const NEW_CARDS = [{"id":"chest-supported-2db","name":"Тяга с опорой грудью (две гантели)","group":"Спина","meta":"gd|","nameEn":"Chest-supported row (two dumbbells)","nameLv":"Vilkme ar krūšu atbalstu (divas hanteles)","lib":["Широчайшие; ромбовидные; средняя трапеция; большая круглая.","Задние дельты; бицепс. Разгибатели позвоночника почти выключены упором.","Горизонтальная тяга с опорой грудью: толщина спины почти без нагрузки на поясницу."],"libEn":["Lats; rhomboids; mid traps; teres major.","Rear delts; biceps. The spinal erectors stay almost unloaded because the chest is supported.","Builds a thick mid-back while the pad keeps the lower back out of the pull."],"libLv":["Platie muguras muskuļi; rombveida muskuļi; trapecveida vidusdaļa; lielais apaļais muskulis.","Aizmugurējie deltveida; bicepss. Muguras atliecēji paliek gandrīz nenoslogoti, jo krūtis ir atbalstītas.","Biezina muguras vidu, kamēr polsteris noņem slodzi no muguras lejasdaļas."],"tech":[["Грудь на наклонной скамье 30–45°. Обе гантели свисают, шея нейтральна.","Одновременная тяга обеих гантелей к нижним рёбрам, лопатки сводятся.","Локти у корпуса, без шрага. Медленный спуск до виса."],["Отрыв груди","тяга к плечам","рывок."],"От виса до локтей у корпуса при груди на подушке."],"techEn":[["Chest on an incline bench set to 30–45°. Both dumbbells hang, neck neutral.","Row both dumbbells at once toward the lower ribs and squeeze the shoulder blades.","Elbows stay by your sides, no shrug. Lower slowly to a hang."],["Chest lifting off the pad","Rowing toward the shoulders","Jerking"],"From a hang to the elbows by your sides, chest staying on the pad."],"techLv":[["Krūtis uz slīpā sola 30–45°. Abas hanteles karājas, kakls neitrāls.","Vienlaicīga abu hanteļu vilkme uz apakšējām ribām, lāpstiņas savilkas.","Elkoņi pie sāniem, bez plecu pacelšanas. Lēna nolaišana līdz karājumam."],["Krūtis atraujas no polstera","Vilkme uz pleciem","Rāviens"],"No karājuma līdz elkoņiem pie sāniem, krūtīm paliekot uz polstera."]},{"id":"chest-supported-1db","name":"Тяга с опорой грудью (одна гантель)","group":"Спина","meta":"gd|","nameEn":"Chest-supported row (one dumbbell)","nameLv":"Vilkme ar krūšu atbalstu (viena hantele)","lib":["Широчайшие; ромбовидные; средняя трапеция; большая круглая рабочей стороны.","Задняя дельта; бицепс. Разгибатели почти выключены упором.","Тяга одной рукой с опорой грудью: большая амплитуда и разгрузка поясницы."],"libEn":["Lats; rhomboids; mid traps; teres major of the working side.","Rear delt; biceps. The erectors stay almost unloaded because of the support.","Lets you row one side and feel the shoulder blade without the lower back helping."],"libLv":["Platie muguras muskuļi; rombveida muskuļi; trapecveida vidusdaļa; darba puses lielais apaļais muskulis.","Aizmugurējais deltveida; bicepss. Atliecēji paliek gandrīz nenoslogoti atbalsta dēļ.","Ļauj vilkt vienu pusi un sajust lāpstiņu, muguras lejasdaļai nepalīdzot."],"tech":[["Грудь на наклонной скамье 30–45°. Одна гантель свисает.","Тяга к бедру, локоть в карман, лопатка сводится.","Локоть у корпуса, без вращения корпуса. Медленный спуск."],["Отрыв груди","скручивание корпуса","шраг."],"От виса до локтя у корпуса."],"techEn":[["Chest on an incline bench set to 30–45°. One dumbbell hangs.","Row toward the hip, elbow into the pocket, shoulder blade pulls in.","Elbow stays by your side, no twisting. Lower slowly."],["Chest lifting off the pad","Twisting the torso","Shrugging"],"From a hang to the elbow by your side."],"techLv":[["Krūtis uz slīpā sola 30–45°. Viena hantele karājas.","Vilkme uz gūžu, elkonis uz aizmugures kabatu, lāpstiņa savilkas.","Elkonis pie sāna, bez rumpja griešanas. Lēna nolaišana."],["Krūtis atraujas no polstera","Rumpja sagriešana","Plecu pacelšana"],"No karājuma līdz elkonim pie sāna."]},{"id":"tbar-row","name":"Тяга Т-грифа","group":"Спина","meta":"g|s","nameEn":"T-bar row","nameLv":"T-stieņa vilkme","lib":["Широчайшие; ромбовидные; средняя трапеция.","Задние дельты; бицепс. Разгибатели спины почти выключены упором в грудь.","Тяжёлая горизонтальная тяга в тренажёре с упором грудью."],"libEn":["Lats; rhomboids; mid traps.","Rear delts; biceps. The spinal erectors stay almost unloaded because the chest is on the pad.","Builds back thickness with a heavy chest-supported row on a stable path."],"libLv":["Platie muguras muskuļi; rombveida muskuļi; trapecveida vidusdaļa.","Aizmugurējie deltveida; bicepss. Muguras atliecēji paliek gandrīz nenoslogoti, jo krūtis ir uz polstera.","Veido muguras biezumu smagā vilkmē ar krūšu atbalstu un stabilu stieņa ceļu."],"tech":[["Грудь на подушке Т-грифа, руки в висе на рукоятке, стопы устойчиво на платформе.","Тяга к низу груди. Узкий хват — больше широчайшие; широкий — больше задние дельты и средняя трапеция.","Сведение лопаток без рывка корпусом."],["Рывок","отрыв груди","округление спины."],"От виса до касания низа груди."],"techEn":[["Chest on the T-bar pad, arms hanging from the handle, feet planted on the platform.","Row to the lower chest. A close grip biases the lats; a wide grip biases the rear delts and mid traps.","Squeeze the shoulder blades without jerking the torso."],["Jerking","Chest lifting off the pad","Rounding the back"],"From a hang until the handle meets the lower chest."],"techLv":[["Krūtis uz T-stieņa polstera, rokas karājas pie roktura, pēdas stabili uz platformas.","Vilkme uz krūšu apakšu. Šaurs tvēriens vairāk noslogo platos muguras muskuļus; plats — aizmugurējos deltveida muskuļus un trapecveida vidusdaļu.","Lāpstiņu savilkšana bez rumpja rāviena."],["Rāviens","Krūtis atraujas no polstera","Muguras noapaļošana"],"No karājuma līdz roktura pieskārienam krūšu apakšai."]},{"id":"close-pulldown","name":"Тяга верхнего блока узким хватом","group":"Спина","meta":"g|","nameEn":"Close-grip lat pulldown","nameLv":"Augšējā bloka vilkme ar šauru tvērienu","lib":["Широчайшие.","Бицепс, плечевая и плечелучевая — больше, чем при широком хвате сверху; большая круглая; ромбовидные.","Вертикальная тяга узким хватом, когда подтягивания ещё тяжелы."],"libEn":["Lats.","Biceps, brachialis, and brachioradialis — more than with a wide overhand grip; teres major; rhomboids.","Builds the lats with a close grip and less swing than a pull-up."],"libLv":["Platie muguras muskuļi.","Bicepss, pleca muskulis un pleca-spieķakaula muskulis — vairāk nekā platā tvērienā no augšas; lielais apaļais muskulis; rombveida muskuļi.","Veido platos muguras muskuļus ar šauru tvērienu un mazāku šūpošanos nekā pievilkšanās."],"tech":[["Нейтральная V-рукоятка, лёгкий наклон назад, плечи опущены.","Тяга к верху груди или грудине, локти вдоль корпуса.","Рукоятка у груди, контроль вверх до растяжения."],["Раскачка","тяга руками без спины."],"От почти прямых рук до рукоятки у грудины."],"techEn":[["Neutral V-handle, a slight lean back, shoulders down.","Pull to the upper chest or the sternum, elbows along your sides.","Handle at the chest, then control the return up into a stretch."],["Swinging","Pulling with the arms and leaving the back out"],"From nearly straight arms to the handle at the sternum."],"techLv":[["Neitrāls V-rokturis, viegls atgāziens, pleci nolaisti.","Vilkme uz krūšu augšu vai krūšu kaulu, elkoņi gar sāniem.","Rokturis pie krūtīm, tad kontrolēta atgriešanās uz augšu līdz iestiepumam."],["Šūpošanās","Vilkšana ar rokām, muguru atstājot ārā"],"No gandrīz taisnām rokām līdz rokturim pie krūšu kaula."]},{"id":"box-jump","name":"Прыжки на ящик","group":"Ноги","meta":"gd|k","nameEn":"Box jump","nameLv":"Lēciens uz kastes","lib":["Квадрицепс; ягодичные (взрывное разгибание бёдер и коленей).","Икры (подошвенное сгибание на отталкивании); задняя поверхность бедра; кор (стабилизация при приземлении).","Взрывной прыжок на ящик. Только для тех, кто уже умеет мягко приземляться."],"libEn":["Quads; glutes (explosive hip and knee extension).","Calves (plantar flexion on the push-off); hamstrings; core (stabilizing the landing).","Trains an explosive jump and a soft landing you step down from."],"libLv":["Četrgalvainais; sēžas muskuļi (sprādzienveida gūžu un ceļu atliekšana).","Ikri (plantārā fleksija atgrūšanās brīdī); augšstilba aizmugure; korpuss (stabilizācija piezemējoties).","Trenē sprādzienveida lēcienu un mīkstu piezemēšanos, no kuras nokāpj ar soli."],"tech":[["Лицом к ящику, стопы примерно на ширине таза, корпус слегка наклонён, руки готовы к маху. Высота ящика такая, чтобы можно было приземлиться мягко в четверть-присед всей стопой на поверхность.","Небольшой контрзамах в четверть-присед, мах руками, взрывное разгибание бёдер, коленей и голеностопов. Приземление на ящик мягко, в четверть-присед: бёдра назад, колени по носкам, вся стопа на ящике, пятки не свисают.","Выпрямиться на ящике до устойчивой стойки. Спуститься шагом, а не спрыгивать вниз: прыжок вниз даёт высокую эксцентрическую нагрузку на ахилл и колени."],["Спрыгивать вниз с ящика","жёсткое приземление на прямые ноги","пятки свисают с края","ящик слишком высокий, если приземление получается в глубокий неконтролируемый присед","завал коленей внутрь","неполная постановка стоп."],"Безопасная высота — та, на которой приземление остаётся мягким в четверть-приседе, грудь поднята, обе стопы целиком на ящике. Не увеличивать ящик ценой техники."],"techEn":[["Face the box, feet about hip-width, torso leaned slightly, arms ready to swing. Choose a height you can land on softly, in a quarter squat, with the whole foot on the surface.","A small countermovement into a quarter squat, an arm swing, then explosive extension of the hips, knees, and ankles. Land on the box softly in a quarter squat: hips back, knees tracking the toes, the whole foot on the box, heels not hanging off.","Stand up on the box into a steady stance. Step down instead of jumping off: a jump down loads the Achilles and the knees hard on the way down."],["Jumping down off the box","Landing hard on straight legs","Heels hanging off the edge","Box too high if the landing drops into a deep, uncontrolled squat","Knees caving in","Not planting the whole foot"],"A safe height is one where the landing stays soft in a quarter squat, chest up, both feet fully on the box. Do not raise the box at the cost of technique."],"techLv":[["Ar seju pret kasti, pēdas apmēram gurnu platumā, rumpis viegli noliekts, rokas gatavas vēzienam. Kastes augstums ir tāds, lai varētu mīksti piezemēties ceturtdaļpietupienā ar visu pēdu uz virsmas.","Neliela pretkustība ceturtdaļpietupienā, roku vēziens, tad sprādzienveida iztaisnošana gūžās, ceļos un potītēs. Piezemēšanās uz kastes ir mīksta, ceturtdaļpietupienā: gurni atpakaļ, ceļi pirkstgalu virzienā, visa pēda uz kastes, papēži nekarājas pāri malai.","Iztaisnošanās uz kastes līdz stabilai stājai. Nokāpšana ar soli, nevis lēciens lejā: lēciens lejā dod lielu ekscentrisku slodzi Ahileja cīpslai un ceļiem."],["Lekt lejā no kastes","Ciets piezemējums uz taisnām kājām","Papēži karājas pāri malai","Kaste par augstu, ja piezemējums iekrīt dziļā, nekontrolētā pietupienā","Ceļi krīt uz iekšu","Nepilna pēdu uzlikšana"],"Drošs augstums ir tāds, kādā piezemējums paliek mīksts ceturtdaļpietupienā, krūtis augšā, abas pēdas pilnībā uz kastes. Nepalielināt kastes augstumu uz tehnikas rēķina."]},{"id":"reverse-lunge","name":"Выпады назад без опоры","group":"Ноги","meta":"gdb|k","nameEn":"Reverse lunge, unsupported","nameLv":"Izklupiens atpakaļ bez balsta","lib":["Квадрицепс и ягодичные передней ноги.","Задняя поверхность бедра; приводящие; средняя ягодичная; кор.","Выпад назад без опоры руками: ноги и баланс."],"libEn":["Quads and glutes of the front leg.","Hamstrings; adductors; glute medius; core.","Builds single-leg strength with a step back that is easier on the front knee."],"libLv":["Priekšējās kājas četrgalvainais un sēžas muskuļi.","Augšstilba aizmugure; pievilcējmuskuļi; vidējais sēžas muskulis; korpuss.","Veido vienas kājas spēku ar soli atpakaļ, kas saudzē priekšējo celi."],"tech":[["Стоя без опоры руками, стопы под бёдрами.","Шаг назад, таз опускается вертикально, передняя пятка на полу.","Оба колена около 90°. Возврат через переднюю стопу."],["Завал колена","короткий шаг","удар задним коленом."],"Оба колена около 90°, передняя пятка на полу."],"techEn":[["Stand with no hand support, feet under the hips.","Step back, hips drop straight down, front heel stays on the floor.","Both knees near 90°. Drive back up through the front foot."],["Knee caving in","Short step","Slamming the back knee"],"Both knees near 90°, front heel on the floor."],"techLv":[["Stāja bez roku balsta, pēdas zem gurniem.","Solis atpakaļ, gurni nolaižas vertikāli, priekšējais papēdis paliek uz grīdas.","Abi ceļi ap 90°. Atgriešanās caur priekšējo pēdu."],["Celis krīt uz iekšu","Īss solis","Sitiens ar aizmugurējo celi"],"Abi ceļi ap 90°, priekšējais papēdis uz grīdas."]},{"id":"single-leg-press","name":"Жим ногами одной ногой","group":"Ноги","meta":"g|k","nameEn":"Single-leg press","nameLv":"Kāju spiediens ar vienu kāju","lib":["Квадрицепс и ягодичная рабочей ноги.","Задняя поверхность бедра; приводящие; средняя ягодичная и кор (антиротация).","Жим одной ногой в тренажёре, когда свободный выпад ещё рано."],"libEn":["Quad and glute of the working leg.","Hamstrings; adductors; glute medius and core (anti-rotation).","Shows which leg is working so the stronger side cannot cover for the other."],"libLv":["Darba kājas četrgalvainais un sēžas muskulis.","Augšstilba aizmugure; pievilcējmuskuļi; vidējais sēžas muskulis un korpuss (pretrotācija).","Parāda, kura kāja dara darbu, lai stiprākā puse nenosegtu otru."],"tech":[["Как в жиме ногами, одна стопа на платформе, таз без перекоса.","Та же линия, что у двуногого жима; таз не разворачивается.","Почти полное разгибание без локаута."],["Перекос таза","отрыв поясницы","завал колена."],"До угла, при котором таз ещё прижат к подушке."],"techEn":[["Set up as in a leg press, one foot on the platform, pelvis level.","Same path as the two-leg press; the pelvis does not twist open.","Nearly full extension without a lockout."],["Pelvis tilting","Lower back lifting off the pad","Knee caving in"],"Only as deep as the angle where the pelvis still stays on the pad."],"techLv":[["Kā kāju spiedienā, viena pēda uz platformas, iegurnis līdzens.","Tā pati līnija kā spiedienā ar abām kājām; iegurnis nepagriežas.","Gandrīz pilna atliekšana bez aizslēgšanas."],["Iegurņa sasvēršanās","Jostas daļa atraujas no polstera","Celis krīt uz iekšu"],"Līdz leņķim, kurā iegurnis vēl turas piespiests polsterim."]},{"id":"seated-calf","name":"Подъёмы на носки сидя","group":"Ноги","meta":"g|","nameEn":"Seated calf raise","nameLv":"Pacelšanās uz pirkstgaliem sēdus","lib":["Камбаловидная.","Икроножная — вклад снижен, потому что колено согнуто около 90°.","Изоляция камбаловидной мышцы сидя."],"libEn":["Soleus.","Gastrocnemius contributes less because the knee is bent to about 90°.","Trains the calf with the knee bent, where a standing raise does not reach the same way."],"libLv":["Pleznas muskulis.","Ikru muskulis dod mazāku ieguldījumu, jo celis ir saliekts ap 90°.","Trenē ikru ar saliektu celi, kur stāvus pacelšanās to nesasniedz tāpat."],"tech":[["Сидя, колени около 90°, передние отделы стоп на платформе, валик на нижних бёдрах.","Пятки вниз, затем подъём на носки. Коленный угол не меняется.","Пауза вверху, медленное опускание."],["Пружина","помощь разгибанием коленей."],"Полная тыльная и подошвенная флексия при фиксированном колене около 90°."],"techEn":[["Sit with the knees near 90°, the balls of the feet on the platform, and the pad across the lower thighs.","Heels down, then rise onto the toes. The knee angle does not change.","Pause at the top, lower slowly."],["Bouncing","Helping by straightening the knees"],"Full dorsiflexion and plantar flexion with the knee fixed near 90°."],"techLv":[["Sēdus, ceļi ap 90°, pēdu priekšdaļa uz platformas, rullis uz augšstilbu lejasdaļas.","Papēži lejā, tad pacelšanās uz pirkstgaliem. Ceļa leņķis nemainās.","Pauze augšā, lēna nolaišana."],["Atsperšanās","Palīdzēšana, atliecot ceļus"],"Pilna dorsālā un plantārā fleksija ar fiksētu celi ap 90°."]},{"id":"standing-db-press","name":"Жим гантелей стоя","group":"Плечи","meta":"gd|p","nameEn":"Standing dumbbell press","nameLv":"Hanteļu spiediens stāvus","lib":["Передние и средние дельты.","Трицепс; кор и ягодичные больше, чем в сидячем жиме.","Жим гантелей над головой стоя: плечи и устойчивость корпуса."],"libEn":["Front and side delts.","Triceps; the core and glutes work more than in a seated press.","Presses the bells overhead while you stay braced on your feet."],"libLv":["Priekšējie un vidējie deltveida.","Tricepss; korpuss un sēžas muskuļi strādā vairāk nekā sēdus spiedienā.","Spiež hanteles virs galvas, kamēr jāturas stingri uz pēdām."],"tech":[["Стоя, гантели у плеч, кор жёсткий.","Жим вверх без подседа и без сильного прогиба.","Гантели над головой близко, без удара. Опускание до ушей."],["Раскачка ногами","прогиб поясницы."],"От уровня ушей до почти прямых рук над головой."],"techEn":[["Stand with the dumbbells at the shoulders and the core braced.","Press overhead without dipping the knees and without a hard arch.","Dumbbells finish close together overhead, without clashing. Lower to ear level."],["Bouncing with the legs","Arching the lower back"],"From ear level to nearly straight arms overhead."],"techLv":[["Stāvus, hanteles pie pleciem, korpuss stingrs.","Spiediens uz augšu bez ietupiena ar kājām un bez stipra izliekuma.","Hanteles virs galvas tuvu kopā, bez sitiena. Nolaišana līdz ausīm."],["Atsperšanās ar kājām","Jostas izliekums"],"No ausu līmeņa līdz gandrīz taisnām rokām virs galvas."]},{"id":"smith-incline-bench","name":"Жим лёжа в Смите (наклонный)","group":"Грудь","meta":"g|p","nameEn":"Smith machine incline bench press","nameLv":"Slīpais guļus spiediens Smitā","lib":["Большая грудная, акцент на ключичной (верхней) порции.","Передние дельты (больше, чем на горизонтальной); трицепс.","Наклонный жим в Смите для верха груди по направляющим."],"libEn":["Pectoralis major, with the emphasis on the clavicular (upper) portion.","Front delts (more than on a flat bench); triceps.","Builds the upper chest on a fixed bar path, with less balancing than a free bar."],"libLv":["Lielais krūšu muskulis, akcents uz atslēgas kaula (augšējo) daļu.","Priekšējie deltveida (vairāk nekā horizontālajā spiedienā); tricepss.","Veido krūšu augšu pa fiksētu stieņa ceļu, ar mazāku balansēšanu nekā ar brīvu stieni."],"tech":[["Спинка скамьи около 30° (рабочий диапазон 15–45°), установленная так, чтобы гриф опускался на верхнюю грудь. Лопатки сведены, страховочные упоры чуть ниже груди.","Опускание к верхней груди по направляющим. Локти 45–75°.","Касание верхней груди без отскока, жим до почти прямых рук."],["Скамья круче 45° сильно смещает нагрузку на передние дельты (ближе к жиму плеч)","жим с шеи","неверная ориентация на наклонной раме."],"Скамья около 30° (рабочий диапазон 15–45°). До касания верхней груди, не с шеи."],"techEn":[["Set the bench near 30° (working range 15–45°) so the bar lowers to the upper chest. Shoulder blades pinched, safeties just below the chest.","Lower to the upper chest along the guides. Elbows at 45–75°.","Touch the upper chest without bouncing, then press to nearly straight arms."],["A bench steeper than 45° shifts the load hard onto the front delts (closer to a shoulder press)","Pressing from the neck","Facing the wrong way on an angled Smith frame"],"Bench near 30° (working range 15–45°). Down to a touch on the upper chest, not off the neck."],"techLv":[["Sola atzveltne ap 30° (darba diapazons 15–45°), novietota tā, lai stienis nolaistos uz krūšu augšu. Lāpstiņas savilktas, drošības atdures nedaudz zem krūtīm.","Nolaišana uz krūšu augšu pa vadotnēm. Elkoņi 45–75°.","Pieskāriens krūšu augšai bez atsitiena, tad spiediens līdz gandrīz taisnām rokām."],["Sols stāvāks par 45° stipri pārnes slodzi uz priekšējiem deltveida muskuļiem (tuvāk plecu spiedienam)","Spiediens no kakla","Nepareiza orientācija uz slīpā Smita rāmja"],"Sols ap 30° (darba diapazons 15–45°). Līdz pieskārienam krūšu augšai, nevis no kakla."]},{"id":"smith-close-grip","name":"Жим узким хватом в Смите","group":"Трицепс","meta":"g|p","nameEn":"Smith machine close-grip bench press","nameLv":"Šaurā tvēriena spiediens Smitā","lib":["Трицепс.","Большая грудная; передние дельты.","Жим узким хватом в Смите с акцентом на трицепс."],"libEn":["Triceps.","Pectoralis major; front delts.","Overloads the triceps on a bench path that cannot drift."],"libLv":["Tricepss.","Lielais krūšu muskulis; priekšējie deltveida.","Pārslogo tricepsu spiediena ceļā, kas nevar aizklīst."],"tech":[["Как в горизонтальном жиме в Смите, хват примерно на ширине плеч, не ладони вместе. Локти ближе к корпусу. Страховочные упоры установлены.","Опускание на нижнюю или среднюю грудь по направляющим, локти вдоль корпуса.","Касание без отскока, жим до почти прямых рук."],["Слишком узкий хват","разлёт локтей","отскок."],"До касания груди и почти полного разгибания. Хват около ширины плеч."],"techEn":[["Same setup as a flat Smith press. Grip about shoulder-width, not palms together. Elbows closer to the sides. Safeties are set.","Lower to the lower or mid chest along the guides, elbows along the torso.","Touch without bouncing, then press to nearly straight arms."],["Grip too narrow","Elbows flaring","Bouncing"],"Down to a chest touch and nearly full extension. Grip about shoulder-width."],"techLv":[["Kā horizontālajā Smita spiedienā. Tvēriens apmēram plecu platumā, nevis plaukstas kopā. Elkoņi tuvāk sāniem. Drošības atdures uzliktas.","Nolaišana uz krūšu apakšu vai vidu pa vadotnēm, elkoņi gar rumpi.","Pieskāriens bez atsitiena, tad spiediens līdz gandrīz taisnām rokām."],["Pārāk šaurs tvēriens","Elkoņi izplešas","Atsitiens"],"Līdz pieskārienam krūtīm un gandrīz pilnai atliekšanai. Tvēriens ap plecu platumu."]},{"id":"smith-split-squat","name":"Выпады / сплит-присед в Смите","group":"Ноги","meta":"g|k","nameEn":"Smith machine lunge / split squat","nameLv":"Izklupiens / dalītais pietupiens Smitā","lib":["Квадрицепс и ягодичные передней ноги.","Приводящие; икры; средняя ягодичная и кор как стабилизаторы (меньше, чем без направляющих).","Сплит-присед в Смите: одна нога, баланс держит рама."],"libEn":["Quads and glutes of the front leg.","Adductors; calves; glute medius and core as stabilizers (less than without the guides).","Holds a split stance on rails so each leg works without a walking step."],"libLv":["Priekšējās kājas četrgalvainais un sēžas muskuļi.","Pievilcējmuskuļi; ikri; vidējais sēžas muskulis un korpuss kā stabilizatori (mazāk nekā bez vadotnēm).","Notur dalītu stāju uz vadotnēm, lai katra kāja strādā bez soļošanas."],"tech":[["Гриф на верхе трапеций. Стопы на месте: передняя чуть впереди линии грифа, задняя сзади. Ходьбы во время повтора нет — фиксированная траектория этому не подходит. Страховочные упоры установлены.","Таз опускается вертикально, оба колена около 90°, передняя пятка на полу.","Подъём через переднюю стопу до почти прямой передней ноги."],["Шаг во время повтора (это не ходьба в выпадах)","завал колена","отрыв передней пятки."],"Оба колена около 90°, передняя пятка на полу."],"techEn":[["Bar on the upper traps. Feet stay put: the front foot slightly ahead of the bar line, the back foot behind. There is no walking during the rep — a fixed path is not for that. Safeties are set.","Hips drop straight down, both knees near 90°, front heel on the floor.","Drive up through the front foot until the front leg is nearly straight."],["Stepping during the rep (this is not a walking lunge)","Knee caving in","Front heel lifting"],"Both knees near 90°, front heel on the floor."],"techLv":[["Stienis uz trapecveida augšdaļas. Pēdas paliek vietā: priekšējā nedaudz pirms stieņa līnijas, aizmugurējā aiz tās. Atkārtojuma laikā nav soļošanas — fiksēta trajektorija tam neder. Drošības atdures uzliktas.","Gurni nolaižas vertikāli, abi ceļi ap 90°, priekšējais papēdis uz grīdas.","Pacelšanās caur priekšējo pēdu līdz gandrīz taisnai priekšējai kājai."],["Solis atkārtojuma laikā (šī nav soļošana izklupienos)","Celis krīt uz iekšu","Priekšējais papēdis atraujas"],"Abi ceļi ap 90°, priekšējais papēdis uz grīdas."]},{"id":"smith-rdl","name":"Румынская тяга в Смите","group":"Ноги","meta":"g|s","nameEn":"Smith machine Romanian deadlift","nameLv":"Rumāņu vilkme Smitā","lib":["Задняя поверхность бедра; ягодичные.","Разгибатели спины; предплечья.","Наклон от таза в Смите для задней поверхности бедра и ягодиц."],"libEn":["Hamstrings; glutes.","Spinal erectors; forearms.","Lengthens and loads the hamstrings on a guided hinge."],"libLv":["Augšstilba aizmugure; sēžas muskuļi.","Muguras atliecēji; apakšdelmi.","Iestiepj un noslogo augšstilba aizmuguri vadītā gūžas locījumā."],"tech":[["Стоя, гриф у бёдер, мягкие колени почти фиксированы, спина нейтральна. Стопы примерно под грифом или с небольшой поправкой на угол рамы.","Таз назад, гриф скользит вдоль бёдер по направляющим.","Остановка, когда таз больше не уходит назад без округления (обычно середина голени). Возврат тазом вперёд."],["Округление поясницы","лишнее сгибание коленей","отрыв грифа от ног."],"До середины голени или до предела шарнира без округления поясницы."],"techEn":[["Stand with the bar at the hips, knees softly bent and nearly fixed, back neutral. Feet about under the bar, or shifted a little for the angle of the frame.","Hips back, the bar sliding along the thighs on the guides.","Stop when the hips cannot travel farther back without rounding (usually mid-shin). Return by driving the hips forward."],["Rounding the lower back","Extra knee bend","Bar leaving the legs"],"To mid-shin, or to the limit of the hinge without rounding the lower back."],"techLv":[["Stāvus, stienis pie gurniem, ceļi mīksti saliekti un gandrīz fiksēti, mugura neitrāla. Pēdas apmēram zem stieņa vai ar nelielu pārbīdi atbilstoši rāmja leņķim.","Gurni atpakaļ, stienis slīd gar augšstilbiem pa vadotnēm.","Apstāties, kad gurni vairs neiet atpakaļ bez noapaļošanas (parasti apakšstilba vidus). Atgriešanās, virzot gurnus uz priekšu."],["Jostas noapaļošana","Lieka ceļu saliekšana","Stienis atraujas no kājām"],"Līdz apakšstilba vidum vai līdz gūžas locījuma robežai bez jostas noapaļošanas."]},{"id":"smith-calf","name":"Подъёмы на носки стоя в Смите","group":"Ноги","meta":"g|","nameEn":"Smith machine standing calf raise","nameLv":"Pacelšanās uz pirkstgaliem stāvus Smitā","lib":["Икроножные.","Камбаловидные (колено разогнуто).","Подъём на носки стоя в Смите."],"libEn":["Gastrocnemius.","Soleus (the knee is extended).","Raises the heels under a bar that cannot tip, through a full ankle range."],"libLv":["Ikru muskulis.","Pleznas muskulis (celis ir atliekts).","Ceļ papēžus zem stieņa, kas nevar apgāzties, pa pilnu potītes amplitūdu."],"tech":[["Гриф на верхе трапеций. Передние отделы стоп на платформе или блине, колени почти прямые, но не запертые. Страховочные упоры чуть ниже нижней точки растяжения.","Пятки опускаются в тыльное сгибание, затем подъём на носки до полного подошвенного сгибания.","Пауза вверху, медленное опускание."],["Пружина","сгиб коленей в помощь","короткая амплитуда."],"Полная тыльная и подошвенная флексия на платформе, безболевой диапазон ахилла."],"techEn":[["Bar on the upper traps. Balls of the feet on a platform or a plate, knees nearly straight but not locked. Safeties just below the bottom of the stretch.","Lower the heels into dorsiflexion, then rise onto the toes to full plantar flexion.","Pause at the top, lower slowly."],["Bouncing","Bending the knees to help","Short range"],"Full dorsiflexion and plantar flexion on the platform, inside a pain-free Achilles range."],"techLv":[["Stienis uz trapecveida augšdaļas. Pēdu priekšdaļa uz platformas vai diska, ceļi gandrīz taisni, bet nav aizslēgti. Drošības atdures nedaudz zem apakšējā iestiepuma.","Papēži nolaižas dorsālajā fleksijā, tad pacelšanās uz pirkstgaliem līdz pilnai plantārajai fleksijai.","Pauze augšā, lēna nolaišana."],["Atsperšanās","Ceļu saliekšana palīgā","Īsa amplitūda"],"Pilna dorsālā un plantārā fleksija uz platformas, Ahileja cīpslas bezsāpju diapazonā."]},{"id":"smith-row","name":"Тяга в наклоне в Смите","group":"Спина","meta":"g|s","nameEn":"Smith machine bent-over row","nameLv":"Vilkme noliekusies Smitā","lib":["Широчайшие; ромбовидные; средняя трапеция.","Задние дельты; бицепс; разгибатели спины (изометрия наклона).","Тяга в наклоне по направляющим Смита."],"libEn":["Lats; rhomboids; mid traps.","Rear delts; biceps; spinal erectors (isometric hold of the hinge).","Rows to the lower ribs on a fixed path so the bar cannot drift off the target."],"libLv":["Platie muguras muskuļi; rombveida muskuļi; trapecveida vidusdaļa.","Aizmugurējie deltveida; bicepss; muguras atliecēji (noliekuma izometrija).","Velk uz ribu apakšu pa fiksētu ceļu, lai stienis neaizklīst no mērķa."],"tech":[["Шарнир, спина нейтральна. Угол корпуса подбирают так, чтобы фиксированный ход грифа приходился к низу рёбер, а не к коленям или к шее.","Тяга к низу рёбер вдоль направляющих, лопатки сводятся.","Гриф у корпуса, контролируемое опускание до почти прямых рук."],["Рывок поясницей","округление спины","туловище под таким углом, что гриф идёт мимо точки контакта."],"От почти прямых рук до касания низа рёбер при нейтральной спине."],"techEn":[["Hinge with a neutral back. Set the torso angle so the fixed bar path meets the lower ribs, not the knees or the neck.","Row to the lower ribs along the guides and squeeze the shoulder blades.","Bar at the torso, then a controlled lower to nearly straight arms."],["Jerking with the lower back","Rounding the back","Torso angled so the bar misses the contact point"],"From nearly straight arms to a touch at the lower ribs, with a neutral back."],"techLv":[["Gūžas locījums, mugura neitrāla. Rumpja leņķi izvēlas tā, lai fiksētais stieņa ceļš trāpītu ribu apakšā, nevis ceļos vai kaklā.","Vilkme uz ribu apakšu gar vadotnēm, lāpstiņas savilkas.","Stienis pie rumpja, tad kontrolēta nolaišana līdz gandrīz taisnām rokām."],["Rāviens ar jostas daļu","Muguras noapaļošana","Rumpis tādā leņķī, ka stienis iet garām saskares punktam"],"No gandrīz taisnām rokām līdz pieskārienam ribu apakšai ar neitrālu muguru."]},{"id":"smith-shrug","name":"Шраги в Смите","group":"Спина","meta":"g|","nameEn":"Smith machine shrug","nameLv":"Šragi Smitā","lib":["Верх трапеций.","Мышца, поднимающая лопатку; предплечья (хват).","Изоляция верха трапеций в Смите."],"libEn":["Upper traps.","Levator scapulae; forearms (grip).","Shrugs straight up and down so the shoulders lift without rolling."],"libLv":["Trapecveida augšdaļa.","Lāpstiņas cēlājmuskulis; apakšdelmi (tvēriens).","Ceļ plecus taisni augšup un lejup, bez ripināšanas."],"tech":[["Стоя, гриф в опущенных руках перед бёдрами, руки прямые. Стопы так, чтобы гриф мог идти вверх вдоль тела, а не в бёдра.","Прямой подъём плеч вверх по направляющим и опускание. Без вращения плечами.","Максимальное поднятие лопаток, пауза, медленный спуск."],["Круговые вращения плечами","сгиб локтей","раскачка."],"Только подъём и опускание лопаток по линии рамы, в безболевом диапазоне."],"techEn":[["Stand with the bar in straight arms in front of the thighs. Set the feet so the bar can travel up along the body, not into the hips.","Lift the shoulders straight up along the guides and lower them. No shoulder circles.","Lift the shoulder blades as high as you can, pause, then lower slowly."],["Circling the shoulders","Bending the elbows","Swinging"],"Only raise and lower the shoulder blades along the frame, in a pain-free range."],"techLv":[["Stāvus, stienis taisnās rokās priekšā augšstilbiem. Pēdas tā, lai stienis varētu iet uz augšu gar ķermeni, nevis gurnos.","Taisna plecu pacelšana pa vadotnēm un nolaišana. Bez plecu apļiem.","Maksimāla lāpstiņu pacelšana, pauze, lēna nolaišana."],["Plecu apļošana","Elkoņu saliekšana","Šūpošanās"],"Tikai lāpstiņu pacelšana un nolaišana pa rāmja līniju, bezsāpju diapazonā."]},{"id":"hack-squat","name":"Гакк-присед","group":"Ноги","meta":"g|k","nameEn":"Hack squat","nameLv":"Haka pietupiens","lib":["Квадрицепс.","Ягодичные; приводящие. Спина опирается на подушку, поэтому разгибатели спины и кор стабилизируют меньше, чем в свободном приседе.","Присед в гакк-тренажёре: тяжёлая работа ног при опоре спины."],"libEn":["Quads.","Glutes; adductors. The back rests on the pad, so the spinal erectors and core stabilize less than in a free squat.","Loads the squat while the pad carries the back."],"libLv":["Četrgalvainais.","Sēžas muskuļi; pievilcējmuskuļi. Mugura balstās uz polstera, tāpēc muguras atliecēji un korpuss stabilizē mazāk nekā brīvā pietupienā.","Noslogo pietupienu, kamēr polsteris nes muguru."],"tech":[["Спина и таз к подушке, плечи под валиками, стопы на платформе примерно на ширине плеч. Поясница не отрывается.","Сгибание коленей и бёдер по направляющим салазок, колени по носкам, пятки на платформе.","До параллели или чуть ниже, пока таз прижат. Выжим без удара в стопор и без полного «запирания», если это бьёт по коленям."],["Отрыв поясницы","колени внутрь","удар в стопор."],"До параллели или ниже при прижатом тазе. Не форсировать глубину ценой округления поясницы."],"techEn":[["Back and pelvis against the pad, shoulders under the shoulder pads, feet on the platform about shoulder-width. The lower back does not lift off.","Bend the knees and hips along the sled rails, knees tracking the toes, heels on the platform.","To parallel or a little below, as long as the pelvis stays pressed in. Drive up without banging the stops and without a full lockout if that bothers the knees."],["Lower back lifting off","Knees caving in","Hitting the stops"],"To parallel or below with the pelvis pressed in. Do not chase depth by rounding the lower back."],"techLv":[["Mugura un iegurnis pret polsteri, pleci zem plecu polsteriem, pēdas uz platformas apmēram plecu platumā. Jostas daļa neatraujas.","Ceļu un gūžu saliekšana pa ragavu sliedēm, ceļi pirkstgalu virzienā, papēži uz platformas.","Līdz paralēlei vai nedaudz zemāk, kamēr iegurnis ir piespiests. Izspiešana bez sitiena pret atduri un bez pilnas aizslēgšanas, ja tā sit pa ceļiem."],["Jostas daļa atraujas","Ceļi krīt uz iekšu","Sitiens pret atduri"],"Līdz paralēlei vai zemāk ar piespiestu iegurni. Nedzīt dziļumu, noapaļojot jostas daļu."]},{"id":"hip-abduction","name":"Отведение бедра в тренажёре","group":"Ноги","meta":"g|","nameEn":"Hip abduction machine","nameLv":"Gūžas atvilkšana trenažierī","lib":["Средняя и малая ягодичные.","Напрягатель широкой фасции.","Изоляция средней ягодичной в тренажёре."],"libEn":["Glute medius and glute minimus.","Tensor fasciae latae.","Strengthens the side of the hips so the pelvis stays level on one leg."],"libLv":["Vidējais un mazais sēžas muskulis.","Augšstilba platās fascijas stingrinātājs.","Stiprina gurnu sānus, lai iegurnis paliek līdzens uz vienas kājas."],"tech":[["Сидя в тренажёре для отведения, спина к подушке, подушки снаружи коленей или бёдер, таз прижат.","Разведение бёдер против сопротивления, без отрыва таза и без наклона корпуса в сторону.","Комфортная амплитуда отведения, короткая пауза, медленное сведение."],["Отрыв таза","рывок","вращение корпусом."],"До комфортного отведения без боли в тазобедренном суставе или пояснице."],"techEn":[["Sit in the abduction machine, back against the pad, pads outside the knees or thighs, pelvis pressed in.","Spread the thighs against the resistance without lifting the pelvis or leaning the torso sideways.","A comfortable abduction range, a short pause, then a slow return."],["Pelvis lifting off","Jerking","Twisting with the torso"],"To a comfortable abduction without pain in the hip or the lower back."],"techLv":[["Sēdus atvilkšanas trenažierī, mugura pret polsteri, polsteri no ārpuses pie ceļiem vai augšstilbiem, iegurnis piespiests.","Augšstilbu atvēršana pret pretestību, neatraujot iegurni un nenoliecot rumpi uz sāniem.","Ērta atvilkšanas amplitūda, īsa pauze, lēna atgriešanās."],["Iegurnis atraujas","Rāviens","Griešana ar rumpi"],"Līdz ērtai atvilkšanai bez sāpēm gūžas locītavā vai jostas daļā."]},{"id":"reverse-hyper","name":"Обратная гиперэкстензия","group":"Ноги","meta":"g|s","nameEn":"Reverse hyperextension","nameLv":"Apgrieztā hiperekstensija","lib":["Ягодичные; задняя поверхность бедра.","Разгибатели спины.","Разгибание бёдер в обратной гиперэкстензии."],"libEn":["Glutes; hamstrings.","Spinal erectors.","Extends the hips with the trunk supported so the back does not take the load."],"libLv":["Sēžas muskuļi; augšstilba aizmugure.","Muguras atliecēji.","Atliec gūžas ar atbalstītu rumpi, lai mugura neuzņem slodzi."],"tech":[["Живот и таз на подушке тренажёра обратной гиперэкстензии, ноги свисают вниз, руками держаться за рукоятки. Позвоночник нейтрален.","Подъём ног назад-вверх за счёт разгибания бёдер, без сильного прогиба поясницы.","Ноги примерно до линии корпуса или чуть выше без гиперлордоза. Контролируемое опускание."],["Раскачка как на качелях с прогибом поясницы","сгибание коленей вместо разгибания бёдер."],"До линии корпуса или чуть выше без боли в пояснице."],"techEn":[["Belly and pelvis on the reverse-hyper pad, legs hanging down, hands on the handles. Spine neutral.","Lift the legs back and up by extending the hips, without a hard arch in the lower back.","Legs to about the line of the torso or a little higher, without an excessive lower-back arch. Lower under control."],["Swinging like a pendulum while arching the lower back","Bending the knees instead of extending the hips"],"To the line of the torso or a little higher, without lower-back pain."],"techLv":[["Vēders un iegurnis uz apgrieztās hiperekstensijas polstera, kājas karājas lejā, rokas tur rokturus. Mugurkauls neitrāls.","Kāju pacelšana atpakaļ un augšup, atliecot gūžas, bez stipra jostas izliekuma.","Kājas apmēram līdz rumpja līnijai vai nedaudz augstāk, bez pārmērīga jostas izliekuma. Kontrolēta nolaišana."],["Šūpošanās kā šūpolēs ar jostas izliekumu","Ceļu saliekšana gūžu atliekšanas vietā"],"Līdz rumpja līnijai vai nedaudz augstāk bez sāpēm jostas daļā."]},{"id":"standing-single-leg-curl","name":"Сгибания ног стоя одной ногой","group":"Ноги","meta":"g|","nameEn":"Standing single-leg curl","nameLv":"Kāju saliekšana stāvus ar vienu kāju","lib":["Задняя поверхность бедра рабочей ноги.","Икры (икроножная как сгибатель колена).","Изоляция задней поверхности бедра одной ногой стоя."],"libEn":["Hamstrings of the working leg.","Calves (gastrocnemius, as a knee flexor).","Curls one knee so the other leg cannot share the work."],"libLv":["Darba kājas augšstilba aizmugure.","Ikri (ikru muskulis kā ceļa saliecējs).","Saliec vienu celi, lai otra kāja nevar dalīt darbu."],"tech":[["Стоя в тренажёре, валик на нижней трети голени рабочей ноги, таз стабилен, опорная нога почти прямая.","Сгибание только рабочего колена по дуге, бедро не уходит вперёд и не поднимается как мах.","Полное сгибание в доступной амплитуде, медленное разгибание почти до прямой ноги."],["Раскачка тазом","мах всей ногой в тазобедренном","рывок."],"От почти прямой ноги до полного сгибания без потери нейтрали таза."],"techEn":[["Stand in the machine with the pad on the lower third of the working shin, pelvis steady, support leg nearly straight.","Curl only the working knee along the arc. The thigh does not drift forward and does not swing up.","Full flexion through the available range, then a slow extension to a nearly straight leg."],["Rocking the pelvis","Swinging the whole leg from the hip","Jerking"],"From a nearly straight leg to full flexion without losing a level pelvis."],"techLv":[["Stāvus trenažierī, rullis uz darba kājas apakšstilba apakšējās trešdaļas, iegurnis stabils, atbalsta kāja gandrīz taisna.","Saliecas tikai darba celis pa loku. Augšstilbs neaiziet uz priekšu un nepaceļas kā vēziens.","Pilna saliekšana pieejamajā amplitūdā, tad lēna atliekšana gandrīz līdz taisnai kājai."],["Iegurņa šūpošana","Visas kājas vēziens no gūžas","Rāviens"],"No gandrīz taisnas kājas līdz pilnai saliekšanai, nezaudējot līdzenu iegurni."]},{"id":"decline-db-press","name":"Жим гантелей на наклонной вниз","group":"Грудь","meta":"gd|","nameEn":"Decline dumbbell press","nameLv":"Hanteļu spiediens uz leju slīpa sola","lib":["Большая грудная, относительно больший акцент на нижних (грудино-рёберных и брюшных) волокнах, чем на горизонтальной или наклонной вверх скамье.","Передние дельты; трицепс.","Жим гантелей головой вниз, акцент на нижнюю часть груди."],"libEn":["Pectoralis major, with relatively more emphasis on the lower (sternocostal and abdominal) fibers than on a flat or incline bench.","Front delts; triceps.","Presses the lower chest on a decline, with each arm free to find its own path."],"libLv":["Lielais krūšu muskulis, salīdzinoši lielāks akcents uz apakšējām (krūškaula-ribu un vēdera) šķiedrām nekā uz horizontāla vai augšup slīpa sola.","Priekšējie deltveida; tricepss.","Spiež krūšu apakšu uz leju slīpa sola, katrai rokai atrodot savu ceļu."],"tech":[["Скамья наклонена вниз обычно на 15–30°. Стопы зафиксированы, лопатки сведены, гантели над нижней или средней грудью.","Опускание к линии нижней груди, локти 45–70°. Вверху гантели сближаются без удара.","Почти прямые руки без потери сведения лопаток."],["Слишком крутой спад, если кровь сильно приливает к голове","отрыв лопаток","удар гантелей."],"Опускать до растяжения груди без вываливания плеча вперёд. Наклон скамьи 15–30°."],"techEn":[["Bench declined, usually 15–30°. Feet locked in, shoulder blades pinched, dumbbells over the lower or mid chest.","Lower toward the lower-chest line, elbows at 45–70°. At the top the dumbbells come together without clashing.","Nearly straight arms without losing the shoulder-blade pinch."],["Decline too steep if blood rushes hard to the head","Shoulder blades lifting off","Dumbbells clashing"],"Lower to a chest stretch without the shoulder dumping forward. Bench angle 15–30°."],"techLv":[["Sols nolaists uz leju, parasti 15–30°. Pēdas fiksētas, lāpstiņas savilktas, hanteles virs krūšu apakšas vai vidus.","Nolaišana uz krūšu apakšas līniju, elkoņi 45–70°. Augšā hanteles satuvinās bez sitiena.","Gandrīz taisnas rokas, nezaudējot lāpstiņu savilkumu."],["Pārāk stāvs slīpums, ja asinis stipri sakāpj galvā","Lāpstiņas atraujas","Hanteļu sitiens"],"Laist lejā līdz krūšu iestiepumam, plecam neizkrītot uz priekšu. Sola slīpums 15–30°."]},{"id":"straight-arm-pulldown","name":"Пуловер на блоке прямыми руками","group":"Спина","meta":"g|","nameEn":"Straight-arm cable pulldown","nameLv":"Taisno roku vilkme uz bloka","lib":["Широчайшие (как разгибатели плеча).","Большая круглая; длинная головка трицепса; задние дельты; большая грудная участвует в разгибании плеча, но не должна перехватывать движение.","Пуловер прямыми руками: широчайшие без сгибания локтей."],"libEn":["Lats (as shoulder extensors).","Teres major; the long head of the triceps; rear delts. Pectoralis major helps extend the shoulder, but it should not take over the movement.","Pulls the arms down in a long arc so the back works without an elbow curl."],"libLv":["Platie muguras muskuļi (kā pleca atliecēji).","Lielais apaļais muskulis; tricepsa garā galva; aizmugurējie deltveida. Lielais krūšu muskulis palīdz atliekt plecu, bet nedrīkst pārņemt kustību.","Velk rokas lejup pa garu loku, lai mugura strādā bez elkoņa saliekuma."],"tech":[["Стоя лицом к верхнему блоку, прямая рукоять или канат, руки почти прямые, лёгкий фиксированный сгиб локтей, корпус слегка наклонён, грудь раскрыта.","Дуга от уровня выше головы к бёдрам за счёт разгибания плеча. Локти не сгибаются как в тяге верхнего блока.","Кисти у бёдер, широчайшие сжаты. Контролируемый возврат по той же дуге."],["Превращение в жим вниз трицепсом (локти сильно сгибаются)","раскачка корпусом."],"От рук выше головы до рукояти у бёдер при почти постоянном угле локтя."],"techEn":[["Face the high cable with a straight bar or a rope. Arms nearly straight, a slight fixed bend in the elbows, torso leaned a little, chest open.","An arc from above the head down to the hips by extending the shoulder. The elbows do not bend the way they do in a lat pulldown.","Hands at the hips, lats squeezed. Return under control along the same arc."],["Turning it into a triceps pushdown (elbows bending a lot)","Swinging the torso"],"From the arms above the head to the handle at the hips, with the elbow angle nearly constant."],"techLv":[["Ar seju pret augšējo bloku, taisns rokturis vai virve. Rokas gandrīz taisnas, viegls fiksēts elkoņu saliekums, rumpis nedaudz noliekts, krūtis atvērtas.","Loks no līmeņa virs galvas uz gurniem, atliecot plecu. Elkoņi nelokās tā, kā augšējā bloka vilkmē.","Plaukstas pie gurniem, platie muguras muskuļi saspiesti. Kontrolēta atgriešanās pa to pašu loku."],["Pārvēršana par tricepsa spiedienu lejup (elkoņi stipri saliecas)","Šūpošanās ar rumpi"],"No rokām virs galvas līdz rokturim pie gurniem, ar gandrīz nemainīgu elkoņa leņķi."]},{"id":"pendlay-row","name":"Тяга Пендли","group":"Спина","meta":"g|s","nameEn":"Pendlay row","nameLv":"Pendlija vilkme","lib":["Широчайшие; ромбовидные; средняя трапеция.","Задние дельты; бицепс; разгибатели спины держат горизонтальный корпус.","Взрывная тяга с пола при горизонтальном корпусе. Для опытных."],"libEn":["Lats; rhomboids; mid traps.","Rear delts; biceps; the spinal erectors hold the torso horizontal.","Pulls from a dead stop with the chest kept parallel to the floor."],"libLv":["Platie muguras muskuļi; rombveida muskuļi; trapecveida vidusdaļa.","Aizmugurējie deltveida; bicepss; muguras atliecēji tur rumpi horizontāli.","Velk no pilnas apstāšanās, krūtīm paliekot paralēli grīdai."],"tech":[["Штанга на полу. Корпус примерно параллелен полу, спина нейтральна, хват сверху чуть шире плеч. Каждое повторение начинается с мёртвой точки на полу.","Взрывная тяга к низу груди / верху живота, лопатки сводятся. Корпус не поднимается вместе с грифом.","Гриф касается корпуса, затем контролируемо возвращается на пол до полной остановки."],["Отрыв корпуса вверх (это уже тяга в наклоне с читингом)","не ставить гриф на пол","округление поясницы."],"От пола до касания низа груди при корпусе параллельно полу."],"techEn":[["Bar on the floor. Torso about parallel to the floor, back neutral, overhand grip slightly wider than the shoulders. Every rep starts from a dead stop on the floor.","An explosive pull to the lower chest or the upper belly, shoulder blades squeeze. The torso does not rise with the bar.","The bar touches the torso, then returns to the floor under control until it is fully stopped."],["Torso rising (that is a cheated bent-over row)","Not setting the bar on the floor","Rounding the lower back"],"From the floor to a touch at the lower chest, torso parallel to the floor."],"techLv":[["Stienis uz grīdas. Rumpis apmēram paralēls grīdai, mugura neitrāla, tvēriens no augšas nedaudz platāks par pleciem. Katrs atkārtojums sākas no pilnas apstāšanās uz grīdas.","Sprādzienveida vilkme uz krūšu apakšu vai vēdera augšu, lāpstiņas savilkas. Rumpis nepaceļas kopā ar stieni.","Stienis pieskaras rumpim, tad kontrolēti atgriežas uz grīdas līdz pilnai apstājai."],["Rumpis ceļas augšup (tā jau ir vilkme noliekusies ar šūpošanu)","Stienis netiek nolikts uz grīdas","Jostas noapaļošana"],"No grīdas līdz pieskārienam krūšu apakšai, rumpim paralēli grīdai."]},{"id":"reverse-pec-deck","name":"Обратные разведения в тренажёре","group":"Плечи","meta":"g|","nameEn":"Reverse pec deck","nameLv":"Apgrieztā izvēršana trenažierī","lib":["Задние дельты.","Ромбовидные; средняя трапеция.","Изоляция задних дельт в тренажёре."],"libEn":["Rear delts.","Rhomboids; mid traps.","Opens the arms out to the side so the back of the shoulder works, not a row."],"libLv":["Aizmugurējie deltveida.","Rombveida muskuļi; trapecveida vidusdaļa.","Ver rokas uz sāniem, lai strādā pleca aizmugure, nevis vilkme."],"tech":[["Сидя лицом к тренажёру, грудь к подушке, предплечья на подушках, локти слегка согнуты и фиксированы.","Горизонтальное отведение рук в линии плеч. Это не тяга: локоть не сгибается сильнее.","Плечо на линии корпуса или чуть дальше без шрага. Медленный возврат."],["Шраг","превращение в тягу со сгибом локтей","отрыв груди от подушки."],"До линии корпуса без боли впереди плеча."],"techEn":[["Sit facing the machine, chest on the pad, forearms on the pads, elbows slightly bent and fixed.","Raise the arms out horizontally in line with the shoulders. This is not a row: the elbow does not bend more.","Upper arm in line with the torso or a little past it, no shrug. Return slowly."],["Shrugging","Turning it into a row by bending the elbows","Chest lifting off the pad"],"To the line of the torso, without pain at the front of the shoulder."],"techLv":[["Sēdus ar seju pret trenažieri, krūtis pret polsteri, apakšdelmi uz polsteriem, elkoņi viegli saliekti un fiksēti.","Horizontāla roku atvilkšana plecu līnijā. Šī nav vilkme: elkonis nesaliecas vairāk.","Augšdelms rumpja līnijā vai nedaudz tālāk, bez plecu pacelšanas. Lēna atgriešanās."],["Plecu pacelšana","Pārvēršana par vilkmi, saliecot elkoņus","Krūtis atraujas no polstera"],"Līdz rumpja līnijai bez sāpēm pleca priekšpusē."]},{"id":"cable-external-rotation","name":"Наружная ротация на блоке","group":"Плечи","meta":"g|p","nameEn":"Cable external rotation","nameLv":"Ārējā rotācija uz bloka","lib":["Подостная и малая круглая (наружные ротаторы плеча).","Задняя дельта как вспомогательная.","Лёгкая работа наружных вращателей плеча. Не основной подход."],"libEn":["Infraspinatus and teres minor (the external rotators of the shoulder).","Rear delt as an assistant.","Turns the shoulder outward with the elbow pinned, a small move that steadies the joint."],"libLv":["Zemšķautnes muskulis un mazais apaļais muskulis (pleca ārējie rotatori).","Aizmugurējais deltveida kā palīgs.","Griež plecu uz āru ar piespiestu elkoni — neliela kustība, kas nostiprina locītavu."],"tech":[["Стоя боком к блоку на уровне локтя, рабочая рука дальняя от блока, локоть прижат к корпусу и согнут 90°, предплечье направлено к животу, полотенце между локтем и боком помогает не отводить плечо. Трос тянет предплечье к животу — наружная ротация идёт против сопротивления.","Предплечье вращается наружу вокруг оси плеча. Плечо и локоть не отъезжают от корпуса.","Предплечье примерно вперёд или чуть наружу, без боли. Медленный возврат."],["Отведение локтя","превращение в тягу или мах","слишком большой вес."],"В безболевом диапазоне наружной ротации, обычно около 45–90° от живота вперёд, индивидуально."],"techEn":[["Stand side-on to the cable at elbow height. The working arm is the one farther from the stack, elbow pinned to the side and bent 90°, forearm toward the belly. A towel between the elbow and the side helps keep the shoulder from drifting out. The cable pulls the forearm toward the belly, so external rotation works against that pull.","The forearm rotates outward around the shoulder. The shoulder and the elbow do not drift off the side.","Forearm about forward or slightly outward, without pain. Return slowly."],["Elbow drifting out","Turning it into a row or a swing","Too much weight"],"A pain-free external-rotation range, usually about 45–90° from the belly toward the front, and it varies by person."],"techLv":[["Stāvus sāniski pret bloku elkoņa augstumā. Darba roka ir tālākā no bloka, elkonis piespiests sānam un saliekts 90°, apakšdelms vērsts uz vēderu. Dvielis starp elkoni un sānu palīdz neaizvirzīt plecu no sāna. Trose velk apakšdelmu uz vēderu, tāpēc ārējā rotācija iet pret šo vilkmi.","Apakšdelms griežas uz āru ap pleca asi. Plecs un elkonis neaiziet no sāna.","Apakšdelms apmēram uz priekšu vai nedaudz uz āru, bez sāpēm. Lēna atgriešanās."],["Elkonis aiziet uz sāniem","Pārvēršana par vilkmi vai vēzienu","Pārāk liels svars"],"Bezsāpju ārējās rotācijas diapazons, parasti ap 45–90° no vēdera uz priekšu, un tas ir individuāli."]},{"id":"concentration-curl","name":"Концентрированные сгибания","group":"Бицепс","meta":"gd|","nameEn":"Concentration curl","nameLv":"Koncentrētais bicepsa saliekums","lib":["Бицепс.","Плечевая; предплечья.","Строгая изоляция бицепса сидя."],"libEn":["Biceps.","Brachialis; forearms.","Curls one arm with the elbow braced so the body cannot swing the weight up."],"libLv":["Bicepss.","Pleca muskulis; apakšdelmi.","Saliec vienu roku ar atbalstītu elkoni, lai ķermenis nevar iešūpot svaru."],"tech":[["Сидя, наклон вперёд, локоть рабочей руки упирается во внутреннюю поверхность бедра, гантель внизу, плечо вертикально.","Сгибание только в локте, без раскачки корпуса и без подъёма локтя с бедра.","Полное сгибание, медленное опускание до почти прямой руки."],["Отрыв локтя от бедра","читинг корпусом."],"От почти прямой руки до полного сгибания при фиксированном локте."],"techEn":[["Sit leaning forward. The working elbow braces on the inner thigh, dumbbell down, upper arm vertical.","Curl only at the elbow, no torso swing and no lifting the elbow off the thigh.","A full curl, then a slow lower to a nearly straight arm."],["Elbow leaving the thigh","Cheating with the torso"],"From a nearly straight arm to a full curl, with the elbow fixed."],"techLv":[["Sēdus, noliekums uz priekšu. Darba rokas elkonis atbalstās pret augšstilba iekšpusi, hantele apakšā, augšdelms vertikāli.","Saliekšana tikai elkonī, bez rumpja šūpošanas un nepaceļot elkoni no augšstilba.","Pilns saliekums, tad lēna nolaišana līdz gandrīz taisnai rokai."],["Elkonis atraujas no augšstilba","Palīdzēšana ar rumpja šūpošanu"],"No gandrīz taisnas rokas līdz pilnam saliekumam ar fiksētu elkoni."]},{"id":"cable-overhead-extension","name":"Разгибания из-за головы на блоке","group":"Трицепс","meta":"g|","nameEn":"Cable overhead triceps extension","nameLv":"Tricepsa atliekšana no aiz galvas uz bloka","lib":["Длинная головка трицепса растянута из-за положения плеча вверх; работают все три головки.","Локтевая мышца; стабилизаторы плеча.","Разгибание трицепса из-за головы, длинная головка в растяжении."],"libEn":["The long head of the triceps is stretched by the overhead shoulder position; all three heads work.","Anconeus; shoulder stabilizers.","Straightens the elbows from behind the head, where a pushdown cannot put the stretch."],"libLv":["Tricepsa garā galva ir iestiepta, jo plecs ir virs galvas; strādā visas trīs galvas.","Elkoņa muskulis; pleca stabilizatori.","Iztaisno elkoņus no aiz galvas, kur spiediens lejup šādu iestiepumu nedod."],"tech":[["Стоя спиной к блоку или слегка в наклоне, канат (реже прямая рукоять) над головой, локти направлены вверх и зафиксированы рядом с головой.","Разгибание только в локтях, концы каната расходятся вперёд-вверх.","Почти прямые руки над головой без удара. Возврат за голову до комфортного сгибания."],["Разъезд локтей","прогиб поясницы","движение в плече как в пуловере."],"За голову до растяжения без боли в локте и плече, затем до почти прямых рук."],"techEn":[["Stand with your back to the cable, or in a slight lean. Rope overhead (a straight bar less often), elbows pointing up and fixed beside the head.","Extend only at the elbows. The rope ends spread forward and up.","Nearly straight arms overhead, without snapping. Return behind the head to a comfortable bend."],["Elbows flaring apart","Arching the lower back","Moving at the shoulder, as in a pullover"],"Behind the head to a stretch without elbow or shoulder pain, then out to nearly straight arms."],"techLv":[["Stāvus ar muguru pret bloku vai vieglā noliekumā. Virve virs galvas (retāk taisns rokturis), elkoņi vērsti uz augšu un fiksēti pie galvas.","Atliekšana tikai elkoņos. Virves gali izplūst uz priekšu un augšu.","Gandrīz taisnas rokas virs galvas, bez sitiena. Atgriešanās aiz galvas līdz ērtai saliekšanai."],["Elkoņi izplešas","Jostas izliekums","Kustība plecā, kā puloverā"],"Aiz galvas līdz iestiepumam bez sāpēm elkonī un plecā, tad līdz gandrīz taisnām rokām."]},{"id":"ankle-knee-to-wall","name":"Подвижность голеностопа (колено к стене)","group":"Разминка","meta":"gdb|","nameEn":"Ankle mobility (knee to wall)","nameLv":"Potītes kustīgums (celis pie sienas)","lib":["Камбаловидная и ахиллов комплекс передней ноги растягиваются: колено согнуто, поэтому двусуставная икроножная натянута меньше, чем при прямой ноге.","Икроножная, если колено почти прямое; передняя большеберцовая помогает тянуть голень в тыльное сгибание.","Проверка и мягкая проработка подвижности голеностопа."],"libEn":["The soleus and the Achilles complex of the front leg are stretched. The knee is bent, so the two-joint gastrocnemius is under less tension than with a straight leg.","Gastrocnemius, if the knee is nearly straight; tibialis anterior helps pull the shin into dorsiflexion.","Frees ankle bend so the heels can stay down in squats and lunges."],"libLv":["Priekšējās kājas pleznas muskulis un Ahileja komplekss iestiepjas. Celis ir saliekts, tāpēc divu locītavu ikru muskulis ir mazāk nospriegots nekā pie taisnas kājas.","Ikru muskulis, ja celis ir gandrīz taisns; priekšējais lielā lielkaula muskulis palīdz vilkt apakšstilbu dorsālajā fleksijā.","Atbrīvo potītes saliekumu, lai papēži var palikt uz grīdas pietupienos un izklupienos."],"tech":[["Стоя лицом к стене. Целевая стопа впереди, носок к стене, пятка на полу. Задняя нога сзади для баланса. Руки можно опереть о стену.","Сгибая переднее колено, направить его к стене над вторым или средним пальцем стопы, не заваливая колено внутрь. Пятка не отрывается.","Колено касается стены или подходит настолько близко, насколько позволяет тыльное сгибание без отрыва пятки и без боли. Вернуться; при необходимости чуть отодвинуть стопу."],["Отрыв пятки","завал колена внутрь","боль в передней части голеностопа — не форсировать."],"Только пока пятка на полу и нет боли спереди голеностопа. Расстояние носка до стены увеличивают постепенно; универсальной нормы в сантиметрах для всех нет."],"techEn":[["Face a wall. The target foot is forward, toes toward the wall, heel on the floor. The back leg is behind you for balance. The hands may rest on the wall.","Bend the front knee and aim it at the wall over the second or middle toe, without the knee caving in. The heel stays down.","The knee touches the wall, or comes as close as dorsiflexion allows without the heel lifting and without pain. Return. If you need to, move the foot a little farther from the wall."],["Heel lifting","Knee caving in","Pain at the front of the ankle — do not force it"],"Only while the heel stays on the floor and the front of the ankle is pain-free. Increase the toe-to-wall distance gradually. There is no centimeter standard that fits everyone."],"techLv":[["Ar seju pret sienu. Mērķa pēda priekšā, pirkstgali pret sienu, papēdis uz grīdas. Aizmugurējā kāja aizmugurē līdzsvaram. Rokas var atbalstīt pret sienu.","Saliecot priekšējo celi, virzīt to uz sienu virs otrā vai vidējā pēdas pirksta, celi nekrītot uz iekšu. Papēdis paliek uz grīdas.","Celis pieskaras sienai vai pienāk tik tuvu, cik dorsālā fleksija ļauj, neatraujot papēdi un bez sāpēm. Atgriezties. Ja vajag, pēdu nedaudz atbīdīt no sienas."],["Papēdis atraujas","Celis krīt uz iekšu","Sāpes potītes priekšpusē — neforsēt"],"Tikai kamēr papēdis ir uz grīdas un potītes priekšpusē nav sāpju. Attālumu no pirkstgala līdz sienai palielina pakāpeniski. Centimetru normas, kas derētu visiem, nav."]},{"id":"open-book","name":"«Открытая книга»","group":"Разминка","meta":"gdb|","nameEn":"Open book","nameLv":"Atvērtā grāmata","lib":["Мышцы-ротаторы грудного отдела; косые мышцы живота.","Большая грудная и передняя часть плечевого пояса верхней стороны растягиваются при открытии руки.","Мягкое вращение грудного отдела лёжа на боку."],"libEn":["Thoracic rotators; abdominal obliques.","Pectoralis major and the front of the shoulder girdle on the top side stretch as the arm opens.","Turns the upper back while the knees keep the hips from rolling along."],"libLv":["Krūšu daļas rotatori; slīpie vēdera muskuļi.","Lielais krūšu muskulis un augšējās puses plecu joslas priekšpuse iestiepjas, roku atverot.","Griež muguras augšu, kamēr ceļi neļauj gurniem ripot līdzi."],"tech":[["Лёжа на боку, бёдра и колени согнуты примерно на 90°, колени вместе. Обе руки вытянуты вперёд и сложены друг на друге на уровне плеч.","Верхняя рука описывает дугу вверх и назад, грудная клетка раскрывается к потолку и к полу за спиной. Взгляд следует за кистью. Таз и колени остаются сложенными, не опрокидываются назад вместе с рукой.","Верхняя рука и лопатка стремятся к полу сзади, насколько позволяет грудной отдел без боли в плече. Медленный возврат — «закрыть книгу»."],["Поворот таза вместе с грудью","рывок рукой через боль в плече","запрокидывание поясницы."],"До комфортного раскрытия грудного отдела и плеча без боли. Колени удерживают таз."],"techEn":[["Lie on your side, hips and knees bent about 90°, knees together. Both arms reach forward and rest stacked at shoulder height.","The top arm draws an arc up and back. The rib cage opens toward the ceiling and toward the floor behind you. The eyes follow the hand. The pelvis and the knees stay stacked and do not roll back with the arm.","The top arm and shoulder blade reach toward the floor behind you, as far as the thoracic spine allows without shoulder pain. Return slowly — close the book."],["Pelvis turning with the chest","Yanking the arm through shoulder pain","Arching the lower back"],"To a comfortable opening of the thoracic spine and the shoulder, without pain. The knees hold the pelvis."],"techLv":[["Guļus uz sāniem, gurni un ceļi saliekti ap 90°, ceļi kopā. Abas rokas izstieptas uz priekšu un saliktas viena uz otras plecu augstumā.","Augšējā roka zīmē loku uz augšu un atpakaļ. Krūškurvis atveras pret griestiem un pret grīdu aiz muguras. Skatiens seko plaukstai. Iegurnis un ceļi paliek salikti un neapgāžas atpakaļ kopā ar roku.","Augšējā roka un lāpstiņa tiecas uz grīdu aizmugurē, cik tālu krūšu daļa ļauj bez sāpēm plecā. Lēna atgriešanās — aizvērt grāmatu."],["Iegurnis griežas kopā ar krūtīm","Rokas rāviens caur sāpēm plecā","Jostas izliekums"],"Līdz ērtai krūšu daļas un pleca atvēršanai bez sāpēm. Ceļi tur iegurni."]},{"id":"worlds-greatest-stretch","name":"«Лучшая растяжка в мире»","group":"Разминка","meta":"gdb|","nameEn":"World's greatest stretch","nameLv":"Pasaules labākā stiepšanās","lib":["Сгибатели бедра задней ноги; ягодичные и приводящие передней ноги; ротаторы грудного отдела.","Задняя поверхность передней ноги (если есть фаза выпрямления колена); икры; кор держит нейтраль.","Связка выпада и вращения грудного отдела."],"libEn":["Hip flexors of the back leg; glutes and adductors of the front leg; thoracic rotators.","Hamstrings of the front leg, if you add the knee-straightening phase; calves; the core holds neutral.","Opens the hips and the upper back in one pass before harder training."],"libLv":["Aizmugurējās kājas gūžas saliecēji; priekšējās kājas sēžas muskuļi un pievilcējmuskuļi; krūšu daļas rotatori.","Priekšējās kājas augšstilba aizmugure, ja ir ceļa iztaisnošanas fāze; ikri; korpuss tur neitrāli.","Atver gurnus un muguras augšu vienā paņēmienā pirms smagāka treniņa."],"tech":[["В длинном выпаде: передняя стопа плоская, заднее колено чуть над полом или мягко касается его. Руки на полу по обе стороны передней стопы или обе внутри неё.","Опустить таз, передняя пятка на полу. Одну руку оставить на полу, другую провести дугой к потолку, раскрывая грудной отдел; взгляд за кистью. Затем можно отвести таз назад и слегка выпрямить переднюю ногу.","Вернуться в выпад и сменить сторону."],["Скругление поясницы вместо вращения груди","отрыв передней пятки","завал колена внутрь","рывок рукой."],"Выпад и ротация в безболевом диапазоне бедра, колена и плеча."],"techEn":[["In a long lunge: front foot flat, back knee just above the floor or lightly touching it. Hands on the floor on either side of the front foot, or both inside it.","Drop the hips, front heel on the floor. Leave one hand down and sweep the other in an arc toward the ceiling, opening the thoracic spine. The eyes follow the hand. You can then shift the hips back and slightly straighten the front leg.","Return to the lunge and switch sides."],["Rounding the lower back instead of rotating the chest","Front heel lifting","Knee caving in","Yanking the arm"],"Lunge and rotation inside a pain-free range of the hip, knee, and shoulder."],"techLv":[["Garā izklupienā: priekšējā pēda plakana, aizmugurējais celis nedaudz virs grīdas vai viegli tai pieskaras. Rokas uz grīdas abpus priekšējai pēdai vai abas pēdas iekšpusē.","Nolaist gurnus, priekšējais papēdis uz grīdas. Vienu roku atstāt uz grīdas, otru vest lokā uz griestiem, atverot krūšu daļu. Skatiens seko plaukstai. Pēc tam var atvirzīt gurnus atpakaļ un viegli iztaisnot priekšējo kāju.","Atgriezties izklupienā un nomainīt pusi."],["Jostas noapaļošana krūšu rotācijas vietā","Priekšējais papēdis atraujas","Celis krīt uz iekšu","Rokas rāviens"],"Izklupiens un rotācija gūžas, ceļa un pleca bezsāpju diapazonā."]},{"id":"lateral-lunge-bw","name":"Боковые выпады с весом тела","group":"Разминка","meta":"gdb|k","nameEn":"Bodyweight lateral lunge","nameLv":"Sānu izklupiens ar ķermeņa svaru","lib":["Квадрицепс и ягодичные сгибающейся (рабочей) ноги.","Приводящие прямой ноги растягиваются; средняя ягодичная рабочей ноги стабилизирует; кор.","Боковой шаг без веса для приводящих и ног."],"libEn":["Quads and glutes of the bending (working) leg.","Adductors of the straight leg stretch; glute medius of the working leg stabilizes; core.","Steps wide onto one bent leg so you can move sideways, not only forward."],"libLv":["Saliektās (darba) kājas četrgalvainais un sēžas muskuļi.","Taisnās kājas pievilcējmuskuļi iestiepjas; darba kājas vidējais sēžas muskulis stabilizē; korpuss.","Māca platu soli uz vienu saliektu kāju, lai varētu kustēties sānis, ne tikai uz priekšu."],"tech":[["Стоя, стопы вместе или узко, руки перед грудью или на бёдрах.","Широкий шаг в сторону. Сгибается только нога, в которую шагнули: таз назад и вниз, колено по носку, пятка рабочей ноги на полу. Другая нога остаётся почти прямой.","Оттолкнуться рабочей стопой и вернуться в стойку. Затем шаг в другую сторону."],["Завал рабочего колена внутрь","сгибание обеих ног сразу (это уже широкий присед)","отрыв пятки рабочей ноги","скругление поясницы."],"До комфортной глубины, пока рабочая пятка на полу и колено над стопой."],"techEn":[["Stand with the feet together or narrow, hands in front of the chest or on the hips.","Take a wide step to the side. Only the leg you stepped onto bends: hips back and down, knee over the toes, working heel on the floor. The other leg stays nearly straight.","Push off the working foot and return to standing. Then step to the other side."],["Working knee caving in","Bending both legs at once (that is a wide squat)","Working heel lifting","Rounding the lower back"],"To a comfortable depth, while the working heel stays down and the knee stays over the foot."],"techLv":[["Stāvus, pēdas kopā vai šauri, rokas priekšā krūtīm vai uz gurniem.","Plats solis uz sāniem. Saliecas tikai tā kāja, uz kuru sper soli: gurni atpakaļ un lejā, celis virs pirkstgaliem, darba kājas papēdis uz grīdas. Otra kāja paliek gandrīz taisna.","Atgrūsties ar darba pēdu un atgriezties stājā. Tad solis uz otru pusi."],["Darba celis krīt uz iekšu","Abu kāju saliekšana uzreiz (tā jau ir plats pietupiens)","Darba kājas papēdis atraujas","Jostas noapaļošana"],"Līdz ērtam dziļumam, kamēr darba papēdis ir uz grīdas un celis virs pēdas."]},{"id":"negative-pullup","name":"Негативные подтягивания","group":"Спина","meta":"gb|","nameEn":"Negative pull-up","nameLv":"Negatīvā pievilkšanās","lib":["Широчайшие (эксцентрическая работа).","Бицепс; задние дельты; ромбовидные; нижние трапеции; кор.","Медленное опускание из подтягивания, когда полный подъём ещё не получается."],"libEn":["Lats (eccentric work).","Biceps; rear delts; rhomboids; lower traps; core.","Builds the strength to lower yourself before you can pull up."],"libLv":["Platie muguras muskuļi (ekscentrisks darbs).","Bicepss; aizmugurējie deltveida; rombveida muskuļi; trapecveida apakšdaļa; korpuss.","Veido spēku nolaisties, pirms spējat pievilkties augšā."],"tech":[["Выход в верхнюю точку (подбородок выше грифа) шагом с опоры или прыжком. Прямой хват чуть шире плеч, плечи упакованы.","Только медленное опускание: локти разгибаются контролируемо, лопатки не «бросаются». Концентрического подтягивания нет.","Почти прямой вис, затем ноги на опору — не прыгать сразу в следующее повторение без контроля."],["Падение вниз","киппинг","сгиб в пояснице","неполная амплитуда (сходить с перекладины на середине пути)."],"От подбородка выше грифа до почти полного виса."],"techEn":[["Get to the top, chin over the bar, by stepping off a support or with a jump. Overhand grip slightly wider than the shoulders, shoulders packed.","Only a slow lower: the elbows straighten under control, and the shoulder blades are not dropped. There is no concentric pull-up.","A nearly straight hang, then the feet back on the support. Do not jump straight into the next rep without control."],["Dropping","Kipping","Bending at the lower back","Short range (leaving the bar halfway down)"],"From the chin over the bar to a nearly full hang."],"techLv":[["Izeja augšā, zods virs stieņa, ar soli no balsta vai ar lēcienu. Tvēriens no augšas nedaudz platāks par pleciem, pleci savākti.","Tikai lēna nolaišana: elkoņi atliecas kontrolēti, lāpstiņas netiek nomestas. Koncentriskas pievilkšanās nav.","Gandrīz taisns karājums, tad kājas atpakaļ uz balsta. Nelēkt uzreiz nākamajā atkārtojumā bez kontroles."],["Krišana","Ķermeņa šūpošana (kipings)","Saliekums jostas daļā","Nepilna amplitūda (nokāpt no stieņa pusceļā)"],"No zoda virs stieņa līdz gandrīz pilnam karājumam."]},{"id":"tibialis-raise","name":"Подъёмы носка на себя","group":"Ноги","meta":"gdb|","nameEn":"Tibialis raise","nameLv":"Pirkstgalu pacelšana pret sevi","lib":["Передняя большеберцовая.","Разгибатели пальцев стопы.","Укрепление передней большеберцовой без отягощения."],"libEn":["Tibialis anterior.","Toe extensors.","Strengthens the front of the shin so the ankle can slow the foot on landings."],"libLv":["Priekšējais lielā lielkaula muskulis.","Pēdas pirkstu atliecēji.","Stiprina apakšstilba priekšpusi, lai potīte var piebremzēt pēdu piezemējoties."],"tech":[["Стоя спиной к стене, стопы чуть впереди, лопатки опираются о стену. Пятки на полу.","Пятки остаются на полу, носки поднимаются на себя (тыльное сгибание).","Максимальный комфортный подъём носков, медленное опускание до касания пола."],["Отрыв пяток","раскачка корпусом","рывок через боль в голени."],"От касания носками пола до максимального безболевого тыльного сгибания."],"techEn":[["Stand with your back to a wall, feet slightly forward, shoulder blades on the wall. Heels on the floor.","Heels stay on the floor and the toes lift toward you (dorsiflexion).","Lift the toes as high as is comfortable, then lower slowly until they touch the floor."],["Heels lifting","Swinging the torso","Jerking through shin pain"],"From the toes touching the floor to the fullest pain-free dorsiflexion."],"techLv":[["Stāvus ar muguru pret sienu, pēdas nedaudz priekšā, lāpstiņas balstās pret sienu. Papēži uz grīdas.","Papēži paliek uz grīdas, pirkstgali ceļas pret sevi (dorsālā fleksija).","Maksimāli ērta pirkstgalu pacelšana, tad lēna nolaišana līdz pieskārienam grīdai."],["Papēži atraujas","Šūpošanās ar rumpi","Rāviens caur sāpēm apakšstilbā"],"No pirkstgalu pieskāriena grīdai līdz maksimālai bezsāpju dorsālajai fleksijai."]},{"id":"neck-flexion-extension","name":"Сгибание и разгибание шеи","group":"Плечи","meta":"gdb|","nameEn":"Neck flexion and extension","nameLv":"Kakla saliekšana un atliekšana","lib":["При сгибании — сгибатели шеи; при разгибании — разгибатели шеи (ременные, полуостистая).","Верхняя трапеция участвует в разгибании; не делать её основной целью.","Медленные кивки шеи без веса."],"libEn":["On the way down, the neck flexors; on the way up, the neck extensors (splenius, semispinalis).","The upper traps take part in extension. Do not make them the main target.","Teaches the neck to nod and look up through a small range, with no added load."],"libLv":["Lejup — kakla saliecēji; augšup — kakla atliecēji (siksnas muskuļi, pusass muskulis).","Trapecveida augšdaļa piedalās atliekšanā. Nepadarīt to par galveno mērķi.","Māca kaklam pamāt un paskatīties augšup mazā amplitūdā, bez papildu svara."],"tech":[["Сидя, без отягощения. Нейтральная шея, плечи опущены, руки на коленях.","Медленный кивок подбородком к груди (сгибание), возврат в нейтраль; затем лёгкое разгибание взглядом чуть вверх, без запрокидывания до упора.","Возврат в нейтраль после каждого направления."],["Рывки","круговые вращения на скорости","большое отягощение на голову","запрокидывание до упора."],"Комфортный безболевой диапазон. Не доводить до крайнего запрокидывания."],"techEn":[["Sit, with no added weight. Neck neutral, shoulders down, hands on the knees.","A slow nod of the chin toward the chest (flexion), then back to neutral. Then a light look slightly upward, without tipping the head all the way back.","Return to neutral after each direction."],["Jerks","Fast neck circles","A heavy load on the head","Tipping the head all the way back"],"A comfortable, pain-free range. Do not go to an extreme backward tilt."],"techLv":[["Sēdus, bez papildu svara. Kakls neitrāls, pleci nolaisti, rokas uz ceļiem.","Lēns pamājiens ar zodu uz krūtīm (saliekšana), tad atpakaļ neitrālē. Pēc tam viegls skatiens nedaudz augšup, neatmetot galvu līdz galam.","Atgriešanās neitrālē pēc katra virziena."],["Rāvieni","Ātri kakla apļi","Liels svars uz galvas","Galvas atmešana līdz galam"],"Ērts bezsāpju diapazons. Neiet līdz galējai galvas atmešanai."]},{"id":"cable-internal-rotation","name":"Внутренняя ротация плеча на блоке","group":"Плечи","meta":"g|p","nameEn":"Cable internal rotation","nameLv":"Pleca iekšējā rotācija uz bloka","lib":["Подлопаточная (основной внутренний ротатор).","Большая грудная и широчайшая как вспомогательные внутренние ротаторы; передняя дельта.","Лёгкая работа внутренних вращателей плеча."],"libEn":["Subscapularis (the main internal rotator).","Pectoralis major and the lats as assisting internal rotators; front delt.","Turns the shoulder inward with the elbow glued to the side."],"libLv":["Zemlāpstiņas muskulis (galvenais iekšējais rotators).","Lielais krūšu muskulis un platie muguras muskuļi kā palīgi iekšējā rotācijā; priekšējais deltveida.","Griež plecu uz iekšu, elkoni turot pie sāna."],"tech":[["Стоя боком к блоку на уровне локтя, рабочая рука ближняя к блоку, локоть прижат к корпусу и согнут 90°, предплечье направлено вперёд или чуть наружу, рукоятка в руке. Трос тянет предплечье от живота — внутренняя ротация идёт против сопротивления.","Предплечье вращается внутрь к животу вокруг оси плеча. Локоть не отъезжает.","Предплечье у живота, без закручивания корпуса. Медленный возврат."],["Отведение локтя","поворот корпуса","превращение в сведение или жим","слишком большой вес."],"В безболевом диапазоне внутренней ротации, локоть прижат к корпусу."],"techEn":[["Stand side-on to the cable at elbow height. The working arm is the one closer to the stack, elbow pinned to the side and bent 90°, forearm pointing forward or slightly out, handle in hand. The cable pulls the forearm away from the belly, so internal rotation works against that pull.","The forearm rotates inward toward the belly around the shoulder. The elbow does not drift off.","Forearm at the belly, without twisting the torso. Return slowly."],["Elbow drifting out","Turning the torso","Turning it into a fly or a press","Too much weight"],"A pain-free internal-rotation range, elbow pinned to the side."],"techLv":[["Stāvus sāniski pret bloku elkoņa augstumā. Darba roka ir tuvākā blokam, elkonis piespiests sānam un saliekts 90°, apakšdelms vērsts uz priekšu vai nedaudz uz āru, rokturis rokā. Trose velk apakšdelmu prom no vēdera, tāpēc iekšējā rotācija iet pret šo vilkmi.","Apakšdelms griežas uz iekšu, uz vēderu, ap pleca asi. Elkonis neaiziet.","Apakšdelms pie vēdera, bez rumpja sagriešanas. Lēna atgriešanās."],["Elkonis aiziet uz sāniem","Rumpja pagriešana","Pārvēršana par savilkšanu vai spiedienu","Pārāk liels svars"],"Bezsāpju iekšējās rotācijas diapazons, elkonis piespiests sānam."]},{"id":"cable-external-rotation-90","name":"Наружная ротация в отведении 90°","group":"Плечи","meta":"g|p","nameEn":"External rotation at 90° abduction","nameLv":"Ārējā rotācija 90° atvilkumā","lib":["Подостная и малая круглая.","Задняя дельта; надостная удерживает голову плеча в отведении.","Наружная ротация плеча в отведении. Лёгкий вес."],"libEn":["Infraspinatus and teres minor.","Rear delt; supraspinatus holds the humeral head up in abduction.","Turns the shoulder outward with the arm held out to the side, the way it works in a press."],"libLv":["Zemšķautnes muskulis un mazais apaļais muskulis.","Aizmugurējais deltveida; virsšķautnes muskulis tur augšdelma galvu atvilkumā.","Griež plecu uz āru ar roku turētu sānis, tā, kā tas strādā spiedienā."],"tech":[["Плечо отведено примерно 90°, локоть согнут 90° (позиция 90/90). Блок на высоте локтя. Предплечье начинает примерно параллельно полу.","Предплечье вращается вверх-назад вокруг оси плеча, локоть остаётся на месте как шарнир.","Предплечье ближе к вертикали, без боли. Медленный возврат."],["Опускание локтя","превращение в жим или тягу к лицу","слишком большой вес","боль впереди плеча."],"В безболевом диапазоне наружной ротации при отведении около 90°."],"techEn":[["Shoulder out to about 90°, elbow bent 90° (the 90/90 position). Cable at elbow height. The forearm starts about parallel to the floor.","The forearm rotates up and back around the shoulder. The elbow stays put, as the hinge.","Forearm closer to vertical, without pain. Return slowly."],["Dropping the elbow","Turning it into a press or a face pull","Too much weight","Pain at the front of the shoulder"],"A pain-free external-rotation range, with the arm out to about 90°."],"techLv":[["Plecs atvilkts ap 90°, elkonis saliekts 90° (90/90 pozīcija). Bloks elkoņa augstumā. Apakšdelms sākas apmēram paralēli grīdai.","Apakšdelms griežas augšup un atpakaļ ap pleca asi. Elkonis paliek vietā kā eņģe.","Apakšdelms tuvāk vertikālei, bez sāpēm. Lēna atgriešanās."],["Elkoņa nolaišana","Pārvēršana par spiedienu vai vilkmi uz seju","Pārāk liels svars","Sāpes pleca priekšpusē"],"Bezsāpju ārējās rotācijas diapazons, rokai esot atvilktai ap 90°."]},{"id":"hanging-knee-raise","name":"Подъём коленей в висе","group":"Пресс","meta":"gb|","nameEn":"Hanging knee raise","nameLv":"Ceļu pacelšana karājumā","lib":["Прямая мышца живота (низ); сгибатели бедра.","Косые; хват.","Подъём коленей в висе для низа пресса."],"libEn":["Rectus abdominis (lower); hip flexors.","Obliques; grip.","Lifts the knees from a hang so the trunk curls without a swing."],"libLv":["Taisnais vēdera muskulis (apakšējā daļa); gūžas saliecēji.","Slīpie vēdera muskuļi; tvēriens.","Ceļ ceļus no karājuma, lai rumpis saliecas bez šūpošanās."],"tech":[["Вис на перекладине, плечи опущены, ноги вместе.","Подтянуть колени к груди за счёт сгибания бёдер и заднего наклона таза. Голени складываются, не мах прямыми ногами.","Бёдра выше параллели или колени у живота, без раскачки. Медленный спуск до виса."],["Раскачка","только мах бёдрами без контроля таза","вытягивание головы вперёд."],"От виса с почти прямыми ногами до коленей у живота или бёдер выше параллели, без боли в пояснице и плечах."],"techEn":[["Hang from a bar, shoulders down, legs together.","Draw the knees toward the chest by bending the hips and tilting the pelvis back. The shins fold in. Do not swing straight legs.","Thighs above parallel, or knees at the belly, with no swing. Lower slowly to a hang."],["Swinging","Only swinging the hips, with no control of the pelvis","Poking the head forward"],"From a hang with nearly straight legs to the knees at the belly, or the thighs above parallel, without pain in the lower back or the shoulders."],"techLv":[["Karājums uz pārliktņa, pleci nolaisti, kājas kopā.","Vilkt ceļus uz krūtīm, saliecot gūžas un sagāžot iegurni atpakaļ. Apakšstilbi saliecas. Nešūpot taisnas kājas.","Augšstilbi virs paralēles vai ceļi pie vēdera, bez šūpošanās. Lēna nolaišana līdz karājumam."],["Šūpošanās","Tikai gūžu vēziens, bez iegurņa kontroles","Galvas bīdīšana uz priekšu"],"No karājuma ar gandrīz taisnām kājām līdz ceļiem pie vēdera vai augšstilbiem virs paralēles, bez sāpēm jostas daļā un plecos."]},{"id":"sl-rdl","name":"Румынская тяга на одной ноге","group":"Ноги","meta":"gd|s","nameEn":"Single-leg Romanian deadlift","nameLv":"Rumāņu vilkme uz vienas kājas","lib":["Задняя поверхность бедра и большая ягодичная опорной ноги.","Средняя ягодичная (стабилизация таза); разгибатели спины; икроножные; кор.","Наклон на одной ноге: задняя цепь и баланс."],"libEn":["Hamstrings and glute max of the stance leg.","Glute medius (pelvic stability); spinal erectors; calves; core.","Hinges on one leg and asks for balance and a level hip at the same time."],"libLv":["Atbalsta kājas augšstilba aizmugure un lielais sēžas muskulis.","Vidējais sēžas muskulis (iegurņa stabilitāte); muguras atliecēji; ikri; korpuss.","Trenē locījumu uz vienas kājas, kur vienlaikus vajag līdzsvaru un līdzenu gūžu."],"tech":[["Стоя на одной ноге, гантель в противоположной руке. Лёгкий мягкий сгиб опорного колена, лопатки собраны.","Шарнир в тазу: корпус наклоняется вперёд, свободная нога уходит назад в одну линию с корпусом. Гантель скользит вдоль опорной голени.","До параллели корпуса полу или меньше, пока спина нейтральна и таз не разворачивается. Возврат за счёт разгибания бедра опорной ноги."],["Скругление поясницы","разворот таза","сгибание опорного колена как в приседе","потеря баланса с шагом на каждом повторе без задачи."],"Наклон до той глубины, где спина остаётся нейтральной и таз смотрит вниз, не вбок."],"techEn":[["Stand on one leg, dumbbell in the opposite hand. A soft bend in the stance knee, shoulder blades set.","Hinge at the hips: the torso tips forward and the free leg reaches back in one line with the torso. The dumbbell slides along the stance shin.","To parallel with the floor, or less of a lean, as long as the back stays neutral and the pelvis does not open. Return by extending the hip of the stance leg."],["Rounding the lower back","Pelvis twisting open","Bending the stance knee like a squat","Losing balance and stepping on every rep when stepping is not the task"],"Hinge only as deep as the back stays neutral and the pelvis faces the floor, not the side."],"techLv":[["Stāvus uz vienas kājas, hantele pretējā rokā. Viegls mīksts saliekums atbalsta celī, lāpstiņas savāktas.","Locījums gurnos: rumpis noliecas uz priekšu, brīvā kāja iet atpakaļ vienā līnijā ar rumpi. Hantele slīd gar atbalsta apakšstilbu.","Līdz rumpja paralēlei ar grīdu vai mazākam noliekumam, kamēr mugura ir neitrāla un iegurnis nepagriežas. Atgriešanās, atliecot atbalsta kājas gūžu."],["Jostas noapaļošana","Iegurnis pagriežas uz sāniem","Atbalsta ceļa saliekšana kā pietupienā","Līdzsvara zaudēšana ar soli katrā atkārtojumā, ja solis nav uzdevums"],"Noliekums līdz tam dziļumam, kur mugura paliek neitrāla un iegurnis skatās lejup, nevis sānis."]},{"id":"band-chest-press","name":"Жим с резиновой лентой","group":"Грудь","meta":"gd|","nameEn":"Band chest press","nameLv":"Krūšu spiediens ar pretestības gumiju","lib":["Большая грудная.","Передние дельты; трицепс; зубчатая.","Жим вперёд с лентой дома или в зале."],"libEn":["Pectoralis major.","Front delts; triceps; serratus anterior.","Presses the chest against a band that gets harder as the arms straighten."],"libLv":["Lielais krūšu muskulis.","Priekšējie deltveida; tricepss; priekšējais zāģmuskulis.","Spiež krūtis pret gumiju, kas kļūst smagāka, rokām iztaisnojoties."],"tech":[["Лента закреплена за спиной на высоте середины груди. Концы в руках у груди, стойка в лёгком сплите или стопы на ширине плеч, лопатки слегка сведены.","Жим рук вперёд до почти прямых локтей, без шрага. Сопротивление растёт к концу, в отличие от свободного веса.","Почти прямые руки перед грудью, возврат до растяжения у груди."],["Шраг","прогиб поясницы","шаг вперёд на каждом повторе без задачи","удар локтей в конце."],"От кистей у груди до почти прямых рук перед собой."],"techEn":[["Band anchored behind you at mid-chest height. Ends in the hands at the chest, a slight split stance or feet at shoulder width, shoulder blades lightly pinched.","Press the arms forward to nearly straight elbows, no shrug. The resistance rises toward the end, unlike free weights.","Nearly straight arms in front of the chest, then return to a stretch at the chest."],["Shrugging","Arching the lower back","Stepping forward on every rep when that is not the task","Snapping the elbows at the end"],"From the hands at the chest to nearly straight arms in front of you."],"techLv":[["Gumija nostiprināta aiz muguras krūšu vidus augstumā. Gali rokās pie krūtīm, viegla dalītā stāja vai pēdas plecu platumā, lāpstiņas viegli savilktas.","Roku spiediens uz priekšu līdz gandrīz taisniem elkoņiem, bez plecu pacelšanas. Pretestība aug beigās, atšķirībā no brīvā svara.","Gandrīz taisnas rokas priekšā krūtīm, tad atgriešanās līdz iestiepumam pie krūtīm."],["Plecu pacelšana","Jostas izliekums","Solis uz priekšu katrā atkārtojumā, ja tas nav uzdevums","Elkoņu sitiens beigās"],"No plaukstām pie krūtīm līdz gandrīz taisnām rokām priekšā sev."]},{"id":"wrist-mobility","name":"Мобилизация запястий","group":"Разминка","meta":"gdb|","nameEn":"Wrist mobilization","nameLv":"Plaukstas locītavu mobilizācija","lib":["Сгибатели и разгибатели запястья (мобилити и лёгкое растяжение).","Предплечья в целом.","Круги и мягкая растяжка запястий."],"libEn":["Wrist flexors and extensors (mobility and a light stretch).","The forearms in general.","Loosens the wrists with circles and easy stretches before pressing or gripping."],"libLv":["Plaukstas locītāji un atliecēji (kustīgums un viegla stiepšanās).","Apakšdelmi kopumā.","Iekustina plaukstas ar apļiem un vieglu stiepšanos pirms spiediena vai tvēriena."],"tech":[["Стоя или сидя, руки перед собой. Сначала круги кистями в обе стороны при свободных пальцах.","Затем растяжка: ладонь на пол или на стену пальцами от себя (разгибание) и пальцами к себе (сгибание), локоть мягкий, без боли.","Вернуться в нейтраль запястья."],["Рывки","давить через острую боль","полностью запирать локоть на растяжке, если запястье протестует."],"Комфортный безболевой диапазон кругов и растяжения."],"techEn":[["Stand or sit, arms in front of you. First circle the hands both ways, fingers relaxed.","Then stretch: palm on the floor or a wall, fingers pointing away (extension) and fingers pointing toward you (flexion). Elbow soft, no pain.","Return the wrist to neutral."],["Jerks","Pushing through sharp pain","Fully locking the elbow on the stretch if the wrist complains"],"A comfortable, pain-free range for the circles and the stretch."],"techLv":[["Stāvus vai sēdus, rokas priekšā. Vispirms apļi ar plaukstām abos virzienos, pirkstiem brīviem.","Tad stiepšanās: plauksta uz grīdas vai sienas, pirksti prom no sevis (atliekšana) un pirksti pret sevi (saliekšana). Elkonis mīksts, bez sāpēm.","Atgriezt plaukstas locītavu neitrālē."],["Rāvieni","Spiešana caur asām sāpēm","Elkoņa pilnīga aizslēgšana stiepšanā, ja plauksta protestē"],"Ērts bezsāpju diapazons apļiem un stiepšanai."]},{"id":"kb-windmill","name":"Мельница с гирей","group":"Пресс","meta":"gd|sp","nameEn":"Kettlebell windmill","nameLv":"Vējdzirnavas ar svara bumbu","lib":["Косые и квадратная мышца поясницы стороны, которая контролирует наклон.","Плечо верхней руки (дельты, манжета) удерживает гирю; задняя поверхность и приводящие нижней стороны; ягодичная.","Наклон с гирей над головой. Сложная координация."],"libEn":["Obliques and quadratus lumborum on the side that controls the lean.","The shoulder of the top arm (delts, rotator cuff) holds the kettlebell; hamstrings and adductors of the lower side; glute.","Side-bends under a locked-out kettlebell so the trunk stays long and the bell stays overhead."],"libLv":["Slīpie vēdera muskuļi un jostas kvadrātmuskulis tajā pusē, kas kontrolē noliekumu.","Augšējās rokas plecs (deltveida, rotatora manšete) tur svara bumbu; apakšējās puses augšstilba aizmugure un pievilcējmuskuļi; sēžas muskulis.","Māca sānu noliekumu zem fiksētas svara bumbas, lai rumpis paliek garš un bumba paliek virs galvas."],"tech":[["Гиря в выпрямленной руке над головой, взгляд на гирю. Стопы чуть шире плеч, носки развёрнуты примерно в сторону наклона (от гири).","Таз уводится в сторону верхней руки, корпус наклоняется, свободная рука скользит вдоль одноимённой ноги. Обе ноги относительно прямые, спина нейтральна.","Свободная рука касается стопы или голени в комфортном диапазоне. Подъём в стойку за счёт выпрямления корпуса, гиря всё время над плечом."],["Скругление поясницы","сгибание верхней руки","потеря вертикали гири","рывок."],"До касания стопы или голени, пока спина нейтральна и гиря остаётся над плечом."],"techEn":[["Kettlebell locked out overhead, eyes on the bell. Feet a little wider than the shoulders, toes turned roughly toward the lean, away from the bell.","Shift the hips toward the top arm, lean the torso, and slide the free hand down the same-side leg. Both legs stay relatively straight, back neutral.","The free hand touches the foot or the shin in a comfortable range. Stand back up by straightening the torso, kettlebell staying over the shoulder the whole time."],["Rounding the lower back","Bending the top arm","Losing the kettlebell's overhead line","Jerking"],"To a touch on the foot or the shin, as long as the back stays neutral and the kettlebell stays over the shoulder."],"techLv":[["Svara bumba iztaisnotā rokā virs galvas, skatiens uz bumbu. Pēdas nedaudz platāk par pleciem, pirkstgali pagriezti apmēram noliekuma virzienā, prom no bumbas.","Gurnus virza augšējās rokas pusē, rumpis noliecas, brīvā roka slīd gar tās pašas puses kāju. Abas kājas samērā taisnas, mugura neitrāla.","Brīvā roka pieskaras pēdai vai apakšstilbam ērtā diapazonā. Pacelšanās stājā, iztaisnojot rumpi, svara bumba visu laiku virs pleca."],["Jostas noapaļošana","Augšējās rokas saliekšana","Svara bumba zaudē līniju virs galvas","Rāviens"],"Līdz pieskārienam pēdai vai apakšstilbam, kamēr mugura ir neitrāla un svara bumba paliek virs pleca."]},{"id":"cuban-press","name":"Кубинский жим","group":"Плечи","meta":"gd|p","nameEn":"Cuban press","nameLv":"Kubas spiediens","lib":["Подостная и малая круглая в фазе наружной ротации; дельты в жиме.","Надостная; трапеции; трицепс в жиме.","Лёгкая связка тяги, наружной ротации и жима для плеч."],"libEn":["Infraspinatus and teres minor in the external-rotation phase; delts in the press.","Supraspinatus; traps; triceps in the press.","Links a high pull, an outward turn, and a light press into one shoulder pattern."],"libLv":["Zemšķautnes muskulis un mazais apaļais muskulis ārējās rotācijas fāzē; deltveida spiedienā.","Virsšķautnes muskulis; trapecveida; tricepss spiedienā.","Savieno vilkmi augšup, pagriezienu uz āru un vieglu spiedienu vienā pleca kustībā."],"tech":[["Стоя, лёгкие гантели. Начало как тяга к груди: локти высоко в стороны, предплечья направлены вниз.","Не опуская локти, вращать плечи наружу, пока предплечья не встанут вертикально (гантели у ушей). Затем жим вверх.","Почти прямые руки над головой. Обратный путь: опустить к ушам, вращение внутрь, опускание как из тяги."],["Большой вес (это не силовой жим)","рывок","тяга выше, чем позволяют плечи","прогиб поясницы."],"От виса у бёдер через позицию «локти высоко, предплечья вертикально» до почти прямых рук над головой."],"techEn":[["Stand with light dumbbells. Start as in a high pull to the chest: elbows high out to the sides, forearms pointing down.","Without dropping the elbows, rotate the shoulders outward until the forearms are vertical (dumbbells by the ears). Then press up.","Nearly straight arms overhead. Reverse the path: lower to the ears, rotate inward, then lower as you would from the pull."],["Heavy weight (this is not a strength press)","Jerking","Pulling higher than the shoulders allow","Arching the lower back"],"From a hang at the hips, through elbows high with the forearms vertical, to nearly straight arms overhead."],"techLv":[["Stāvus, vieglas hanteles. Sākums kā augstā vilkmē uz krūtīm: elkoņi augstu sānis, apakšdelmi vērsti lejup.","Nenolaižot elkoņus, plecus griež uz āru, līdz apakšdelmi nostājas vertikāli (hanteles pie ausīm). Tad spiediens uz augšu.","Gandrīz taisnas rokas virs galvas. Atpakaļceļš: nolaist līdz ausīm, rotācija uz iekšu, tad nolaišana kā no vilkmes."],["Liels svars (šis nav spēka spiediens)","Rāviens","Vilkme augstāk, nekā pleci ļauj","Jostas izliekums"],"No karājuma pie gurniem caur augstiem elkoņiem ar vertikāliem apakšdelmiem līdz gandrīz taisnām rokām virs galvas."]},{"id":"mch-incline","name":"Жим в тренажёре сидя (наклонный)","group":"Грудь","meta":"g|p","nameEn":"Seated incline machine chest press","nameLv":"Sēdus slīpais krūšu spiediens trenažierī","lib":["Большая грудная, акцент на ключичной порции.","Передние дельты (больше, чем в горизонтальном); трицепс.","Наклонный жим в тренажёре: верх груди по заданной траектории."],"libEn":["Pectoralis major, with the emphasis on the clavicular portion.","Front delts (more than in the flat press); triceps.","Presses the upper chest on a guided machine with the back supported."],"libLv":["Lielais krūšu muskulis, akcents uz atslēgas kaula daļu.","Priekšējie deltveida (vairāk nekā horizontālajā spiedienā); tricepss.","Spiež krūšu augšu vadītā trenažierī ar atbalstītu muguru."],"tech":[["Сиденье и спинка задают наклон около 30° (рабочий диапазон 15–45°). Рукоятки на уровне верхней груди.","Жим вверх-вперёд по направляющим, лопатки к подушке.","Почти прямые руки без удара; контролируемый возврат."],["Наклон круче 45° сильно смещает нагрузку на передние дельты (ближе к жиму плеч)","шраг."],"Наклон тренажёра около 30° (рабочий диапазон 15–45°). Не выходить в положение жима над головой."],"techEn":[["Seat and backrest set an angle near 30° (working range 15–45°). Handles at upper-chest height.","Press up and forward along the guides, shoulder blades on the pad.","Nearly straight arms without banging the end of the range. Return under control."],["An angle steeper than 45° shifts the load hard onto the front delts (closer to a shoulder press)","Shrugging"],"Machine angle near 30° (working range 15–45°). Do not drift into an overhead-press position."],"techLv":[["Sēdeklis un atzveltne nosaka slīpumu ap 30° (darba diapazons 15–45°). Rokturi krūšu augšas augstumā.","Spiediens augšup un uz priekšu pa vadotnēm, lāpstiņas pie polstera.","Gandrīz taisnas rokas bez sitiena amplitūdas galā. Kontrolēta atgriešanās."],["Slīpums stāvāks par 45° stipri pārnes slodzi uz priekšējiem deltveida muskuļiem (tuvāk plecu spiedienam)","Plecu pacelšana"],"Trenažiera slīpums ap 30° (darba diapazons 15–45°). Neieiet virs galvas spiediena pozīcijā."]},{"id":"lc-seated","name":"Сгибание ног сидя","group":"Ноги","meta":"g|","nameEn":"Seated leg curl","nameLv":"Kāju saliekšana sēdus","lib":["Задняя поверхность бедра. При согнутом бедре двусуставные хамстринги в более растянутом положении у таза.","Икры.","Сгибание ног сидя, бицепс бедра в растянутом положении."],"libEn":["Hamstrings. With the hip bent, the two-joint hamstrings sit in a more stretched position at the pelvis.","Calves.","Curls the knee from a bent hip so the back of the thigh works in a long position."],"libLv":["Augšstilba aizmugure. Ar saliektu gūžu divu locītavu augšstilba aizmugures muskuļi ir vairāk iestiepti pie iegurņa.","Ikri.","Saliec celi no saliektas gūžas, lai augšstilba aizmugure strādā garā stāvoklī."],"tech":[["Сидя, валик чуть выше пяток, таз прижат к сиденью.","Сгибание коленей вниз по дуге без отрыва таза.","Полное сгибание, медленный возврат почти до прямой ноги."],["Отрыв таза","рывок."],"От почти прямой ноги до полного сгибания при фиксированном тазе."],"techEn":[["Sit with the pad just above the heels and the pelvis pressed into the seat.","Curl the knees down along the arc without the pelvis lifting.","Full flexion, then a slow return to a nearly straight leg."],["Pelvis lifting off","Jerking"],"From a nearly straight leg to full flexion, with the pelvis fixed."],"techLv":[["Sēdus, rullis nedaudz virs papēžiem, iegurnis piespiests sēdeklim.","Ceļu saliekšana lejup pa loku, iegurnim neatraujoties.","Pilna saliekšana, tad lēna atgriešanās gandrīz līdz taisnai kājai."],["Iegurnis atraujas","Rāviens"],"No gandrīz taisnas kājas līdz pilnai saliekšanai ar fiksētu iegurni."]},{"id":"tpd-rope","name":"Разгибание на блоке (канат)","group":"Трицепс","meta":"g|","nameEn":"Rope triceps pushdown","nameLv":"Tricepsa spiediens lejup ar virvi","lib":["Трицепс (все три головки).","Локтевая мышца.","Разгибание трицепса на блоке канатом."],"libEn":["Triceps (all three heads).","Anconeus.","Straightens the elbows on a rope so the shoulders stay quiet and the hands can finish apart."],"libLv":["Tricepss (visas trīs galvas).","Elkoņa muskulis.","Iztaisno elkoņus ar virvi, lai pleci paliek mierā un plaukstas var beigt nedaudz šķirti."],"tech":[["Канат, локти прижаты к корпусу.","Разгибание в локте; внизу можно слегка развести концы каната.","Почти прямые руки, концы каната слегка врозь. Возврат до 90°."],["Наклон корпусом","разведение локтей","движение в плече."],"От локтя около 90° до почти полного разгибания."],"techEn":[["Rope, elbows pinned to the sides.","Extend at the elbow. At the bottom you can spread the rope ends slightly.","Nearly straight arms, rope ends slightly apart. Return to about 90°."],["Leaning with the torso","Elbows flaring","Moving at the shoulder"],"From the elbow near 90° to nearly full extension."],"techLv":[["Virve, elkoņi piespiesti sāniem.","Atliekšana elkonī. Apakšā virves galus var viegli atvērt.","Gandrīz taisnas rokas, virves gali nedaudz šķirti. Atgriešanās līdz apmēram 90°."],["Noliekšanās ar rumpi","Elkoņi izplešas","Kustība plecā"],"No elkoņa ap 90° līdz gandrīz pilnai atliekšanai."]},{"id":"pec-deck","name":"Сведения в тренажёре","group":"Грудь","meta":"g|","nameEn":"Pec deck","nameLv":"Krūšu savilkšana trenažierī","lib":["Большая грудная.","Передние дельты; короткая головка бицепса. Трицепс почти не работает.","Сведение в тренажёре: изоляция груди без трицепса."],"libEn":["Pectoralis major.","Front delts; the short head of the biceps. The triceps barely work.","Squeezes the chest on a fixed arc so the move stays a fly, not a press."],"libLv":["Lielais krūšu muskulis.","Priekšējie deltveida; bicepsa īsā galva. Tricepss gandrīz nestrādā.","Saspiež krūtis pa fiksētu loku, lai kustība paliek izvērse, nevis spiediens."],"tech":[["Спина к подушке, лопатки прижаты, предплечья на вертикальных подушках тренажёра, локти слегка согнуты и фиксированы.","Дуга сведения в горизонтальной плоскости; угол локтя не меняется.","Сведение перед грудью без удара; обратный ход до растяжения без провала плеча."],["Превращение в жим","избыточная растяжка передней капсулы плеча."],"До сведения перед грудью и обратного растяжения без вываливания плеч вперёд."],"techEn":[["Back on the pad, shoulder blades pressed in, forearms on the machine's vertical pads, elbows slightly bent and fixed.","A fly arc in the horizontal plane. The elbow angle does not change.","Bring the arms together in front of the chest without banging them. Return to a stretch without the shoulder dumping forward."],["Turning it into a press","Overstretching the front of the shoulder capsule"],"To the arms meeting in front of the chest, and back into a stretch, without the shoulders dumping forward."],"techLv":[["Mugura pret polsteri, lāpstiņas piespiestas, apakšdelmi uz trenažiera vertikālajiem polsteriem, elkoņi viegli saliekti un fiksēti.","Savilkšanas loks horizontālā plaknē. Elkoņa leņķis nemainās.","Savilkšana priekšā krūtīm bez sitiena. Atpakaļceļš līdz iestiepumam, plecam neizkrītot uz priekšu."],["Pārvēršana par spiedienu","Pārmērīga pleca priekšējās kapsulas iestiepšana"],"Līdz roku savilkšanai priekšā krūtīm un atpakaļ līdz iestiepumam, pleciem neizkrītot uz priekšu."]},{"id":"reverse-lunge-supported","name":"Выпады назад с опорой","group":"Ноги","meta":"gdb|k","nameEn":"Supported reverse lunge","nameLv":"Izklupiens atpakaļ ar balstu","lib":["Квадрицепс и ягодичные передней ноги.","Задняя поверхность бедра; приводящие. Средняя ягодичная и кор слабее, чем без опоры.","Выпад назад с опорой рукой: проще держать баланс."],"libEn":["Quads and glutes of the front leg.","Hamstrings; adductors. Glute medius and the core work less than without support.","Lets you learn the reverse lunge with a handhold so balance does not limit the leg."],"libLv":["Priekšējās kājas četrgalvainais un sēžas muskuļi.","Augšstilba aizmugure; pievilcējmuskuļi. Vidējais sēžas muskulis un korpuss strādā mazāk nekā bez balsta.","Ļauj apgūt izklupienu atpakaļ ar roku balstu, lai līdzsvars neierobežo kāju."],"tech":[["Одна рука на стойке или подвесных петлях. Стопы под бёдрами.","Шаг назад с лёгкой помощью опоры для баланса, таз опускается вертикально.","Оба колена около 90°. Возврат через переднюю стопу."],["Перенос веса на руку вместо ноги","завал колена."],"Оба колена около 90°, передняя пятка на полу."],"techEn":[["One hand on a rack or on suspension straps. Feet under the hips.","Step back, using the support lightly for balance. The hips drop straight down.","Both knees near 90°. Drive back up through the front foot."],["Putting the weight on the hand instead of the leg","Knee caving in"],"Both knees near 90°, front heel on the floor."],"techLv":[["Viena roka uz statīva vai piekares cilpām. Pēdas zem gurniem.","Solis atpakaļ, viegli palīdzoties ar balstu līdzsvaram. Gurni nolaižas vertikāli.","Abi ceļi ap 90°. Atgriešanās caur priekšējo pēdu."],["Svara pārnešana uz roku kājas vietā","Celis krīt uz iekšu"],"Abi ceļi ap 90°, priekšējais papēdis uz grīdas."]},{"id":"cable-crunch","name":"Скручивания на блоке","group":"Пресс","meta":"g|","nameEn":"Cable crunches","nameLv":"Vēdera preses saliekšana blokā","lib":["Прямая мышца живота.","Косые.","Скручивание на блоке для прямой мышцы живота."],"libEn":["Rectus abdominis.","Obliques.","Flexes the trunk against a cable so the abs do the work."],"libLv":["Taisnais vēdera muskulis.","Slīpie.","Saliec korpusu pret trosi, lai darbu veic vēdera prese."],"tech":[["На коленях лицом к верхнему блоку, канат у головы или верхней груди.","Сгибание корпуса вниз за счёт пресса, таз относительно стабилен.","Контролируемое сгибание, медленный возврат без прогиба поясницы."],["Тяга руками","движение тазом (сгибание в тазобедренных суставах) вместо сгибания корпуса."],"Сгибание корпуса в комфортном диапазоне без боли в пояснице."],"techEn":[["Kneel facing the high cable, with the rope at the head or the upper chest.","Curl the trunk down with the abs; the pelvis stays relatively still.","Controlled flexion, then a slow return without arching the lower back."],["Pulling with the arms","moving the pelvis (bending at the hips) instead of flexing the trunk."],"Trunk flexion through a comfortable range, without lower-back pain."],"techLv":[["Ceļos ar seju pret augšējo bloku, virve pie galvas vai krūšu augšdaļas.","Saliec korpusu uz leju ar vēdera presi; iegurnis paliek samērā nekustīgs.","Kontrolēta saliekšana, tad lēna atgriešanās bez jostasvietas ieliekuma."],["Vilkšana ar rokām","iegurņa kustība (saliekšana gūžās) korpusa saliekšanas vietā."],"Korpusa saliekšana ērtā amplitūdā, bez sāpēm jostasvietā."]},{"id":"plank-advanced","name":"Планка с усложнением","group":"Пресс","meta":"gdb|","nameEn":"Plank with added difficulty","nameLv":"Planka ar paaugstinātu grūtību","lib":["Прямая и поперечная мышцы живота.","Косые; ягодичные; плечи.","Планка с ногами выше: тяжелее обычной планки."],"libEn":["Rectus abdominis and transverse abdominis.","Obliques; glutes; shoulders.","Holds a straight body line in a harder plank, with the feet raised."],"libLv":["Taisnais un šķērseniskais vēdera muskulis.","Slīpie; sēžas muskuļi; pleci.","Notur taisnu ķermeņa līniju grūtākā plankā, ar pēdām uz paaugstinājuma."],"tech":[["Планка на предплечьях, стопы на устойчивом возвышении (скамья или бокс), тело прямой линией.","Статическое удержание: таз не провисает и не уходит вверх домиком, рёбра опущены.","Удержание без провисания таза, затем колени на пол.","Статическое удержание."],["Провисание таза","таз поднят домиком","выпячивание рёбер."],"Как у базовой планки: нейтральный позвоночник, прямая линия тела."],"techEn":[["Forearm plank, feet on a stable raise (a bench or a box), body in a straight line.","Static hold: the pelvis does not sag and does not pike up, ribs stay down.","Hold without the pelvis sagging, then bring the knees to the floor.","Static hold."],["Pelvis sagging","pelvis piked up","ribs flaring."],"Same as a basic plank: a neutral spine and a straight line through the body."],"techLv":[["Planka uz apakšdelmiem, pēdas uz stabila paaugstinājuma (sols vai bokss), ķermenis taisnā līnijā.","Statiska noturēšana: iegurnis neiekrīt un nepaceļas „mājiņā”, ribas nolaistas.","Noturi bez iegurņa iekrīšanas, tad nolaid ceļus uz grīdas.","Statiska noturēšana."],["Iegurņa iekrīšana","iegurnis pacelts „mājiņā”","ribu izvirzīšana."],"Tāpat kā pamata plankā: neitrāls mugurkauls un taisna ķermeņa līnija."]},{"id":"smith-bench","name":"Жим лёжа в Смите (горизонтальный)","group":"Грудь","meta":"g|","nameEn":"Flat bench press in the Smith machine","nameLv":"Horizontālā guļus spiešana Smitā","lib":["Большая грудная, акцент на грудино-рёберной порции.","Передние дельты; трицепс. Стабилизаторы плеча работают меньше, чем в жиме штанги лёжа, из-за направляющих.","Горизонтальный жим в Смите по направляющим."],"libEn":["Pectoralis major, with emphasis on the sternocostal portion.","Anterior deltoids; triceps. The shoulder stabilizers work less than in a barbell bench press because of the guide rails.","Trains the flat press on a fixed bar path."],"libLv":["Lielais krūšu muskulis, akcents uz krūšu-ribu daļu.","Priekšējie deltveida; tricepss. Pleca stabilizatori strādā mazāk nekā stieņa guļus spiešanā, jo ir vadotnes.","Trenē horizontālo spiešanu pa fiksētu stieņa ceļu."],"tech":[["Скамья под грифом так, чтобы внизу гриф касался середины груди, а вверху оказывался над плечами. Пять точек опоры, лопатки сведены. Страховочные упоры чуть ниже нижней точки.","Снять крючки и опускать гриф на среднюю грудь по фиксированной траектории рамы. Локти 45–75°.","Касание груди без отскока, жим до почти прямых рук. Крючки можно зацепить поворотом запястий."],["Скамья смещена так, что гриф падает на шею или живот","отскок","не ставить страховочные упоры."],"До касания середины груди без отскока и до почти прямых рук."],"techEn":[["Set the bench under the bar so the bar touches the mid-chest at the bottom and finishes over the shoulders at the top. Five points of contact, shoulder blades pulled together. Safety stops just below the bottom position.","Unhook and lower the bar to the mid-chest along the frame's fixed path. Elbows at 45–75°.","Touch the chest without bouncing, then press to nearly straight arms. Rotate the wrists to rehook the bar."],["Bench placed so the bar drops onto the neck or the stomach","bouncing","not setting the safety stops."],"Down to a mid-chest touch without a bounce, and up to nearly straight arms."],"techLv":[["Novieto solu zem stieņa tā, lai apakšā stienis skartu krūšu vidu, bet augšā būtu virs pleciem. Pieci atbalsta punkti, lāpstiņas savilktas. Drošības atdures nedaudz zem apakšējā punkta.","Noņem āķus un nolaid stieni uz krūšu vidu pa rāmja fiksēto ceļu. Elkoņi 45–75°.","Pieskaries krūtīm bez atsitiena, tad spied līdz gandrīz taisnām rokām. Pagriez plaukstas, lai aizķertu āķus."],["Sols nobīdīts tā, ka stienis krīt uz kakla vai vēdera","atsitiens","drošības atdures nav uzstādītas."],"Līdz pieskārienam krūšu vidum bez atsitiena un līdz gandrīz taisnām rokām."]},{"id":"smith-seated-press","name":"Жим сидя в Смите","group":"Плечи","meta":"g|p","nameEn":"Seated press in the Smith machine","nameLv":"Sēdus spiešana Smitā","lib":["Передние и средние дельты.","Трицепс; верх груди. Кор работает меньше, чем в жиме штанги стоя.","Жим сидя над головой в Смите."],"libEn":["Anterior and lateral deltoids.","Triceps; upper chest. The core works less than in a standing barbell press.","Trains an overhead press on a fixed path, with less load on the lower back."],"libLv":["Priekšējie un vidējie deltveida.","Tricepss; krūšu augšdaļa. Korpuss strādā mazāk nekā stieņa spiešanā stāvus.","Trenē spiešanu virs galvas pa fiksētu ceļu, ar mazāku slodzi jostasvietai."],"tech":[["Скамья со спинкой внутри рамы так, чтобы гриф в нижней точке был у верха груди, а вверху проходил перед лицом и заканчивался над плечами. Страховочные упоры чуть ниже верха груди.","Снять крючки и жать вдоль направляющих без прогиба поясницы и без шрага.","Почти прямые руки над головой. Опускание до верха груди."],["Скамья стоит так, что гриф идёт в лицо","сильный прогиб","шраг."],"От верха груди до почти прямых рук над головой при нейтральной пояснице."],"techEn":[["Place a bench with a backrest inside the frame so the bar is at the upper chest at the bottom, and at the top it passes in front of the face and finishes over the shoulders. Safety stops just below the upper chest.","Unhook and press along the rails without arching the lower back and without shrugging.","Nearly straight arms overhead. Lower to the upper chest."],["Bench set so the bar travels into the face","a strong arch","shrugging."],"From the upper chest to nearly straight arms overhead, with a neutral lower back."],"techLv":[["Novieto solu ar atzveltni rāmī tā, lai stienis apakšā būtu pie krūšu augšdaļas, bet augšā ietu gar seju un beigtos virs pleciem. Drošības atdures nedaudz zem krūšu augšdaļas.","Noņem āķus un spied gar vadotnēm bez jostasvietas ieliekuma un bez plecu raustīšanas.","Gandrīz taisnas rokas virs galvas. Nolaišana līdz krūšu augšdaļai."],["Sols novietots tā, ka stienis iet sejā","spēcīgs ieliekums","plecu raustīšana."],"No krūšu augšdaļas līdz gandrīz taisnām rokām virs galvas, ar neitrālu jostasvietu."]},{"id":"smith-upright-row","name":"Тяга широким хватом к груди в Смите","group":"Плечи","meta":"g|p","nameEn":"Wide-grip pull to the chest in the Smith machine","nameLv":"Plata tvēriena vilkme līdz krūtīm Smitā","lib":["Средние дельты; трапеции.","Передние дельты; бицепс.","Тяга широким хватом к груди в Смите для дельт и трапеций."],"libEn":["Lateral deltoids; trapezius.","Anterior deltoids; biceps.","Pulls a wide grip up to the chest to work the side delts and traps."],"libLv":["Vidējie deltveida; trapecveida.","Priekšējie deltveida; bicepss.","Velk platu tvērienu līdz krūtīm, lai noslogotu vidējos deltveida un trapecveida."],"tech":[["Стоя, гриф на прямых руках перед бёдрами, хват примерно в 1,5 раза шире плеч. Стопы под грифом или с поправкой на угол рамы.","Тяга вдоль направляющих, локти ведут в стороны-вверх.","Гриф до нижней груди. Локти не выше плеч."],["Узкий хват и локти выше плеч: выше риск импинджмента. Рывок. Тяга к подбородку."],"До нижней груди; локти максимум на высоте плеч."],"techEn":[["Stand with the bar on straight arms in front of the thighs, grip about 1.5 times shoulder width. Feet under the bar, or shifted to match the angle of the frame.","Pull along the rails, elbows leading out and up.","Bar to the lower chest. Elbows no higher than the shoulders."],["A narrow grip with the elbows above the shoulders raises the risk of impingement. Jerking the weight. Pulling to the chin."],"To the lower chest; elbows at shoulder height at most."],"techLv":[["Stāvus, stienis uz taisnām rokām augšstilbu priekšā, tvēriens aptuveni 1,5 reizes platāks par pleciem. Pēdas zem stieņa vai nobīdītas atbilstoši rāmja leņķim.","Velc gar vadotnēm, elkoņi vada uz sāniem un augšup.","Stienis līdz krūšu apakšai. Elkoņi ne augstāk par pleciem."],["Šaurs tvēriens un elkoņi virs pleciem: lielāks pleca sadursmes risks. Rāviens. Vilkme līdz zodam."],"Līdz krūšu apakšai; elkoņi ne augstāk par plecu augstumu."]},{"id":"smith-squat","name":"Приседания в Смите","group":"Ноги","meta":"g|sk","nameEn":"Squats in the Smith machine","nameLv":"Pietupieni Smitā","lib":["Квадрицепс; ягодичные.","Приводящие; камбаловидная; разгибатели спины; кор. Стабилизаторы работают меньше, чем в приседаниях со штангой, из-за направляющих.","Присед в Смите: ноги работают, баланс держит рама."],"libEn":["Quadriceps; glutes.","Adductors; soleus; spinal erectors; core. The stabilizers work less than in a barbell squat because of the guide rails.","Loads a squat while the rails take care of most of the balance."],"libLv":["Četrgalvainais; sēžas muskuļi.","Pievilcēji; plekstveida muskulis; muguras taisnotāji; korpuss. Stabilizatori strādā mazāk nekā pietupienos ar stieni, jo ir vadotnes.","Noslogo pietupienu, kamēr vadotnes uzņemas lielāko daļu līdzsvara."],"tech":[["Гриф на верхе трапеций (высокое положение грифа). Стопы обычно чуть впереди линии грифа, на ширине плеч, носки слегка наружу. Крючки сняты, страховочные упоры чуть ниже нижней точки.","Одновременное сгибание бёдер и коленей вдоль фиксированной траектории. Колени по носкам, пятки на полу.","Складка бедра на уровне колена или ниже при нейтральной спине. Подъём до полного разгибания."],["Копировать постановку стоп свободного приседа без поправки на направляющие","встать лицом не в ту сторону на наклонной раме","не ставить страховочные упоры."],"До параллели или ниже при пятках на полу и нейтральной спине."],"techEn":[["Bar on the upper traps (high-bar position). Feet usually a little in front of the bar, about shoulder width, toes slightly out. Hooks off, safety stops just below the bottom.","Bend the hips and knees together along the fixed path. Knees track the toes, heels stay on the floor.","Hip crease at knee height or below, with a neutral back. Stand up to full extension."],["Copying a free-squat stance without adjusting for the rails","facing the wrong way on an angled frame","not setting the safety stops."],"To parallel or below, with the heels down and a neutral back."],"techLv":[["Stienis uz trapecveida augšdaļas (augstais stieņa novietojums). Pēdas parasti nedaudz priekšā stienim, aptuveni plecu platumā, pirksti viegli uz āru. Āķi noņemti, drošības atdures nedaudz zem apakšējā punkta.","Saliec gūžas un ceļus vienlaikus pa fiksēto ceļu. Ceļi virzienā uz pirkstiem, papēži uz grīdas.","Gūžas locījums ceļa augstumā vai zemāk, ar neitrālu muguru. Pieceļies līdz pilnai iztaisnošanai."],["Brīvā pietupiena pēdu novietojuma kopēšana bez korekcijas vadotnēm","nostāšanās ar seju nepareizā virzienā slīpā rāmī","drošības atdures nav uzstādītas."],"Līdz paralēlei vai zemāk, ar papēžiem uz grīdas un neitrālu muguru."]},{"id":"smith-bss","name":"Болгарские выпады в Смите","group":"Ноги","meta":"g|k","nameEn":"Bulgarian lunges in the Smith machine","nameLv":"Bulgāru izklupieni Smitā","lib":["Квадрицепс и ягодичные передней ноги.","Приводящие; икры; средняя ягодичная. Баланс держать легче, чем в болгарских сплит-приседаниях со свободным весом, из-за направляющих.","Болгарский сплит-присед в Смите."],"libEn":["Quadriceps and glutes of the front leg.","Adductors; calves; gluteus medius. Balance is easier to hold than in free-weight Bulgarian split squats because of the guide rails.","Loads one leg in a Bulgarian lunge while the rails steady you."],"libLv":["Priekšējās kājas četrgalvainais un sēžas muskuļi.","Pievilcēji; ikri; vidējais sēžas muskulis. Līdzsvaru ir vieglāk noturēt nekā brīvā svara bulgāru dalītajos pietupienos, jo ir vadotnes.","Noslogo vienu kāju bulgāru izklupienā, vadotnēm atvieglojot līdzsvaru."],"tech":[["Гриф на верхе трапеций. Задняя стопа на скамье, передняя достаточно впереди, чтобы пятка не отрывалась. Страховочные упоры установлены.","Таз опускается вниз вдоль направляющих, заднее колено к полу.","Переднее бедро примерно параллельно полу. Подъём через переднюю стопу."],["Передняя стопа слишком близко","толчок задней ногой","прогиб поясницы."],"До параллели переднего бедра при пятке на полу."],"techEn":[["Bar on the upper traps. Rear foot on a bench, front foot far enough forward that the heel stays down. Safety stops are set.","Lower the hips straight down along the rails, rear knee toward the floor.","Front thigh about parallel to the floor. Drive up through the front foot."],["Front foot too close","pushing off the back leg","arching the lower back."],"To a parallel front thigh, with the heel on the floor."],"techLv":[["Stienis uz trapecveida augšdaļas. Aizmugurējā pēda uz sola, priekšējā pietiekami tālu priekšā, lai papēdis paliktu uz grīdas. Drošības atdures ir uzstādītas.","Laid iegurni taisni lejup gar vadotnēm, aizmugurējais celis virzienā uz grīdu.","Priekšējais augšstilbs aptuveni paralēli grīdai. Pacelies caur priekšējo pēdu."],["Priekšējā pēda pārāk tuvu","atspēriens ar aizmugurējo kāju","jostasvietas ieliekums."],"Līdz priekšējā augšstilba paralēlei, ar papēdi uz grīdas."]},{"id":"smith-hip-thrust","name":"Ягодичный мост в Смите (плечи на скамье)","group":"Ноги","meta":"g|","nameEn":"Glute bridge in the Smith machine (shoulders on a bench)","nameLv":"Sēžas tilts Smitā (pleci uz sola)","lib":["Ягодичные (большая ягодичная).","Задняя поверхность бедра; приводящие.","Ягодичный мост со штангой в Смите, плечи на скамье."],"libEn":["Glutes (gluteus maximus).","Hamstrings; adductors.","Drives the hips up against the bar so the glutes work hard at full extension."],"libLv":["Sēžas muskuļi (lielais sēžas muskulis).","Augšstilba aizmugure; pievilcēji.","Dzen gūžas augšup pret stieni, lai sēžas muskuļi strādātu pilnā iztaisnojumā."],"tech":[["Верх спины на скамье перпендикулярно направляющим. Гриф в сгибе бёдер с подушкой. Стопы так, чтобы вверху голени были вертикальны. Крючки сняты.","Разгибание бёдер через пятки вдоль направляющих. Рёбра опущены.","Полное разгибание бёдер без гиперлордоза: линия плечи–бёдра–колени. Медленное опускание."],["Прогиб поясницей вместо бёдер","скамья стоит так, что в верхней точке нет линии плечи–бёдра–колени."],"До прямой линии плечи–бёдра–колени без переразгибания поясницы."],"techEn":[["Upper back on a bench set perpendicular to the rails. Bar in the hip crease, with a pad. Feet placed so the shins are vertical at the top. Hooks off.","Extend the hips through the heels along the rails. Ribs stay down.","Full hip extension without hyperextending the lower back: shoulders, hips, and knees in one line. Lower slowly."],["Arching the lower back instead of moving the hips","bench placed so the top has no shoulder–hip–knee line."],"To a straight shoulder–hip–knee line, without overextending the lower back."],"techLv":[["Muguras augšdaļa uz sola, kas stāv perpendikulāri vadotnēm. Stienis gūžas locījumā, ar polsteri. Pēdas tā, lai augšā apakšstilbi būtu vertikāli. Āķi noņemti.","Iztaisno gūžas caur papēžiem gar vadotnēm. Ribas nolaistas.","Pilna gūžu iztaisnošana bez pārliektas jostasvietas: pleci, gūžas un ceļi vienā līnijā. Lēna nolaišana."],["Ieliekums ar jostasvietu gūžu kustības vietā","sols novietots tā, ka augšā nav līnijas pleci–gūžas–ceļi."],"Līdz taisnai līnijai pleci–gūžas–ceļi, bez jostasvietas pārliekšanas."]},{"id":"hip-adduction","name":"Сведение бедра в тренажёре","group":"Ноги","meta":"g|","nameEn":"Thigh adduction in a machine","nameLv":"Augšstilbu savilkšana trenažierī","lib":["Приводящие мышцы бедра (длинная, большая, короткая; тонкая).","Других значимых рабочих мышц нет: движение изолирующее.","Изоляция приводящих мышц бедра."],"libEn":["Hip adductors (adductor longus, magnus, and brevis; gracilis).","No other meaningful working muscles: the movement is isolated.","Squeezes the thighs together to strengthen the adductors."],"libLv":["Augšstilba pievilcējmuskuļi (garais, lielais un īsais; smalkais muskulis).","Citu nozīmīgu darba muskuļu nav: kustība ir izolēta.","Savieno augšstilbus, lai stiprinātu pievilcējus."],"tech":[["Сидя в тренажёре для сведения, подушки изнутри коленей или бёдер, таз прижат.","Сведение бёдер против сопротивления без отрыва таза.","Бёдра сближаются в комфортном диапазоне, медленный возврат."],["Рывок","отрыв таза","сводить через боль в паху."],"До сведения без боли в приводящих и тазобедренном суставе."],"techEn":[["Sit in the adduction machine, pads inside the knees or thighs, pelvis pressed into the seat.","Bring the thighs together against the resistance without lifting the pelvis.","The thighs come together through a comfortable range, then return slowly."],["Jerking","lifting the pelvis","squeezing through groin pain."],"To full adduction, without pain in the adductors or the hip."],"techLv":[["Sēdi savilkšanas trenažierī, polsteri ceļu vai augšstilbu iekšpusē, iegurnis piespiests sēdeklim.","Savieno augšstilbus pret pretestību, neatraujot iegurni.","Augšstilbi tuvojas ērtā amplitūdā, tad lēna atgriešanās."],["Rāviens","iegurņa atraušana","savilkšana caur sāpēm cirkšņos."],"Līdz savilkšanai, bez sāpēm pievilcējos vai gūžā."]},{"id":"incline-db-fly","name":"Разводка гантелей на наклонной скамье","group":"Грудь","meta":"gd|p","nameEn":"Dumbbell fly on an incline bench","nameLv":"Hanteļu izvēršana slīpā solā","lib":["Большая грудная, акцент на ключичной порции относительно горизонтальной разводки.","Передние дельты; короткая головка бицепса. Трицепс почти не работает — это не жим.","Разводка на наклонной скамье для верха груди."],"libEn":["Pectoralis major, with more emphasis on the clavicular portion than in a flat fly.","Anterior deltoids; short head of the biceps. The triceps barely work — this is not a press.","Opens and closes the arms on an incline to stretch and squeeze the upper chest."],"libLv":["Lielais krūšu muskulis, lielāks akcents uz atslēgas kaula daļu nekā horizontālajā izvēršanā.","Priekšējie deltveida; bicepsa īsā galva. Tricepss gandrīz nestrādā — tā nav spiešana.","Atver un aizver rokas slīpumā, lai izstieptu un savilktu krūšu augšdaļu."],"tech":[["Спинка 30–45°. Гантели над верхней грудью, локти слегка согнуты и фиксированы.","Руки расходятся дугой в стороны. Угол локтя почти не меняется.","Сведение над верхней грудью без удара; внизу — растяжение без провала плеча."],["Разгибание локтей (превращение в жим)","избыточная растяжка передней капсулы плеча."],"Опускать примерно до линии туловища или чуть ниже, пока плечо не проваливается вперёд."],"techEn":[["Backrest at 30–45°. Dumbbells over the upper chest, elbows slightly bent and held at that angle.","The arms open out to the sides in an arc. The elbow angle barely changes.","Squeeze over the upper chest without clanking the dumbbells; at the bottom, a stretch without the shoulder dumping forward."],["Straightening the elbows (turning it into a press)","overstretching the front of the shoulder capsule."],"Lower to about torso level or slightly below, as long as the shoulder does not roll forward."],"techLv":[["Atzveltne 30–45°. Hanteles virs krūšu augšdaļas, elkoņi viegli saliekti un turēti šajā leņķī.","Rokas atveras uz sāniem pa loku. Elkoņa leņķis gandrīz nemainās.","Savilc virs krūšu augšdaļas, nesitot hanteles kopā; apakšā — stiepums, plecam neiekrītot uz priekšu."],["Elkoņu iztaisnošana (pārvēršas par spiešanu)","pārmērīgs pleca priekšējās kapsulas stiepums."],"Laid lejā aptuveni līdz korpusa līmenim vai nedaudz zemāk, kamēr plecs neiekrīt uz priekšu."]},{"id":"meadows-row","name":"Тяга Мидоу","group":"Спина","meta":"g|s","nameEn":"Meadows row","nameLv":"Meadows vilkme","lib":["Широчайшие; ромбовидные; средняя трапеция рабочей стороны.","Задняя дельта; бицепс.","Тяга одного конца штанги из угла. Для опытных."],"libEn":["Lats; rhomboids; mid trapezius of the working side.","Posterior deltoid; biceps.","Rows one end of a landmine bar toward the hip through a long lat stretch."],"libLv":["Platie muguras muskuļi; rombveida; darba puses vidējais trapecveida.","Aizmugurējais deltveida; bicepss.","Velk lendmaina stieņa galu pret gūžu caur garu plato muguras muskuļu stiepumu."],"tech":[["Один конец грифа в угловом упоре (лэндмайн) или в углу стены. Встать боком к грифу, в шахматной стойке, взять толстый конец хватом сверху. Корпус в шарнире, спина нейтральна.","Тяга конца грифа к нижней части рёбер / к тазу рабочей стороны, локоть уходит назад и слегка в сторону, лопатка сводится.","Короткая пауза у корпуса, медленный спуск до растяжения без округления спины."],["Скручивание корпуса","рывок поясницей","превращение в шраг."],"От растяжения широчайших внизу до локтя у корпуса."],"techEn":[["One end of the bar in a corner support (landmine) or in the corner of a wall. Stand side-on to the bar in a staggered stance and take the thick end with an overhand grip. Hinge at the hips, back neutral.","Pull the end of the bar toward the lower ribs or the hip on the working side. The elbow travels back and slightly out, and the shoulder blade pulls in.","A short pause by the torso, then lower slowly into the stretch without rounding the back."],["Twisting the torso","jerking with the lower back","turning it into a shrug."],"From a lat stretch at the bottom to the elbow beside the torso."],"techLv":[["Viens stieņa gals stūra atbalstā (lendmaine) vai sienas stūrī. Stājies sāniski pret stieni ar vienu pēdu priekšā un satver resno galu ar tvērienu no augšas. Noliecies no gurniem, mugura neitrāla.","Velc stieņa galu uz darba puses apakšējām ribām vai gūžu. Elkonis iet atpakaļ un nedaudz uz sāniem, lāpstiņa savienojas.","Īsa pauze pie korpusa, tad lēni nolaid līdz stiepumam, neapaļojot muguru."],["Korpusa griešana","rāviens ar jostasvietu","pārvēršana par plecu raustīšanu."],"No plato muguras muskuļu stiepuma apakšā līdz elkonim pie korpusa."]},{"id":"single-arm-cable-lateral","name":"Разведения на нижнем блоке одной рукой","group":"Плечи","meta":"g|","nameEn":"Single-arm raises on the low cable","nameLv":"Vienas rokas sānu pacelšana apakšējā blokā","lib":["Средние дельты.","Надостная (работает вместе с дельтой по всей амплитуде); передние дельты; трапеции (не должны доминировать).","Мах в сторону на нижнем блоке с постоянным натяжением."],"libEn":["Lateral deltoids.","Supraspinatus (it works with the deltoid through the whole range); anterior deltoids; trapezius (it should not take over).","Raises one arm out to the side with steady tension from a low cable."],"libLv":["Vidējie deltveida.","Virsšķautnes muskulis (strādā kopā ar deltveida visā amplitūdā); priekšējie deltveida; trapecveida (nedrīkst pārņemt kustību).","Ceļ vienu roku uz sāniem ar pastāvīgu spriegumu no apakšējā bloka."],"tech":[["Стоя боком к нижнему блоку, рукоять в дальней от блока руке, трос проходит перед корпусом, лёгкий фиксированный сгиб локтя, плечо опущено.","Подъём руки в плоскости лопатки до уровня плеча. Постоянное натяжение троса.","Плечо примерно параллельно полу. Медленное опускание, не бросая трос."],["Раскачка","шраг","подъём сильно выше плеч."],"До линии плеч. Выше часто перехватывает верхняя трапеция."],"techEn":[["Stand side-on to the low cable, handle in the hand farther from the stack, cable passing in front of the body, a small fixed bend in the elbow, shoulder down.","Raise the arm in the scapular plane to shoulder height. Keep the cable under tension the whole time.","Upper arm about parallel to the floor. Lower slowly; do not let the cable drop."],["Swinging","shrugging","lifting well above the shoulders."],"To shoulder height. Above that, the upper traps often take over."],"techLv":[["Stāvies sāniski pret apakšējo bloku, rokturis rokā, kas tālāk no bloka, trose iet korpusa priekšā, neliels fiksēts elkoņa saliekums, plecs nolaists.","Cel roku lāpstiņas plaknē līdz pleca augstumam. Trosi turi nospriegotu visu laiku.","Augšdelms aptuveni paralēli grīdai. Nolaid lēni; neļauj trosei krist."],["Šūpošanās","plecu raustīšana","pacelšana krietni virs pleciem."],"Līdz plecu augstumam. Augstāk kustību bieži pārņem trapecveida augšdaļa."]},{"id":"incline-db-curl","name":"Сгибания рук с гантелями на наклонной скамье","group":"Бицепс","meta":"gd|","nameEn":"Dumbbell curls on an incline bench","nameLv":"Hanteļu saliekšana slīpā solā","lib":["Бицепс; длинная головка сильнее растянута, потому что рука свисает позади корпуса.","Плечевая; предплечья.","Сгибания на наклонной скамье: бицепс в растянутом положении."],"libEn":["Biceps; the long head is stretched harder because the arm hangs behind the torso.","Brachialis; forearms.","Curls the biceps from a stretched hang behind the torso."],"libLv":["Bicepss; garā galva ir stiprāk izstiepta, jo roka karājas aiz korpusa.","Pleca muskulis; apakšdelmi.","Saliec bicepsu no izstieptas karāšanās aiz korpusa."],"tech":[["Сидя на наклонной скамье 45–60°, руки свободно свисают, локти чуть позади корпуса, ладони вперёд или начинают нейтрально и супинируют.","Сгибание только в локте. Плечо не выезжает вперёд.","Полное сгибание без заброса локтей. Медленное опускание до почти прямой руки."],["Раскачка корпуса","вынос локтей вперёд","слишком крутой наклон, если болит спереди плеча."],"От почти прямой свисающей руки до полного сгибания без заброса локтя."],"techEn":[["Sit on a 45–60° incline bench, arms hanging free, elbows slightly behind the torso, palms facing forward or starting neutral and then supinating.","Bend only at the elbow. The upper arm does not travel forward.","A full curl without throwing the elbows forward. Lower slowly to a nearly straight arm."],["Rocking the torso","driving the elbows forward","an incline that is too steep if the front of the shoulder hurts."],"From a nearly straight hanging arm to a full curl, without throwing the elbow forward."],"techLv":[["Sēdi slīpā solā 45–60°, rokas brīvi karājas, elkoņi nedaudz aiz korpusa, plaukstas uz priekšu vai sāc neitrāli un tad supinē.","Locies tikai elkonī. Augšdelms nevirzās uz priekšu.","Pilna saliekšana, nemetot elkoņus uz priekšu. Nolaid lēni līdz gandrīz taisnai rokai."],["Korpusa šūpošana","elkoņu dzīšana uz priekšu","pārāk stāvs slīpums, ja sāp pleca priekšpuse."],"No gandrīz taisnas karājošās rokas līdz pilnai saliekšanai, nemetot elkoni uz priekšu."]},{"id":"wrist-curl","name":"Сгибания запястий","group":"Бицепс","meta":"gd|","nameEn":"Wrist curls","nameLv":"Plaukstas locītavu saliekšana","lib":["Сгибатели запястья и пальцев (лучевой и локтевой сгибатели запястья, поверхностный сгибатель пальцев и др.).","Других значимых рабочих мышц нет; бицепс почти не участвует — локоть не двигается.","Сгибание запястий. Только добивка после основной работы на бицепс."],"libEn":["Wrist and finger flexors (flexor carpi radialis and flexor carpi ulnaris, flexor digitorum superficialis, and others).","No other meaningful working muscles; the biceps barely takes part — the elbow does not move.","Isolates wrist flexion to strengthen the grip and the front of the forearm."],"libLv":["Plaukstas un pirkstu saliecēji (spieķkaula un elkoņa kaula plaukstas saliecēji, virspusējais pirkstu saliecējs u. c.).","Citu nozīmīgu darba muskuļu nav; bicepss gandrīz nepiedalās — elkonis nekustas.","Izolē plaukstas saliekšanu, lai stiprinātu tvērienu un apakšdelma priekšpusi."],"tech":[["Сидя, предплечья на бёдрах или на скамье, ладони вверх, запястья чуть за краем опоры, гриф в пальцах.","Сгибание только в запястьях, поднимая ладони к себе. Предплечья неподвижны.","Полное сгибание запястья, медленное опускание до растяжения сгибателей."],["Сгибание локтей","рывок всем предплечьем","боль в запястье."],"От тыльного растяжения до полного ладонного сгибания в безболевом диапазоне."],"techEn":[["Sit with the forearms on the thighs or a bench, palms up, wrists just past the edge of the support, bar held in the fingers.","Bend only at the wrists, curling the palms toward you. The forearms stay still.","Full wrist flexion, then a slow lower into a stretch of the flexors."],["Bending the elbows","jerking with the whole forearm","pain in the wrist."],"From a stretch on the back of the wrist to full palm flexion, in a pain-free range."],"techLv":[["Sēdi, apakšdelmi uz augšstilbiem vai sola, plaukstas uz augšu, plaukstas locītavas nedaudz aiz atbalsta malas, stienis pirkstos.","Locies tikai plaukstas locītavās, tinot plaukstas pret sevi. Apakšdelmi paliek nekustīgi.","Pilna plaukstas locītavas saliekšana, tad lēna nolaišana līdz saliecēju stiepumam."],["Elkoņu saliekšana","rāviens ar visu apakšdelmu","sāpes plaukstas locītavā."],"No stiepuma plaukstas locītavas mugurpusē līdz pilnai plaukstas saliekšanai, nesāpīgā amplitūdā."]},{"id":"reverse-wrist-curl","name":"Разгибания запястий","group":"Бицепс","meta":"gd|","nameEn":"Wrist extensions","nameLv":"Plaukstas locītavu iztaisnošana","lib":["Разгибатели запястья и пальцев (длинный и короткий лучевые разгибатели запястья, локтевой разгибатель запястья и др.).","Других значимых рабочих мышц нет; бицепс почти не участвует — локоть не двигается.","Разгибание запястий. Только добивка, не вместо сгибаний рук."],"libEn":["Wrist and finger extensors (extensor carpi radialis longus and brevis, extensor carpi ulnaris, and others).","No other meaningful working muscles; the biceps barely takes part — the elbow does not move.","Isolates wrist extension so it can balance the stronger forearm flexors."],"libLv":["Plaukstas un pirkstu atliecēji (garais un īsais spieķkaula plaukstas atliecēji, elkoņa kaula plaukstas atliecējs u. c.).","Citu nozīmīgu darba muskuļu nav; bicepss gandrīz nepiedalās — elkonis nekustas.","Izolē plaukstas iztaisnošanu, lai tā līdzsvarotu spēcīgākos apakšdelma saliecējus."],"tech":[["Сидя, предплечья на опоре, ладони вниз, запястья чуть за краем, гриф хватом сверху.","Разгибание только в запястьях (тыльное сгибание), предплечья неподвижны.","Полное доступное разгибание, медленное опускание."],["Сгибание локтей","рывок","слишком большой вес (разгибатели слабее сгибателей)."],"От ладонного свисания до полного тыльного разгибания без боли."],"techEn":[["Sit with the forearms on a support, palms down, wrists just past the edge, bar in an overhand grip.","Extend only at the wrists (bend the back of the hand up). The forearms stay still.","As much extension as you have, then lower slowly."],["Bending the elbows","jerking","too much weight (the extensors are weaker than the flexors)."],"From the hands hanging down on the palm side to full wrist extension, without pain."],"techLv":[["Sēdi, apakšdelmi uz atbalsta, plaukstas uz leju, plaukstas locītavas nedaudz aiz malas, stienis ar tvērienu no augšas.","Iztaisno tikai plaukstas locītavas (cel delnas muguru augšup). Apakšdelmi paliek nekustīgi.","Tik daudz iztaisnošanas, cik ir pieejams, tad nolaid lēni."],["Elkoņu saliekšana","rāviens","pārāk liels svars (atliecēji ir vājāki par saliecējiem)."],"No plaukstu nokarāšanās delnas pusē līdz pilnai plaukstas iztaisnošanai, bez sāpēm."]},{"id":"pallof-press","name":"Жим Паллофа (антиротация на блоке)","group":"Пресс","meta":"g|","nameEn":"Pallof press (anti-rotation on a cable)","nameLv":"Pallofa spiešana (pretrotācija blokā)","lib":["Косые и поперечная мышца живота (антиротация).","Прямая мышца живота; ягодичные и средняя ягодичная как стабилизаторы таза.","Жим вперёд боком к блоку: корпус сопротивляется повороту."],"libEn":["Obliques and transverse abdominis (anti-rotation).","Rectus abdominis; glutes and gluteus medius as stabilizers of the pelvis.","Teaches the trunk to resist being twisted by a cable."],"libLv":["Slīpie un šķērseniskais vēdera muskulis (pretrotācija).","Taisnais vēdera muskulis; sēžas muskuļi un vidējais sēžas muskulis kā iegurņa stabilizatori.","Māca korpusam pretoties trosei, kas griež ķermeni."],"tech":[["Стоя боком к блоку на высоте груди, рукоять двумя руками у груди, стопы на ширине таза, кор напряжён. Трос натягивает корпус к повороту — этому нужно сопротивляться.","Выжать рукоять прямо вперёд до прямых рук, не поворачивая плечи и таз к блоку. Пауза.","Медленно вернуть рукоять к груди, всё ещё не вращаясь."],["Поворот корпуса за тросом","наклон в сторону","слишком большой вес с потерей нейтрали."],"От рукояти у груди до прямых рук перед грудиной. Поворот корпуса не является целью."],"techEn":[["Stand side-on to a cable set at chest height, handle in both hands at the chest, feet about hip-width, core braced. The cable pulls the torso into a turn — resist that.","Press the handle straight forward to straight arms, without turning the shoulders or the pelvis toward the stack. Pause.","Bring the handle back to the chest slowly, still without rotating."],["Turning the torso with the cable","leaning to the side","so much weight that you lose a neutral position."],"From the handle at the chest to straight arms in front of the sternum. Turning the torso is not the goal."],"techLv":[["Stāvies sāniski pret bloku krūšu augstumā, rokturis abās rokās pie krūtīm, pēdas aptuveni iegurņa platumā, korpuss sasprindzināts. Trose velk korpusu griezienā — pretojies tam.","Izspied rokturi taisni uz priekšu līdz taisnām rokām, nepagriežot plecus vai iegurni pret bloku. Pauze.","Atgriez rokturi pie krūtīm lēni, joprojām negriežoties."],["Korpusa pagriešanās līdzi trosei","noliekšanās uz sāniem","tik liels svars, ka zūd neitrāls stāvoklis."],"No roktura pie krūtīm līdz taisnām rokām krūšu kaula priekšā. Korpusa griešana nav mērķis."]},{"id":"standing-ab-wheel","name":"Ролик для пресса стоя","group":"Пресс","meta":"gd|s","nameEn":"Standing ab wheel","nameLv":"Vēdera rullītis stāvus","lib":["Прямая мышца живота.","Косые; широчайшие; плечи; сгибатели бедра.","Ролик стоя. Очень длинный рычаг, только после уверенного варианта с колен."],"libEn":["Rectus abdominis.","Obliques; lats; shoulders; hip flexors.","Rolls the body out from standing so the abs have to resist an arch in the lower back."],"libLv":["Taisnais vēdera muskulis.","Slīpie; platie muguras muskuļi; pleci; gūžas saliecēji.","Izritina ķermeni no stāvus, lai vēdera presei jāpretojas jostasvietas ieliekumam."],"tech":[["Стоя, наклон от таза, руки на ролике перед стопами; таз слегка подкручен, рёбра опущены, поясница не прогибается; верх спины может быть слегка округлён.","Качение вперёд почти до линии тела у пола, сопротивление прогибу поясницы (антиразгибание).","Насколько позволяет контроль поясницы, затем возврат к стопам за счёт пресса и широчайших, выход обратно в наклон и стойку."],["Прогиб поясницы — главная ошибка","падение в растянутую позицию","переход к стоячему варианту, не освоив ролик с колен."],"Только пока удаётся не прогибать поясницу. Рычаг гораздо длиннее, чем у ролика с коленей."],"techEn":[["Stand and hinge from the hips, hands on the wheel in front of the feet; pelvis slightly tucked, ribs down, lower back not arched; the upper back may round a little.","Roll forward until the body is almost in a straight line near the floor, resisting an arch in the lower back (anti-extension).","Go only as far as the lower back stays under control, then return to the feet with the abs and lats, back into the hinge and up to standing."],["Arching the lower back — the main mistake","collapsing into the stretched-out position","moving on to the standing version before the kneeling wheel is solid."],"Only while you can keep the lower back from arching. The lever is much longer than in the kneeling wheel."],"techLv":[["Stāvies un noliecies no gurniem, rokas uz rullīša pēdu priekšā; iegurnis viegli pagriezts atpakaļ, ribas nolaistas, jostasvieta neieliecas; muguras augšdaļa var būt nedaudz apaļa.","Ritinies uz priekšu, līdz ķermenis ir gandrīz taisnā līnijā pie grīdas, pretojoties jostasvietas ieliekumam (pretizliekšanās).","Ej tikai tik tālu, cik jostasvieta paliek kontrolē, tad atgriezies pie pēdām ar vēdera presi un platajiem muguras muskuļiem, atpakaļ noliekumā un stājā."],["Jostasvietas ieliekums — galvenā kļūda","iekrīšana izstieptajā pozīcijā","pāreja uz stāvus variantu, pirms rullītis no ceļiem ir apgūts."],"Tikai tikmēr, kamēr izdodas neieliekt jostasvietu. Svira ir krietni garāka nekā rullītim no ceļiem."]},{"id":"farmers-walk","name":"Фермерская прогулка","group":"Ноги","meta":"gd|","nameEn":"Farmer's walk","nameLv":"Fermera pastaiga","lib":["Предплечья и хват; верх трапеций; мышцы кора.","Ягодичные, квадрицепс и икры как локомоторные мышцы шага.","Ходьба с тяжёлыми снарядами в обеих руках: хват, осанка, ноги."],"libEn":["Forearms and grip; upper traps; core muscles.","Glutes, quadriceps, and calves as the muscles that carry the walk.","Walks with heavy weights at the sides to build grip, posture, and a stiff trunk."],"libLv":["Apakšdelmi un tvēriens; trapecveida augšdaļa; korpusa muskuļi.","Sēžas muskuļi, četrgalvainais un ikri kā soļošanas muskuļi.","Soļo ar smagiem svariem sānos, lai veidotu tvērienu, stāju un stingru korpusu."],"tech":[["Две тяжёлые гантели в опущенных руках по бокам, грудь раскрыта, плечи опущены, взгляд вперёд.","Ровная ходьба короткими устойчивыми шагами, снаряды не раскачиваются, корпус не заваливается.","Несколько шагов по прямой с сохранением осанки. Постановка снарядов — контролируемая, не бросок."],["Шраг к ушам","раскачка снарядов","скругленные плечи","бег."],"Полный шаг при нейтральном позвоночнике, снаряды удерживаются вдоль тела."],"techEn":[["A heavy dumbbell in each straight arm at your sides, chest open, shoulders down, eyes forward.","Walk evenly with short, stable steps. The weights do not swing, and the torso does not tip.","Several steps in a straight line while posture holds. Set the weights down under control, do not drop them."],["Shrugging up toward the ears","weights swinging","rounded shoulders","running."],"A full stride with a neutral spine, weights held alongside the body."],"techLv":[["Smaga hantele katrā taisnā rokā sānos, krūtis atvērtas, pleci nolaisti, skatiens uz priekšu.","Soļo vienmērīgi ar īsiem, stabiliem soļiem. Svari nešūpojas, un korpuss neapgāžas.","Vairāki soļi taisnā līnijā, kamēr stāja turas. Noliec svarus kontrolēti, nemet zemē."],["Plecu raustīšana augšup pret ausīm","svaru šūpošanās","apaļi pleci","skriešana."],"Pilns solis ar neitrālu mugurkaulu, svari turēti gar ķermeni."]},{"id":"suitcase-carry","name":"Прогулка с гантелью в одной руке („чемодан“)","group":"Пресс","meta":"gd|","nameEn":"One-dumbbell walk (\"suitcase\")","nameLv":"Pastaiga ar hanteli vienā rokā („čemodāns”)","lib":["Косые мышцы живота и квадратная мышца поясницы противоположной стороны (антинаклон).","Хват рабочей руки; средняя ягодичная; кор в целом.","Ходьба с гантелью в одной руке: корпус не заваливается в сторону."],"libEn":["Obliques and quadratus lumborum on the opposite side (resisting a side bend).","Grip of the working arm; gluteus medius; the core as a whole.","Walks with a weight on one side so the trunk has to stay level."],"libLv":["Slīpie vēdera muskuļi un pretējās puses jostas kvadrātmuskulis (pretošanās sānu noliekumam).","Darba rokas tvēriens; vidējais sēžas muskulis; korpuss kopumā.","Soļo ar svaru vienā pusē, lai korpusam jāpaliek līmenī."],"tech":[["Один снаряд в опущенной руке сбоку, как чемодан. Свободная рука вдоль тела. Плечи и таз горизонтальны.","Ходьба по прямой без бокового наклона к снаряду или от него.","Несколько шагов с ровным тазом. Контролируемая постановка снаряда."],["Наклон к весу","подъём противоположного плеча","скручивание корпуса."],"Полный шаг при горизонтальных плечах и тазе."],"techEn":[["One weight in a straight arm at your side, like a suitcase. The free arm hangs along the body. Shoulders and pelvis stay level.","Walk in a straight line without leaning toward the weight or away from it.","Several steps with a level pelvis. Set the weight down under control."],["Leaning toward the weight","hiking the opposite shoulder","twisting the torso."],"A full stride with the shoulders and pelvis level."],"techLv":[["Viens svars taisnā rokā sānos, kā čemodāns. Brīvā roka gar ķermeni. Pleci un iegurnis paliek līmenī.","Soļo taisni, nenoliecoties pret svaru vai prom no tā.","Vairāki soļi ar līdzenu iegurni. Noliec svaru kontrolēti."],["Noliekšanās pret svaru","pretējā pleca pacelšana","korpusa griešana."],"Pilns solis ar pleciem un iegurni līmenī."]},{"id":"kettlebell-swing","name":"Махи гирей","group":"Ноги","meta":"gd|s","nameEn":"Kettlebell swings","nameLv":"Svaru bumbas šūpoles","lib":["Ягодичные; задняя поверхность бедра.","Разгибатели спины; кор; передние дельты и хват держат гирю. Это баллистический шарнир, не присед.","Баллистический мах гирей от таза. Нужна поставленная техника шарнира."],"libEn":["Glutes; hamstrings.","Spinal erectors; core; the anterior deltoids and the grip hold the kettlebell. This is a ballistic hinge, not a squat.","Drives the hips to swing the bell instead of lifting it with the arms."],"libLv":["Sēžas muskuļi; augšstilba aizmugure.","Muguras taisnotāji; korpuss; priekšējie deltveida un tvēriens tur svaru bumbu. Tā ir ballistiska noliekšanās no gurniem, nevis pietupiens.","Dzen gūžas, lai šūpotu svaru bumbu, nevis celtu to ar rokām."],"tech":[["Стопы чуть шире таза, гиря перед собой. Хват двумя руками. Спина нейтральна, колени мягкие.","Замах гири назад между ног за счёт отведения таза назад (шарнир), затем резкое разгибание бёдер. Гиря поднимается примерно до уровня груди или глаз. Руки не поднимают гирю силой дельт.","Вверху корпус прямой, ягодицы сжаты, гиря — продолжение рук. Снова шарнир: таз назад, гиря между ног."],["Присед вместо шарнира","округление поясницы","подъём гири руками","уход гири выше головы без отдельной задачи."],"Замах до растяжения задней цепи без округления; вверху — до груди/глаз для русского маха."],"techEn":[["Feet slightly wider than the hips, kettlebell in front of you. Grip it with both hands. Back neutral, knees soft.","Swing the bell back between the legs by pushing the hips back (a hinge), then snap the hips straight. The bell rises to about chest or eye height. The arms do not lift it with the delts.","At the top the torso is upright, the glutes are squeezed, and the bell is in line with the arms. Hinge again: hips back, bell between the legs."],["Squatting instead of hinging","rounding the lower back","lifting the bell with the arms","letting the bell go overhead when that is not a separate goal."],"Swing back to a posterior-chain stretch without rounding; at the top, to chest or eye height for the Russian swing."],"techLv":[["Pēdas nedaudz platāk par gurniem, svaru bumba priekšā. Satver ar abām rokām. Mugura neitrāla, ceļi mīksti.","Aizšūpo bumbu starp kājām, bīdot gūžas atpakaļ (noliekšanās), tad strauji iztaisno gūžas. Bumba paceļas aptuveni līdz krūtīm vai acīm. Rokas to neceļ ar deltveida spēku.","Augšā korpuss ir taisns, sēžas muskuļi saspiesti, un bumba ir roku līnijā. Atkal noliecies: gūžas atpakaļ, bumba starp kājām."],["Pietupiens noliekšanās vietā","jostasvietas apaļošana","bumbas celšana ar rokām","bumbas aiznešana virs galvas, ja tas nav atsevišķs mērķis."],"Šūpo atpakaļ līdz aizmugurējās ķēdes stiepumam bez apaļošanas; augšā — līdz krūtīm vai acīm krievu šūpolēm."]},{"id":"sled-push","name":"Толкание саней","group":"Ноги","meta":"g|","nameEn":"Sled push","nameLv":"Ragavu stumšana","lib":["Квадрицепс; ягодичные.","Икры; кор; плечевой пояс удерживает рукояти.","Толкание саней шагами. Только если сани есть в зале."],"libEn":["Quadriceps; glutes.","Calves; core; the shoulder girdle holds the handles.","Pushes a sled with hard steps for leg drive and conditioning."],"libLv":["Četrgalvainais; sēžas muskuļi.","Ikri; korpuss; plecu josla tur rokturus.","Stumj ragavas ar spēcīgiem soļiem kāju atspērienam un kondīcijai."],"tech":[["Руки на высоких рукоятях саней, корпус наклонён вперёд, одна нога уже в шаге. Спина нейтральна.","Мощные шаги вперёд с упором передней частью стопы, сани едут по полу без остановки.","Несколько непрерывных шагов с сохранением наклона и нейтральной спины."],["Округление поясницы","только толкание руками без ног","скольжение стоп без упора."],"Полный шаг с разгибанием бедра и колена рабочей ноги."],"techEn":[["Hands on the high handles, torso leaned forward, one foot already in a step. Back neutral.","Hard steps forward, driving through the front of the foot. The sled keeps moving along the floor.","Several steps in a row, keeping the lean and a neutral back."],["Rounding the lower back","pushing only with the arms, without the legs","feet slipping with no drive into the floor."],"A full step with the working hip and knee extending."],"techLv":[["Rokas uz augstajiem rokturiem, korpuss nolieks uz priekšu, viena pēda jau solī. Mugura neitrāla.","Spēcīgi soļi uz priekšu, atspiežoties ar pēdas priekšdaļu. Ragavas turpina braukt pa grīdu.","Vairāki soļi pēc kārtas, saglabājot noliekumu un neitrālu muguru."],["Jostasvietas apaļošana","stumšana tikai ar rokām, bez kājām","pēdu slīdēšana bez atspēriena grīdā."],"Pilns solis, darba kājas gūžai un celim iztaisnojoties."]},{"id":"deep-squat-hold","name":"Глубокий присед с удержанием","group":"Разминка","meta":"gdb|k","nameEn":"Deep squat hold","nameLv":"Dziļais pietupiens ar noturēšanu","lib":["Квадрицепс и ягодичные удерживают позицию изометрически; приводящие растягиваются внизу.","Камбаловидные и икроножные (тыльное сгибание голеностопа); кор держит грудной отдел.","Удержание глубокого приседа для подвижности."],"libEn":["Quadriceps and glutes hold the position isometrically; the adductors stretch at the bottom.","Soleus and gastrocnemius (ankle dorsiflexion); the core holds the ribcage.","Sits in a deep squat to open the hips and ankles."],"libLv":["Četrgalvainais un sēžas muskuļi notur pozīciju izometriski; pievilcēji apakšā stiepjas.","Plekstveida muskulis un ikru muskulis (potītes dorsālfleksija); korpuss tur krūškurvi.","Sēž dziļā pietupienā, lai atvērtu gūžas un potītes."],"tech":[["Стопы примерно на ширине плеч или чуть шире, носки слегка наружу. Медленно опуститься в глубокий присед.","Удерживать нижнюю точку: пятки стремятся к полу, грудь поднята, колени по носкам. Локти можно упереть изнутри в колени и слегка раскрывать бёдра, без рывка.","Спокойно выйди в стойку.","Статическое удержание в комфортном безболевом диапазоне. Дышать ровно."],["Сильное округление поясницы","завал коленей","пружинить внизу через боль","отрывать пятки и игнорировать это, уходя в ещё большую глубину."],"Глубина такая, чтобы пятки по возможности оставались на полу и позвоночник не скруглялся в болезненный сгиб. Если пятки отрываются — ограничение голеностопа, не форсировать."],"techEn":[["Feet about shoulder width or a little wider, toes slightly out. Lower slowly into a deep squat.","Hold the bottom: heels reach for the floor, chest up, knees track the toes. The elbows can press the knees from the inside and gently open the hips, without a jerk.","Stand up calmly.","A static hold in a comfortable, pain-free range. Breathe evenly."],["A strong round in the lower back","knees collapsing inward","bouncing at the bottom through pain","letting the heels lift and then going even deeper anyway."],"Only as deep as the heels can stay down, if possible, and the spine does not round into a painful bend. If the heels lift, that is an ankle limit — do not force more depth."],"techLv":[["Pēdas aptuveni plecu platumā vai nedaudz platāk, pirksti viegli uz āru. Lēni nolaižies dziļā pietupienā.","Noturi apakšējo punktu: papēži tiecas uz grīdu, krūtis augšā, ceļi virzienā uz pirkstiem. Elkoņi var spiest ceļus no iekšpuses un viegli atvērt gūžas, bez rāviena.","Mierīgi pieceļies.","Statiska noturēšana ērtā, nesāpīgā amplitūdā. Elpo vienmērīgi."],["Spēcīga jostasvietas apaļošana","ceļu iekrīšana uz iekšu","atsperšanās apakšā caur sāpēm","papēžu atraušana un iešana vēl dziļāk tik un tā."],"Tikai tik dziļi, lai papēži pēc iespējas paliktu uz grīdas un mugurkauls neapaļotos sāpīgā saliekumā. Ja papēži atraujas, tas ir potītes ierobežojums — neforsē lielāku dziļumu."]},{"id":"inchworm","name":"Гусеница","group":"Разминка","meta":"gdb|","nameEn":"Inchworm","nameLv":"Kāpurs","lib":["Задняя поверхность бедра (наклон и шаг стоп к кистям); мышцы кора в фазе планки.","Икры; плечи и передняя зубчатая (опора на руках).","Шаги руками в планку и обратно. Для разминки."],"libEn":["Hamstrings (in the hinge and as the feet step toward the hands); core muscles in the plank.","Calves; shoulders and serratus anterior (supporting you on the hands).","Walks the hands out to a plank and back in, to loosen the hamstrings and brace the trunk."],"libLv":["Augšstilba aizmugure (noliekšanās laikā un pēdām soļojot pret plaukstām); korpusa muskuļi plankā.","Ikri; pleci un priekšējais zāģzobis (balsts uz rokām).","Aizsoļo ar rokām līdz plankai un atpakaļ, lai atbrīvotu augšstilba aizmuguri un sasprindzinātu korpusu."],"tech":[["Стоя, стопы на ширине таза. Наклон от таза с мягкими коленями, ладони на полу перед стопами (колени согнуть столько, сколько нужно, чтобы не скруглять поясницу чрезмерно).","Перебирая руками, выйди в высокую планку — тело прямой линией. Затем мелкими шагами подведи стопы к кистям, таз поднимается.","Стопы близко к кистям в наклоне; можно выпрямиться в стойку или сразу снова пройти руками вперёд."],["Провисание поясницы в планке","жёстко запертые колени в наклоне","шаг руками так далеко, что поясница проваливается."],"В планке — прямая линия тела. В наклоне — столько сгибания в тазу и коленях, чтобы ладони встали на пол без боли в пояснице."],"techEn":[["Stand with the feet about hip width. Hinge from the hips with soft knees and put the palms on the floor in front of the feet (bend the knees as much as you need so the lower back does not round too much).","Walk the hands out to a high plank — body in a straight line. Then take small steps to bring the feet toward the hands as the hips rise.","Feet close to the hands in the hinge; stand up, or walk the hands forward again right away."],["The lower back sagging in the plank","knees locked hard during the hinge","walking the hands so far that the lower back collapses."],"In the plank, a straight line through the body. In the hinge, as much bend at the hips and knees as it takes to get the palms on the floor without lower-back pain."],"techLv":[["Stāvies ar pēdām aptuveni gurnu platumā. Noliecies no gurniem ar mīkstiem ceļiem un liec plaukstas uz grīdas pēdu priekšā (saliec ceļus tik, cik vajag, lai jostasvieta neapaļotos pārmērīgi).","Aizsoļo ar rokām līdz augstajai plankai — ķermenis taisnā līnijā. Tad ar maziem soļiem pievelc pēdas pie plaukstām, gurniem ceļoties.","Pēdas tuvu plaukstām noliekumā; pieceļies vai uzreiz atkal soļo ar rokām uz priekšu."],["Jostasvietas iekrīšana plankā","ceļi stingri aizslēgti noliekšanās laikā","soļošana ar rokām tik tālu, ka jostasvieta iekrīt."],"Plankā — taisna līnija cauri ķermenim. Noliekumā — tik daudz saliekuma gurnos un ceļos, lai plaukstas nokļūtu uz grīdas bez sāpēm jostasvietā."]},{"id":"assisted-pullup","name":"Подтягивания с помощью","group":"Спина","meta":"gb|","nameEn":"Assisted pull-ups","nameLv":"Pievilkšanās ar palīdzību","lib":["Широчайшие.","Бицепс; задние дельты; ромбовидные; нижние трапеции; кор.","Подтягивание с резинкой или гравитроном."],"libEn":["Lats.","Biceps; posterior deltoids; rhomboids; lower traps; core.","Practices the pull-up while a band or a machine takes off some body weight."],"libLv":["Platie muguras muskuļi.","Bicepss; aizmugurējie deltveida; rombveida; apakšējie trapecveida; korpuss.","Trenē pievilkšanos, kamēr gumija vai trenažieris noņem daļu ķermeņa svara."],"tech":[["Прямой хват чуть шире плеч, как в подтягиваниях. Резинка на перекладине, стопы или колени в петле; либо колени на платформе гравитрона. Плечи слегка опущены, без раскачки.","Та же траектория, что у подтягивания: локти вниз-назад, грудь к перекладине. Помощь разгружает вес тела, концентрику выполняет сам атлет.","Подбородок выше грифа. Контролируемое опускание до почти прямых рук.","Вариант: Резинка (стопы или колени в петле) или гравитрон (колени на платформе)."],["Киппинг","полностью отдавать движение резинке или тренажёру без тяги спиной","шраг","вытягивание головы вперёд."],"От почти полного виса до подбородка выше грифа. Сопротивление резинки или груз гравитрона подбирают так, чтобы амплитуда была полной."],"techEn":[["Overhand grip a little wider than the shoulders, as in pull-ups. A band on the bar with the feet or knees in the loop, or the knees on the gravitron platform. Shoulders slightly down, no swinging.","The same path as a pull-up: elbows down and back, chest toward the bar. The help unloads body weight; you still do the pull.","Chin above the bar. Lower under control to nearly straight arms.","Variation: A band (feet or knees in the loop) or a gravitron (knees on the platform)."],["Kipping","letting the band or the machine do the whole movement, with no pull from the back","shrugging","jutting the head forward."],"From a nearly full hang to the chin above the bar. Set the band or the gravitron load so the range stays full."],"techLv":[["Tvēriens no augšas nedaudz platāks par pleciem, kā pievilkšanās. Gumija uz stieņa, pēdas vai ceļi cilpā, vai ceļi uz gravitrona platformas. Pleci viegli nolaisti, bez šūpošanās.","Tā pati trajektorija kā pievilkšanās: elkoņi lejup un atpakaļ, krūtis pret stieni. Palīdzība atslogo ķermeņa svaru; vilkmi dari tu pats.","Zods virs stieņa. Nolaidies kontrolēti līdz gandrīz taisnām rokām.","Variants: Gumija (pēdas vai ceļi cilpā) vai gravitron (ceļi uz platformas)."],["Kipings","ļaut gumijai vai trenažierim izdarīt visu kustību, bez vilkmes no muguras","plecu raustīšana","galvas izbāšana uz priekšu."],"No gandrīz pilnas karāšanās līdz zodam virs stieņa. Gumiju vai gravitrona svaru izvēlies tā, lai amplitūda paliktu pilna."]},{"id":"dead-hang","name":"Вис на перекладине","group":"Спина","meta":"gb|p","nameEn":"Dead hang","nameLv":"Karāšanās pie stieņa","lib":["Сгибатели пальцев и предплечья (хват).","Широчайшие и нижние трапеции удерживают плечо в лёгкой упаковке; мышцы кора стабилизируют таз.","Вис на перекладине для хвата и плеч."],"libEn":["Finger flexors and the forearms (grip).","Lats and lower traps keep the shoulder settled slightly down; the core steadies the pelvis.","Hangs from the bar to build grip and a settled shoulder position."],"libLv":["Pirkstu saliecēji un apakšdelmi (tvēriens).","Platie muguras muskuļi un apakšējie trapecveida tur plecu viegli nolaistu; korpuss notur iegurni.","Karājas pie stieņa, lai veidotu tvērienu un mierīgu pleca stāvokli."],"tech":[["Хват сверху на ширине плеч, стопы оторваны от пола. Плечи не подняты к ушам: лёгкая упаковка вниз, без активного подтягивания.","Статическое удержание виса. Дышать ровно, рёбра не выпячивать, ноги спокойны.","Мягко встать на пол или опору, не спрыгивать на прямые ноги.","Статическое удержание — до потери качества хвата или положения плеч."],["Полностью „повисшие“ плечи с резкой растяжкой без подготовки","раскачка","сгибание рук (это уже подтягивание или подтягивание лопатками)."],"Прямые руки, без сгибания локтей. Упаковка плеча индивидуальна: без боли впереди плеча."],"techEn":[["Overhand grip at shoulder width, feet off the floor. Shoulders not up by the ears: settle them slightly down, without actively pulling up.","Hold the hang. Breathe evenly, do not flare the ribs, and keep the legs quiet.","Step down onto the floor or a support. Do not drop onto straight legs.","A static hold, until the grip or the shoulder position starts to fade."],["Shoulders left completely dumped, with a sharp stretch and no preparation","swinging","bending the arms (that is already a pull-up, or a scapular pull-up)."],"Straight arms, no bend at the elbows. How far to settle the shoulder down is individual: no pain at the front of the shoulder."],"techLv":[["Tvēriens no augšas plecu platumā, pēdas nost no grīdas. Pleci nav pie ausīm: viegla nolaišana uz leju, bez aktīvas vilkšanas augšup.","Noturi karāšanos. Elpo vienmērīgi, neizvirzi ribas, un turi kājas mierā.","Nostājies uz grīdas vai atbalsta. Nelec uz taisnām kājām.","Statiska noturēšana, līdz tvēriens vai plecu stāvoklis sāk zust."],["Pleci atstāti pilnīgi nokārušies, ar asu stiepumu un bez sagatavošanās","šūpošanās","roku saliekšana (tā jau ir pievilkšanās vai pievilkšanās ar lāpstiņām)."],"Taisnas rokas, bez saliekuma elkoņos. Cik tālu nolaist plecu, ir individuāli: bez sāpēm pleca priekšpusē."]},{"id":"stretch-hip-flexor","name":"Растяжка сгибателей бедра","group":"Заминка","meta":"gdb|","nameEn":"Hip flexor stretch","nameLv":"Gūžas saliecēju stiepšana","lib":["Подвздошно-поясничная и прямая мышца бедра задней ноги (растягиваются).","Гребенковая; прямая мышца живота удерживает задний наклон таза.","Спокойная растяжка сгибателей бедра в полуколене."],"libEn":["Iliopsoas and rectus femoris of the back leg (they are being stretched).","Pectineus; rectus abdominis holds the posterior pelvic tilt.","Lengthens the front of the hip after sitting or after leg work."],"libLv":["Aizmugurējās kājas jostas-gūžas muskulis un taisnais augšstilba muskulis (tie tiek stiepti).","Ķemmveida muskulis; taisnais vēdera muskulis notur iegurņa aizmugurējo sagāzumu.","Pagarina gūžas priekšpusi pēc sēdēšanas vai kāju darba."],"tech":[["Полуколено: одно колено на полу (можно подложить коврик), другая стопа впереди, голень примерно вертикальна.","Задний наклон таза (подкрутить копчик под себя), затем лёгкий сдвиг таза вперёд, не прогибаясь в пояснице. Руки на переднем бедре или вдоль корпуса.","Удержание растяжения сгибателя задней ноги без боли.","Статическое удержание, ровное дыхание.","Вариант: Более интенсивный вариант — задняя голень вертикально у стены."],["Сильный прогиб поясницы","выпячивание рёбер","завал переднего колена внутрь","рывок в растяжку."],"До ощущения растяжения спереди бедра или паха задней ноги, без боли в пояснице."],"techEn":[["Half kneeling: one knee on the floor (a mat underneath is fine), the other foot in front, that shin about vertical.","Tilt the pelvis back (tuck the tailbone under you), then shift the hips slightly forward without arching the lower back. Hands on the front thigh or alongside the body.","Hold the stretch in the hip flexor of the back leg, without pain.","A static hold, breathing evenly.","Variation: A stronger option is the back shin vertical against a wall."],["A strong arch in the lower back","ribs flaring","the front knee collapsing inward","jerking into the stretch."],"To a stretch at the front of the thigh or the groin of the back leg, without lower-back pain."],"techLv":[["Pusceļos: viens celis uz grīdas (apakšā var būt paklājiņš), otra pēda priekšā, tās apakšstilbs aptuveni vertikāls.","Sagāz iegurni atpakaļ (paslēp astes kaulu zem sevis), tad viegli pārbīdi gūžas uz priekšu, neieliecot jostasvietu. Rokas uz priekšējā augšstilba vai gar ķermeni.","Noturi stiepumu aizmugurējās kājas gūžas saliecējā, bez sāpēm.","Statiska noturēšana, elpojot vienmērīgi.","Variants: Stiprāks variants — aizmugurējais apakšstilbs vertikāli pie sienas."],["Spēcīgs ieliekums jostasvietā","ribu izvirzīšana","priekšējā ceļa iekrīšana uz iekšu","rāviens stiepienā."],"Līdz stiepumam aizmugurējās kājas augšstilba priekšpusē vai cirksnī, bez sāpēm jostasvietā."]},{"id":"stretch-chest-doorway","name":"Растяжка груди у дверного проёма","group":"Заминка","meta":"gdb|p","nameEn":"Chest stretch in a doorway","nameLv":"Krūšu stiepšana durvju ailē","lib":["Большая грудная (растягивается).","Передняя дельта; малая грудная.","Растяжка груди у дверного проёма."],"libEn":["Pectoralis major (it is being stretched).","Anterior deltoid; pectoralis minor.","Opens the chest after pressing."],"libLv":["Lielais krūšu muskulis (tas tiek stiepts).","Priekšējais deltveida; mazais krūšu muskulis.","Atver krūtis pēc spiešanas."],"tech":[["Стоя в дверном проёме или у стойки, предплечье на косяке, локоть примерно на высоте плеча или чуть ниже, корпус анфас.","Лёгкий шаг вперёд, грудь раскрывается. Лопатка остаётся слегка сведённой — не проваливать плечо вперёд.","Удержание растяжения груди без боли впереди плеча.","Статическое удержание, ровное дыхание."],["Провал плеча вперёд","рывок корпусом","боль в передней капсуле плеча."],"До ощущения растяжения груди, без боли в плече."],"techEn":[["Stand in a doorway or at a rack, forearm on the frame, elbow about shoulder height or slightly below, torso square to the front.","Take a small step forward so the chest opens. The shoulder blade stays slightly pulled in — do not let the shoulder roll forward.","Hold the chest stretch without pain at the front of the shoulder.","A static hold, breathing evenly."],["The shoulder rolling forward","jerking with the torso","pain in the front of the shoulder capsule."],"To a stretch in the chest, without pain in the shoulder."],"techLv":[["Stāvies durvju ailē vai pie statīva, apakšdelms uz aplodas, elkonis aptuveni pleca augstumā vai nedaudz zemāk, korpuss vērsts uz priekšu.","Sper mazu soli uz priekšu, lai krūtis atvērtos. Lāpstiņa paliek viegli savilkta — neļauj plecam iekrist uz priekšu.","Noturi krūšu stiepumu bez sāpēm pleca priekšpusē.","Statiska noturēšana, elpojot vienmērīgi."],["Pleca ievelšanās uz priekšu","rāviens ar korpusu","sāpes pleca priekšējā kapsulā."],"Līdz stiepumam krūtīs, bez sāpēm plecā."]},{"id":"stretch-hamstring","name":"Растяжка задней поверхности бедра","group":"Заминка","meta":"gdb|","nameEn":"Hamstring stretch","nameLv":"Augšstilba aizmugures stiepšana","lib":["Двуглавая бедра, полусухожильная и полуперепончатая (растягиваются).","Икроножная, если стопа на себя; разгибатели поясницы не должны тянуться вместо бедра.","Растяжка задней поверхности бедра лёжа."],"libEn":["Biceps femoris, semitendinosus, and semimembranosus (they are being stretched).","Gastrocnemius, if the foot is drawn toward you; the lumbar extensors should not be the ones that stretch instead of the thigh.","Lengthens the back of the thigh while the pelvis stays on the floor."],"libLv":["Augšstilba divgalvainais, puscīpslainais un pusplēvainais muskulis (tie tiek stiepti).","Ikru muskulis, ja pēda ir pievilkta pret sevi; jostas atliecējiem nevajadzētu stiepties augšstilba vietā.","Pagarina augšstilba aizmuguri, kamēr iegurnis paliek uz grīdas."],"tech":[["Лёжа на спине, одна нога согнута стопой на полу. Другую поднять, обхватить руками за бедро или за ремень на стопе.","Выпрямлять поднятую ногу, пока не появится растяжение по задней поверхности бедра. Таз прижат к полу.","Удержание без боли, затем смена ноги.","Статическое удержание, ровное дыхание."],["Округление поясницы и отрыв таза","тянуть через боль в колене","рывок."],"До растяжения задней поверхности бедра при прижатом тазе, без боли в колене или пояснице."],"techEn":[["Lie on your back, one leg bent with the foot on the floor. Raise the other leg and hold the thigh with the hands, or use a strap around the foot.","Straighten the raised leg until you feel a stretch along the back of the thigh. Keep the pelvis on the floor.","Hold without pain, then switch legs.","A static hold, breathing evenly."],["Rounding the lower back and lifting the pelvis","pulling through pain in the knee","jerking."],"To a stretch along the back of the thigh with the pelvis down, without pain in the knee or the lower back."],"techLv":[["Guli uz muguras, viena kāja saliekta ar pēdu uz grīdas. Pacel otru kāju un turi augšstilbu ar rokām vai lieto jostu ap pēdu.","Taisno pacelto kāju, līdz jūti stiepumu gar augšstilba aizmuguri. Turi iegurni uz grīdas.","Noturi bez sāpēm, tad maini kājas.","Statiska noturēšana, elpojot vienmērīgi."],["Jostasvietas apaļošana un iegurņa pacelšana","vilkšana caur sāpēm celī","rāviens."],"Līdz stiepumam gar augšstilba aizmuguri ar iegurni lejā, bez sāpēm celī vai jostasvietā."]},{"id":"stretch-glute-figure4","name":"Растяжка ягодичной («четвёрка»)","group":"Заминка","meta":"gdb|","nameEn":"Glute stretch (\"figure four\")","nameLv":"Sēžas muskuļa stiepšana („četri”)","lib":["Большая и средняя ягодичные, грушевидная сгибаемой (верхней) ноги (растягиваются).","Глубокие наружные вращатели бедра (близнецовые, запирательные, квадратная мышца бедра).","Растяжка ягодичной в положении «четвёрка»."],"libEn":["Gluteus maximus, gluteus medius, and piriformis of the bent (top) leg (they are being stretched).","Deep external rotators of the hip (gemelli, obturators, quadratus femoris).","Stretches the glute of the crossed leg while the pelvis stays level on the floor."],"libLv":["Saliektās (augšējās) kājas lielais sēžas muskulis, vidējais sēžas muskulis un bumbieru muskulis (tie tiek stiepti).","Dziļie gūžas ārējie rotatori (dvīņu muskuļi, slēdzējmuskuļi, augšstilba kvadrātmuskulis).","Stiepj sakrustotās kājas sēžas muskuli, kamēr iegurnis paliek līmenī uz grīdas."],"tech":[["Лёжа на спине. Голень одной ноги кладут на бедро другой крест-накрест («четвёрка»).","Подтянуть опорную ногу к груди руками за бедро. Таз остаётся на полу, крестец не скручивать вбок.","Удержание растяжения ягодичной верхней ноги, затем смена сторон.","Статическое удержание, ровное дыхание."],["Тянуть за голень так, что колено верхней ноги уходит к плечу через боль","скручивать таз вбок","рывок."],"До растяжения ягодичной и боковой поверхности таза, без боли в колене или пояснице."],"techEn":[["Lie on your back. Rest one shin across the other thigh, crossed like a figure four.","Draw the supporting leg toward the chest, hands behind that thigh. The pelvis stays on the floor; do not twist the sacrum to the side.","Hold the stretch in the glute of the top leg, then switch sides.","A static hold, breathing evenly."],["Pulling the shin so the top knee is forced toward the shoulder through pain","twisting the pelvis to the side","jerking."],"To a stretch in the glute and the side of the hip, without pain in the knee or the lower back."],"techLv":[["Guli uz muguras. Liec vienas kājas apakšstilbu šķērsām uz otra augšstilba, sakrustotu kā četrus.","Pievelc atbalsta kāju pie krūtīm, rokas aiz šī augšstilba. Iegurnis paliek uz grīdas; negriez krustu kaulu uz sāniem.","Noturi stiepumu augšējās kājas sēžas muskulī, tad maini puses.","Statiska noturēšana, elpojot vienmērīgi."],["Apakšstilba vilkšana tā, ka augšējais celis tiek spiests pret plecu caur sāpēm","iegurņa griešana uz sāniem","rāviens."],"Līdz stiepumam sēžas muskulī un gūžas sānos, bez sāpēm celī vai jostasvietā."]},{"id":"stretch-calf","name":"Растяжка икр","group":"Заминка","meta":"gdb|","nameEn":"Calf stretch","nameLv":"Ikru stiepšana","lib":["Икроножная при прямой задней ноге; камбаловидная при согнутом колене.","Задняя большеберцовая и длинные сгибатели пальцев (слабо).","Растяжка икры при прямой и при согнутой ноге."],"libEn":["Gastrocnemius with the back knee straight; soleus with that knee bent.","Tibialis posterior and the long toe flexors (lightly).","Lengthens the calf first with a straight knee, then with a bent knee."],"libLv":["Ikru muskulis ar taisnu aizmugurējo celi; plekstveida muskulis ar šo celi saliektu.","Mugurējais lielā lielakaula muskulis un garie pirkstu saliecēji (vāji).","Pagarina ikru vispirms ar taisnu celi, tad ar saliektu celi."],"tech":[["Стоя лицом к стене, руки на стене. Задняя нога сзади, пятка стремится к полу.","Сначала прямое колено задней ноги (икроножная). Затем слегка согнуть то же колено, не отрывая пятку (камбаловидная).","Удержание каждой фазы без боли в ахилловом сухожилии.","Статическое удержание в каждой фазе."],["Отрыв пятки","рывок","заваливание стопы внутрь","растяжка через боль в ахилловом сухожилии."],"Пятка задней ноги стремится к полу; глубина — до растяжения икры без боли."],"techEn":[["Stand facing a wall, hands on the wall. The back leg is behind you, heel reaching for the floor.","First keep the back knee straight (gastrocnemius). Then bend that same knee slightly without lifting the heel (soleus).","Hold each phase without pain in the Achilles tendon.","A static hold in each phase."],["The heel lifting","jerking","the foot collapsing inward","stretching through pain in the Achilles tendon."],"The back heel reaches for the floor; go only as far as a calf stretch without pain."],"techLv":[["Stāvies ar seju pret sienu, rokas uz sienas. Aizmugurējā kāja ir aiz tevis, papēdis tiecas uz grīdu.","Vispirms turi aizmugurējo celi taisnu (ikru muskulis). Tad viegli saliec to pašu celi, neatraujot papēdi (plekstveida muskulis).","Noturi katru fāzi bez sāpēm Ahileja cīpslā.","Statiska noturēšana katrā fāzē."],["Papēža atraušanās","rāviens","pēdas iekrīšana uz iekšu","stiepšana caur sāpēm Ahileja cīpslā."],"Aizmugurējais papēdis tiecas uz grīdu; ej tikai tik tālu, cik ikra stiepums bez sāpēm."]},{"id":"neck-retraction","name":"Ретракция шеи","group":"Плечи","meta":"gdb|","nameEn":"Neck retraction","nameLv":"Kakla retrakcija","lib":["Глубокие сгибатели шеи (длинная мышца шеи и головы).","Поверхностные разгибатели шеи и верхняя трапеция не должны перехватывать движение.","Короткое движение головы назад, без кивка вниз."],"libEn":["Deep neck flexors (longus colli and longus capitis).","The superficial neck extensors and the upper trapezius should not take the movement over.","Slides the head straight back to train a more neutral neck."],"libLv":["Dziļie kakla saliecēji (garais kakla muskulis un garais galvas muskulis).","Virspusējiem kakla atliecējiem un trapecveida augšdaļai nevajadzētu pārņemt kustību.","Bīda galvu taisni atpakaļ, lai trenētu neitrālāku kaklu."],"tech":[["Сидя или стоя, взгляд горизонтально, плечи опущены. Позвоночник нейтрален.","Голова скользит назад параллельно полу (как «двойной подбородок»), не опуская и не задирая подбородок.","Короткое удержание, возврат в нейтраль — не в вытянутую вперёд голову."],["Кивок вниз (это сгибание шеи — отдельное упражнение)","задирание подбородка","напряжение плеч."],"Малая амплитуда в безболевом диапазоне, взгляд остаётся горизонтальным."],"techEn":[["Sit or stand, gaze level, shoulders down. Spine neutral.","Slide the head straight back, parallel to the floor (a \"double chin\"), without dropping the chin or lifting it.","A short hold, then return to neutral — not to a head jutting forward."],["Nodding down (that is neck flexion, a separate exercise)","lifting the chin","tensing the shoulders."],"A small range that stays pain-free; the gaze stays level."],"techLv":[["Sēdi vai stāvi, skatiens līmenī, pleci nolaisti. Mugurkauls neitrāls.","Bīdi galvu taisni atpakaļ, paralēli grīdai („dubultzods”), nenolaižot zodu un nepaceļot to.","Īsa noturēšana, tad atgriezies neitrālā stāvoklī — nevis galvā, kas izbāzta uz priekšu."],["Mājiens uz leju (tā ir kakla saliekšana, atsevišķs vingrinājums)","zoda pacelšana","plecu sasprindzināšana."],"Neliela amplitūda, kas paliek nesāpīga; skatiens paliek līmenī."]},{"id":"copenhagen-plank","name":"Планка Копенгаген","group":"Ноги","meta":"gdb|","nameEn":"Copenhagen plank","nameLv":"Kopenhāgenas planka","lib":["Приводящие верхней (опорной на скамье) ноги.","Косые и квадратная мышца поясницы (как в боковой планке); средняя ягодичная; кор.","Боковая планка с опорой верхней ногой. Высокая нагрузка на приводящие."],"libEn":["Adductors of the top leg (the one supported on the bench).","Obliques and quadratus lumborum (as in a side plank); gluteus medius; core.","Holds a side plank from the top leg so the adductors have to work."],"libLv":["Augšējās kājas pievilcēji (tās, kas balstās uz sola).","Slīpie un jostas kvadrātmuskulis (kā sānu plankā); vidējais sēžas muskulis; korpuss.","Notur sānu planku no augšējās kājas, lai pievilcējiem jāstrādā."],"tech":[["Боком к скамье. Верхняя нога голенью на скамье, нижняя на весу. Предплечье на полу, тело прямой линией.","Удержание боковой планки: таз не провисает и не заваливается вперёд-назад. Можно короткие опускания-подъёмы таза.","Контролируемый выход: нижняя нога на пол, затем верхняя.","Статическое удержание.","Вариант: Регрессия: опора на скамью коленом верхней ноги (короткий рычаг) или нижняя нога на полу."],["Провисание таза","поворот груди к полу","опора верхней ногой слишком близко к колену, если это вызывает боль в колене."],"Тело — прямая линия от головы до верхней стопы. Без боли в лонном сочленении и колене."],"techEn":[["Side-on to a bench. The top leg's shin is on the bench, the bottom leg hangs. Forearm on the floor, body in a straight line.","Hold the side plank: the pelvis does not sag and does not tip forward or back. Short lowers and lifts of the pelvis are fine.","Step out under control: bottom foot to the floor, then the top leg.","Static hold.","Variation: An easier version: the top knee on the bench (a shorter lever), or the bottom foot on the floor."],["The pelvis sagging","the chest turning toward the floor","the top leg supported so close to the knee that the knee hurts."],"A straight line from the head to the top foot. No pain at the pubic symphysis or the knee."],"techLv":[["Sāniski pret solu. Augšējās kājas apakšstilbs ir uz sola, apakšējā kāja karājas. Apakšdelms uz grīdas, ķermenis taisnā līnijā.","Noturi sānu planku: iegurnis neiekrīt un neapgāžas uz priekšu vai atpakaļ. Īsa iegurņa nolaišana un pacelšana ir pieņemama.","Izej kontrolēti: apakšējā pēda uz grīdas, tad augšējā kāja.","Statiska noturēšana.","Variants: Vieglāks variants: augšējais celis uz sola (īsāka svira) vai apakšējā pēda uz grīdas."],["Iegurņa iekrīšana","krūšu pagriešanās pret grīdu","augšējā kāja atbalstīta tik tuvu celim, ka celis sāp."],"Taisna līnija no galvas līdz augšējai pēdai. Bez sāpēm kaunuma simfīzē vai celī."]},{"id":"wall-slide","name":"Скольжение руками по стене","group":"Плечи","meta":"gdb|","nameEn":"Arm slides on the wall","nameLv":"Roku slīdēšana pa sienu","lib":["Передняя зубчатая; нижние трапеции.","Средние трапеции и ромбовидные удерживают сведение; надостная в отведении.","Скольжение рук по стене для лопаток."],"libEn":["Serratus anterior; lower trapezius.","Mid trapezius and rhomboids hold the shoulder blades in; supraspinatus works as the arms lift out.","Slides the arms up a wall while the ribs and the lower back stay quiet."],"libLv":["Priekšējais zāģzobis; apakšējie trapecveida.","Vidējie trapecveida un rombveida tur lāpstiņas savilktas; virsšķautnes muskulis strādā, rokām ceļoties sānis.","Slidina rokas augšup pa sienu, kamēr ribas un jostasvieta paliek mierā."],"tech":[["Стоя спиной к стене, стопы чуть впереди. Поясница, верх спины и затылок стремятся к стене без сильного прогиба. Руки буквой W: локти и тыл кистей на стене.","Скользить руками вверх в букву Y, не отрывая локти и кисти от стены. Рёбра не выпячиваются.","Насколько позволяет контроль, затем скольжение обратно в W."],["Отрыв кистей или локтей","выпячивание рёбер","шраг к ушам","прогиб поясницы."],"От позиции W до той высоты, где контакт со стеной и нейтральные рёбра ещё сохраняются."],"techEn":[["Stand with your back to the wall, feet a little forward. The lower back, upper back, and the back of the head reach for the wall without a strong arch. Arms in a W: elbows and the backs of the hands on the wall.","Slide the arms up into a Y without taking the elbows or the hands off the wall. The ribs do not flare.","Only as high as you can still control, then slide back to the W."],["Hands or elbows coming off the wall","ribs flaring","shrugging toward the ears","arching the lower back."],"From the W up to the height where you still touch the wall and the ribs stay neutral."],"techLv":[["Stāvies ar muguru pret sienu, pēdas nedaudz priekšā. Jostasvieta, muguras augšdaļa un pakausis tiecas pret sienu bez spēcīga ieliekuma. Rokas W formā: elkoņi un plaukstu muguras uz sienas.","Slidini rokas augšup Y formā, neatraujot elkoņus vai plaukstas no sienas. Ribas neizvirzās.","Tikai tik augstu, cik vēl vari kontrolēt, tad slidinies atpakaļ uz W."],["Plaukstu vai elkoņu atraušanās no sienas","ribu izvirzīšana","plecu raustīšana pret ausīm","jostasvietas ieliekums."],"No W līdz tam augstumam, kur vēl ir kontakts ar sienu un ribas paliek neitrālas."]},{"id":"jump-rope","name":"Прыжки со скакалкой","group":"Кардио","meta":"gd|k","nameEn":"Jump rope","nameLv":"Lēcieni ar lecamauklu","lib":["Икроножные и камбаловидные.","Передняя большеберцовая между прыжками; квадрицепс; плечи и предплечья вращают скакалку; кор.","Скакалка: икры и пульс, без высокого прыжка."],"libEn":["Gastrocnemius and soleus.","Tibialis anterior between jumps; quadriceps; the shoulders and forearms turn the rope; core.","Turns a rope for easy, rhythmic conditioning."],"libLv":["Ikru muskulis un plekstveida muskulis.","Priekšējais lielā lielakaula muskulis starp lēcieniem; četrgalvainais; pleci un apakšdelmi griež lecamauklu; korpuss.","Griež lecamauklu vieglai, ritmiskai kondīcijai."],"tech":[["Скакалка сзади, локти у корпуса, кисти чуть впереди бёдер. Мягкие колени.","Вращение преимущественно кистями. Невысокие прыжки двумя ногами, приземление на переднюю часть стопы с мягким коленом.","Непрерывные невысокие прыжки без паузы на прямых ногах."],["Жёсткое приземление на прямые ноги","вращение всей рукой от плеча","слишком высокие прыжки."],"Небольшой отрыв стоп, достаточный, чтобы скакалка прошла под ногами."],"techEn":[["Rope behind you, elbows by the torso, hands slightly in front of the hips. Soft knees.","Turn the rope mostly with the wrists. Low jumps on both feet, landing on the front of the foot with a soft knee.","Keep the jumps low and continuous, with no pause on straight legs."],["Landing hard on straight legs","turning from the whole arm at the shoulder","jumps that are too high."],"A small lift of the feet, just enough for the rope to pass underneath."],"techLv":[["Lecamaukla aiz tevis, elkoņi pie korpusa, plaukstas nedaudz gurnu priekšā. Mīksti ceļi.","Griez lecamauklu galvenokārt ar plaukstām. Zemi lēcieni uz abām pēdām, piezemējoties uz pēdas priekšdaļas ar mīkstu celi.","Turi lēcienus zemus un nepārtrauktus, bez pauzes uz taisnām kājām."],["Cieta piezemēšanās uz taisnām kājām","griešana ar visu roku no pleca","pārāk augsti lēcieni."],"Neliela pēdu atraušanās, tieši tik, lai lecamaukla paietu apakšā."]},{"id":"jump-squat","name":"Выпрыгивания из приседа","group":"Ноги","meta":"gdb|k","nameEn":"Squat jumps","nameLv":"Izlēcieni no pietupiena","lib":["Квадрицепс; ягодичные.","Задняя поверхность; икры; кор.","Выпрыгивание из приседа. Только при уверенном мягком приземлении."],"libEn":["Quadriceps; glutes.","Hamstrings; calves; core.","Jumps out of a squat and lands softly."],"libLv":["Četrgalvainais; sēžas muskuļi.","Augšstilba aizmugure; ikri; korpuss.","Izlec no pietupiena un piezemējas mīksti."],"tech":[["Стопы на ширине плеч, как в приседаниях с весом тела. Руки можно замахнуть.","Присед до примерно параллели, затем взрывное разгибание и отрыв стоп от пола. В полёте тело вытянуто.","Мягкое приземление в четверть-присед, колени по носкам."],["Жёсткое приземление на прямые ноги","завал коленей","слишком глубокий неконтролируемый присед на приземлении."],"Присед примерно до параллели перед прыжком; приземление в четверть-присед, не на прямые колени."],"techEn":[["Feet at shoulder width, as in a bodyweight squat. The arms can swing.","Squat to about parallel, then extend explosively and leave the floor. The body is long in the air.","Land softly in a quarter squat, knees tracking the toes."],["Landing hard on straight legs","knees collapsing inward","a squat on the landing that is too deep and out of control."],"Squat to about parallel before the jump; land in a quarter squat, not on straight knees."],"techLv":[["Pēdas plecu platumā, kā pietupienā ar ķermeņa svaru. Rokas var aizvēzēt.","Pietupies aptuveni līdz paralēlei, tad iztaisnojies sprādzienveidā un atrauj pēdas no grīdas. Gaisā ķermenis ir izstiepts.","Piezemējies mīksti ceturtdaļpietupienā, ceļi virzienā uz pirkstiem."],["Cieta piezemēšanās uz taisnām kājām","ceļu iekrīšana uz iekšu","pietupiens piezemējoties, kas ir pārāk dziļš un bez kontroles."],"Pietupies aptuveni līdz paralēlei pirms lēciena; piezemējies ceturtdaļpietupienā, nevis uz taisniem ceļiem."]},{"id":"woodchop","name":"Рубка дров на блоке","group":"Пресс","meta":"g|","nameEn":"Cable woodchop","nameLv":"Malkas skaldīšana blokā","lib":["Косые мышцы живота стороны вращения.","Прямая мышца живота; поперечная; ягодичные и ноги передают силу с пола; плечи держат руки.","Поворот корпуса по диагонали на блоке."],"libEn":["Obliques on the side that is rotating.","Rectus abdominis; transverse abdominis; the glutes and legs pass force up from the floor; the shoulders hold the arms.","Turns the trunk on a diagonal against a cable."],"libLv":["Slīpie vēdera muskuļi tajā pusē, kas griežas.","Taisnais vēdera muskulis; šķērseniskais vēdera muskulis; sēžas muskuļi un kājas nodod spēku no grīdas; pleci tur rokas.","Griež korpusu pa diagonāli pret trosi."],"tech":[["Боком к верхнему блоку, рукоятка двумя руками у дальнего от блока плеча, выше головы. Стопы чуть шире плеч, колени мягкие.","Поворот корпуса и опускание рукоятки по диагонали к противоположному бедру. Бёдра и грудь поворачиваются вместе, руки почти прямые. Это вращение корпуса, не тяга руками.","Рукоятка у противоположного бедра, затем контроль обратно вверх по той же диагонали.","Вариант: Снизу вверх (обратная рубка) — отдельный вариант."],["Только руки без поворота корпуса","сильный провал поясницы","рывок коленями внутрь","отпускать рукоятку."],"От положения рук над дальним плечом до рукоятки у противоположного бедра, без потери нейтрали поясницы."],"techEn":[["Stand side-on to the high cable, handle in both hands by the shoulder farther from the stack, above the head. Feet a little wider than the shoulders, knees soft.","Turn the torso and bring the handle down on a diagonal to the opposite hip. Hips and chest turn together, arms nearly straight. This is a turn of the trunk, not a pull with the arms.","Handle at the opposite hip, then bring it back up the same diagonal under control.","Variation: Low to high (a reverse chop) is a separate option."],["Arms only, with no turn of the torso","the lower back collapsing hard","the knees snapping inward","letting go of the handle."],"From the hands above the far shoulder to the handle at the opposite hip, without losing a neutral lower back."],"techLv":[["Stāvies sāniski pret augšējo bloku, rokturis abās rokās pie pleca, kas tālāk no bloka, virs galvas. Pēdas nedaudz platāk par pleciem, ceļi mīksti.","Pagriez korpusu un ved rokturi lejup pa diagonāli līdz pretējam gurnam. Gūžas un krūtis griežas kopā, rokas gandrīz taisnas. Tā ir korpusa griešana, nevis vilkme ar rokām.","Rokturis pie pretējā gurna, tad ved to atpakaļ augšup pa to pašu diagonāli kontrolēti.","Variants: No apakšas uz augšu (apgrieztā skaldīšana) ir atsevišķa iespēja."],["Tikai rokas, bez korpusa griešanas","jostasvieta stipri iekrīt","ceļi raujas uz iekšu","roktura atlaišana."],"No rokām virs tālākā pleca līdz rokturim pie pretējā gurna, nezaudējot neitrālu jostasvietu."]},{"id":"landmine-press","name":"Жим штанги одной рукой в угловом упоре (лэндмайн)","group":"Плечи","meta":"g|p","nameEn":"One-arm barbell press in a corner support (landmine)","nameLv":"Stieņa spiešana ar vienu roku stūra atbalstā (lendmaine)","lib":["Передние дельты; ключичная порция большой грудной.","Передняя зубчатая; трицепс; кор (особенно в стоячем одноручном).","Жим одной рукой по дуге, конец грифа в углу."],"libEn":["Anterior deltoids; clavicular portion of pectoralis major.","Serratus anterior; triceps; core (especially in the standing one-arm version).","Presses one arm up along an arc while the trunk stays braced."],"libLv":["Priekšējie deltveida; lielā krūšu muskuļa atslēgas kaula daļa.","Priekšējais zāģzobis; tricepss; korpuss (īpaši stāvus variantā ar vienu roku).","Spiež vienu roku augšup pa loku, kamēr korpuss paliek sasprindzināts."],"tech":[["Один конец грифа в угловом упоре или в углу стены. Стоя, гриф у плеча одной руки, стойка слегка в разножке, кор напряжён.","Жим грифа вверх и чуть вперёд по дуге, пока рука почти прямая. Лопатка движется вверх-вперёд (зубчатая), без избыточного прогиба.","Почти полное разгибание, медленное опускание к плечу.","Вариант: Жим из полуколена (более стабильный) и жим двумя руками."],["Сильный прогиб поясницы","шраг","вращение корпуса вместо жима","удар грифом в верхней точке."],"От грифа у плеча до почти прямой руки."],"techEn":[["One end of the bar in a corner support or in the corner of a wall. Stand with the bar at one shoulder, a slight split stance, core braced.","Press the bar up and slightly forward along an arc until the arm is nearly straight. The shoulder blade moves up and forward (serratus), without an excessive arch.","Nearly full extension, then lower slowly to the shoulder.","Variation: A half-kneeling press (more stable) and a two-arm press."],["A strong arch in the lower back","shrugging","turning the torso instead of pressing","banging the bar at the top."],"From the bar at the shoulder to a nearly straight arm."],"techLv":[["Viens stieņa gals stūra atbalstā vai sienas stūrī. Stāvies ar stieni pie viena pleca, viena pēda nedaudz priekšā, korpuss sasprindzināts.","Spied stieni augšup un nedaudz uz priekšu pa loku, līdz roka ir gandrīz taisna. Lāpstiņa virzās augšup un uz priekšu (zāģzobis), bez pārmērīga ieliekuma.","Gandrīz pilna iztaisnošana, tad nolaid lēni pie pleca.","Variants: Spiešana no pusceļgala (stabilāka) un spiešana ar abām rokām."],["Spēcīgs ieliekums jostasvietā","plecu raustīšana","korpusa griešana spiešanas vietā","sitiens ar stieni augšā."],"No stieņa pie pleca līdz gandrīz taisnai rokai."]},{"id":"turkish-getup","name":"Турецкий подъём","group":"Пресс","meta":"gd|sp","nameEn":"Turkish get-up","nameLv":"Turku piecēšanās","lib":["Кор (прямая, косые, поперечная) как стабилизатор на всём пути.","Плечо рабочей руки (дельты, вращательная манжета, зубчатая) удерживает гирю; ягодичные и квадрицепс разгибают ноги.","Подъём с пола с гирей над головой. Сложная координация."],"libEn":["The core (rectus abdominis, obliques, transverse abdominis) stabilizes you the whole way.","The shoulder of the working arm (deltoids, rotator cuff, serratus) holds the kettlebell; glutes and quadriceps extend the legs.","Stands up from the floor while one arm keeps a weight overhead."],"libLv":["Korpuss (taisnais vēdera muskulis, slīpie, šķērseniskais vēdera muskulis) stabilizē visu ceļu.","Darba rokas plecs (deltveida, rotatora manšete, zāģzobis) tur svaru bumbu; sēžas muskuļi un četrgalvainais iztaisno kājas.","Pieceļas no grīdas, kamēr viena roka tur svaru virs galvas."],"tech":[["Лёжа на спине, гиря в выпрямленной руке над плечом, взгляд на гирю. Одноимённая нога согнута, стопа на полу; противоположные рука и нога лежат под углом.","Каноническая последовательность: опора на свободный локоть, затем на ладонь; мост; убрать прямую ногу под себя в полуколено; встать. Рабочая рука всё время вертикальна.","Устойчивое положение в полуколене, гиря вертикально над плечом; затем подъём в стойку и спуск в обратном порядке.","Медленно, по шагам: полный цикл подъёма и спуска обычно 12–20 с."],["Сгибать руку с гирей","терять взгляд с гири на первых шагах","провал плеча","рывок в стойку."],"Каждый шаг до устойчивой опоры, гиря остаётся над плечом по вертикали."],"techEn":[["Lie on your back, kettlebell in a straight arm over the shoulder, eyes on the bell. The leg on that same side is bent, foot on the floor; the opposite arm and leg lie out at an angle.","The standard order: post on the free elbow, then on the palm; bridge the hips; sweep the straight leg underneath into half kneeling; stand up. The working arm stays vertical the whole time.","A steady half-kneeling position, bell vertical over the shoulder; then stand, and come back down in reverse.","Go slowly, one step at a time: a full trip up and down is usually 12–20 s."],["Bending the arm that holds the bell","taking the eyes off the bell in the first steps","the shoulder collapsing","rushing up to standing."],"Each step only as far as the support is steady, with the bell staying vertical over the shoulder."],"techLv":[["Guli uz muguras, svaru bumba taisnā rokā virs pleca, skatiens uz bumbu. Tās pašas puses kāja ir saliekta, pēda uz grīdas; pretējā roka un kāja guļ sānis leņķī.","Parastā secība: atbalsts uz brīvā elkoņa, tad uz plaukstas; pacel gūžas tiltā; pabīdi taisno kāju zem sevis pusceļos; pieceļies. Darba roka visu laiku paliek vertikāla.","Stabila pozīcija pusceļos, bumba vertikāli virs pleca; tad pieceļies un kāp lejā apgrieztā secībā.","Dari lēni, pa vienam solim: pilns ceļš augšup un lejup parasti ir 12–20 s."],["Rokas, kas tur bumbu, saliekšana","skatiena novēršana no bumbas pirmajos soļos","pleca iekrīšana","steiga augšā stājā."],"Katrs solis tikai tik tālu, cik atbalsts ir stabils, bumbai paliekot vertikāli virs pleca."]},{"id":"med-ball-slam","name":"Бросок медбола об пол","group":"Пресс","meta":"gd|s","nameEn":"Medicine ball slam","nameLv":"Medbola mešana pret grīdu","lib":["Прямая мышца живота и широчайшие в фазе броска вниз.","Плечи; косые; ягодичные и ноги в разгибании перед броском.","Бросок мяча в пол. Нужен мяч, который не отскакивает в лицо."],"libEn":["Rectus abdominis and the lats during the downward throw.","Shoulders; obliques; glutes and legs as you extend before the throw.","Throws a medicine ball into the floor for a hard, fast brace of the trunk."],"libLv":["Taisnais vēdera muskulis un platie muguras muskuļi mešanas lejup laikā.","Pleci; slīpie; sēžas muskuļi un kājas, iztaisnojoties pirms metiena.","Met medbolu pret grīdu ātrai un stingrai korpusa savilkšanai."],"tech":[["Стоя, медбол двумя руками. Поднять мяч над головой с лёгким разгибанием, корпус длинный.","Мощно бросить мяч в пол перед собой, сгибаясь в тазу и корпусе. Руки сопровождают мяч вниз.","Мяч ударяется о пол; подобрать его для следующего повтора или выпрямиться."],["Бросок мячом, который сильно отскакивает (риск удара в лицо)","округление поясницы при броске","сильный прогиб поясницы на замахе."],"От мяча над головой до удара о пол перед стопами, поясница под контролем."],"techEn":[["Stand with the medicine ball in both hands. Raise it overhead with a slight lean back, body long.","Throw the ball hard into the floor in front of you, hinging at the hips and flexing the trunk. The arms follow the ball down.","The ball hits the floor; pick it up for the next rep, or stand tall."],["Throwing a ball that bounces hard (it can come back into the face)","rounding the lower back on the throw","a strong arch in the lower back on the wind-up."],"From the ball overhead to the hit on the floor in front of the feet, with the lower back under control."],"techLv":[["Stāvies ar medbolu abās rokās. Pacel to virs galvas ar vieglu atlieci, ķermenis garš.","Met bumbu spēcīgi grīdā sev priekšā, noliekoties gurnos un saliecot korpusu. Rokas pavada bumbu lejup.","Bumba atsitas pret grīdu; pacel to nākamajam atkārtojumam vai iztaisnojies."],["Mešana ar bumbu, kas stipri atlec (tā var trāpīt atpakaļ sejā)","jostasvietas apaļošana metienā","spēcīgs jostasvietas ieliekums aizvēzienā."],"No bumbas virs galvas līdz triecienam grīdā pēdu priekšā, ar jostasvietu kontrolē."]},{"id":"plate-pinch","name":"Щипок блинов","group":"Бицепс","meta":"g|","nameEn":"Plate pinch","nameLv":"Disku šķipsna","lib":["Мышцы большого пальца (длинный и короткий сгибатели, приводящая) и собственные мышцы кисти; сгибатели пальцев.","Предплечья в целом; плечо стабилизирует вис груза вдоль тела.","Удержание блина щипком для хвата."],"libEn":["Muscles of the thumb (flexor pollicis longus and brevis, adductor pollicis) and the intrinsic muscles of the hand; finger flexors.","The forearms overall; the shoulder steadies the load hanging beside the body.","Holds a smooth plate between the thumb and fingers to build pinch grip."],"libLv":["Īkšķa muskuļi (garais un īsais īkšķa saliecējs, īkšķa pievilcējs) un plaukstas iekšējie muskuļi; pirkstu saliecēji.","Apakšdelmi kopumā; plecs notur svaru, kas karājas gar ķermeni.","Tur gludu disku starp īkšķi un pirkstiem, lai veidotu šķipsnas tvērienu."],"tech":[["Стоя, один гладкий блин щипком: большой палец против остальных, рука вдоль тела.","Удержание щипка, плечо опущено. Блин не опирается на пальцы сверху как крюком (это уже обычный хват).","Контролируемо поставить блин на пол, не бросать на пальцы.","Статическое удержание."],["Крюковой хват за обод вместо щипка","бросать блин","пожимать плечом."],"Блин удерживается щипком на выпрямленной вдоль тела руке."],"techEn":[["Stand and pinch one smooth plate: thumb against the other fingers, arm alongside the body.","Hold the pinch with the shoulder down. The plate is not hanging on the fingers from above like a hook (that is an ordinary grip).","Set the plate on the floor under control. Do not drop it onto the fingers.","Static hold."],["A hook grip on the rim instead of a pinch","dropping the plate","shrugging the shoulder."],"The plate is pinched in a straight arm held alongside the body."],"techLv":[["Stāvies un saspied vienu gludu disku šķipsnā: īkšķis pret pārējiem pirkstiem, roka gar ķermeni.","Noturi šķipsnu ar nolaistu plecu. Disks nekarājas uz pirkstiem no augšas kā āķī (tas ir parasts tvēriens).","Noliec disku uz grīdas kontrolēti. Nemet to uz pirkstiem.","Statiska noturēšana."],["Āķa tvēriens aiz malas šķipsnas vietā","diska nomešana","pleca raustīšana."],"Disks turēts šķipsnā taisnā rokā gar ķermeni."]},{"id":"push-press","name":"Жимовой швунг","group":"Плечи","meta":"g|sp","nameEn":"Push press","nameLv":"Spiešanas švungs","lib":["Передние и средние дельты.","Трицепс; квадрицепс и ягодичные в подседе-разгибании; кор; верх груди.","Жим над головой с помощью короткого подседа."],"libEn":["Anterior and lateral deltoids.","Triceps; quadriceps and glutes in the dip and the drive; core; upper chest.","Uses a short drive from the legs to help press the bar overhead."],"libLv":["Priekšējie un vidējie deltveida.","Tricepss; četrgalvainais un sēžas muskuļi piepietupienā un atspērienā; korpuss; krūšu augšdaļa.","Izmanto īsu kāju atspērienu, lai palīdzētu izspiest stieni virs galvas."],"tech":[["Штанга на верхе груди, как в жиме штанги стоя. Стопы на ширине плеч, кор напряжён.","Небольшой подсед (четверть-присед) и сразу разгибание ног, которое передаёт импульс в жим рук. Гриф проходит лицо и уходит над головой.","Локти разогнуты над головой, ноги прямые. Опускание на грудь контролируемое."],["Ножницы ног как в толчке","прогиб поясницы","жим без помощи ног (это уже жим штанги стоя)","слишком глубокий подсед."],"От верха груди до полного разгибания над головой после помощи ног."],"techEn":[["Bar high on the chest, as in a standing barbell press. Feet at shoulder width, core braced.","A small dip (a quarter squat), then straighten the legs right away so that drive goes into the press. The bar passes the face and goes overhead.","Elbows extended overhead, legs straight. Lower to the chest under control."],["Splitting the feet the way a jerk does","arching the lower back","pressing with no help from the legs (that is already a standing barbell press)","a dip that is too deep."],"From high on the chest to full extension overhead, after the legs have helped."],"techLv":[["Stienis augstu uz krūtīm, kā stieņa spiešanā stāvus. Pēdas plecu platumā, korpuss sasprindzināts.","Neliels piepietupiens (ceturtdaļpietupiens), tad uzreiz iztaisno kājas, lai atspēriens ieietu spiešanā. Stienis iet gar seju un nonāk virs galvas.","Elkoņi iztaisnoti virs galvas, kājas taisnas. Nolaid uz krūtīm kontrolēti."],["Kāju šķēres kā grūdienā","jostasvietas ieliekums","spiešana bez kāju palīdzības (tā jau ir stieņa spiešana stāvus)","pārāk dziļš piepietupiens."],"No augstas pozīcijas uz krūtīm līdz pilnai iztaisnošanai virs galvas pēc kāju palīdzības."]},{"id":"broad-jump","name":"Прыжок в длину с места","group":"Ноги","meta":"gdb|k","nameEn":"Standing long jump","nameLv":"Tāllēciens no vietas","lib":["Ягодичные; квадрицепс.","Задняя поверхность; икры; кор.","Прыжок в длину с места. Мягкое приземление обязательно."],"libEn":["Glutes; quadriceps.","Hamstrings; calves; core.","Jumps forward from a stand and sticks the landing on both feet."],"libLv":["Sēžas muskuļi; četrgalvainais.","Augšstilba aizmugure; ikri; korpuss.","Lec uz priekšu no vietas un notur piezemēšanos uz abām pēdām."],"tech":[["Стопы на ширине бёдер, полуприсед, руки отведены назад.","Мах руками вперёд-вверх и взрывное разгибание, прыжок вперёд, не вверх как основная цель.","Мягкое приземление на обе стопы в четверть-присед, затем остановиться (не шагать вперёд сразу).","Один взрывной прыжок, затем остановка и стабилизация."],["Приземление на прямые ноги","колени внутрь","приземление с потерей баланса вперёд на руки."],"Приземление в четверть-присед на обе стопы, колени по носкам."],"techEn":[["Feet about hip width, a half squat, arms swung back.","Swing the arms forward and up and extend explosively. Jump forward; height is not the main goal.","Land softly on both feet in a quarter squat, then stop (do not step forward right away).","One explosive jump, then a stop while you steady yourself."],["Landing on straight legs","knees caving in","landing with balance lost forward onto the hands."],"Land in a quarter squat on both feet, knees tracking the toes."],"techLv":[["Pēdas aptuveni gurnu platumā, puspietupiens, rokas aizvēzētas atpakaļ.","Vēzē rokas uz priekšu un augšup un iztaisnojies sprādzienveidā. Lec uz priekšu; augstums nav galvenais mērķis.","Piezemējies mīksti uz abām pēdām ceturtdaļpietupienā, tad apstājies (nesper uz priekšu uzreiz).","Viens sprādzienveida lēciens, tad apstāšanās, kamēr nostabilizējies."],["Piezemēšanās uz taisnām kājām","ceļu iekrīšana uz iekšu","piezemēšanās, zaudējot līdzsvaru uz priekšu uz rokām."],"Piezemējies ceturtdaļpietupienā uz abām pēdām, ceļi virzienā uz pirkstiem."]},{"id":"air-bike","name":"Эйрбайк","group":"Кардио","meta":"g|","nameEn":"Air bike","nameLv":"Gaisa velotrenažieris","lib":["Квадрицепс и ягодичные; передние дельты и широчайшие на подвижных рукоятках.","Задняя поверхность; трицепс и грудь на жиме рукояток; кор.","Велотренажёр с вентилятором: ноги и руки вместе."],"libEn":["Quadriceps and glutes; anterior deltoids and lats on the moving handles.","Hamstrings; triceps and chest as you push the handles; core.","Drives the pedals and the handles together for full-body conditioning."],"libLv":["Četrgalvainais un sēžas muskuļi; priekšējie deltveida un platie muguras muskuļi uz kustīgajiem rokturiem.","Augšstilba aizmugure; tricepss un krūtis, spiežot rokturus; korpuss.","Dzen pedāļus un rokturus kopā visa ķermeņa kondīcijai."],"tech":[["Сидя на сиденье эйрбайка, стопы зафиксированы на педалях, руки на подвижных рычагах.","Одновременно крутить педали и толкать-тянуть рукоятки. Вентилятор создаёт сопротивление, растущее со скоростью.","Непрерывный цикл ног и рук.","Ровный или интервальный темп."],["Сутулая спина","работа только ногами без рук","удары коленями о руль."],"Полный круг педалей и полный ход рукояток без удара коленями."],"techEn":[["Sit on the air bike seat, feet fixed on the pedals, hands on the moving arms.","Pedal and push and pull the handles at the same time. The fan creates resistance that rises as you go faster.","A continuous cycle of the legs and the arms.","A steady pace, or intervals."],["A slouched back","using only the legs, without the arms","the knees hitting the handlebars."],"A full circle of the pedals and a full stroke of the handles, without the knees hitting anything."],"techLv":[["Sēdi gaisa velotrenažiera sēdeklī, pēdas fiksētas pedāļos, rokas uz kustīgajām svirām.","Min pedāļus un vienlaikus stum un velc rokturus. Ventilators rada pretestību, kas aug līdz ar ātrumu.","Nepārtraukts kāju un roku cikls.","Vienmērīgs temps vai intervāli."],["Sakumpusi mugura","darbs tikai ar kājām, bez rokām","ceļu sitieni pret stūri."],"Pilns pedāļu aplis un pilns rokturu gājiens, ceļiem ne pret ko neatsitoties."]},{"id":"ski-erg","name":"Лыжный эргометр","group":"Кардио","meta":"g|","nameEn":"Ski ergometer","nameLv":"Slēpošanas ergometrs","lib":["Широчайшие, трицепс и прямая мышца живота в тяге вниз.","Задняя поверхность и ягодичные в лёгком шарнире; плечи; кор.","Тяга вниз на лыжном эргометре."],"libEn":["Lats, triceps, and rectus abdominis in the downward pull.","Hamstrings and glutes in a light hinge; shoulders; core.","Pulls the handles down the way ski poles do, for upper-body conditioning."],"libLv":["Platie muguras muskuļi, tricepss un taisnais vēdera muskulis vilkmē lejup.","Augšstilba aizmugure un sēžas muskuļi vieglā noliekšanās; pleci; korpuss.","Velk rokturus lejup tā, kā to dara slēpošanas nūjas, ķermeņa augšdaļas kondīcijai."],"tech":[["Стоя лицом к лыжному эргометру, рукоятки вверху в руках, стопы на ширине бёдер.","Двойная тяга сверху вниз: шарнир в тазу, руки проводят рукоятки вдоль тела до бёдер, затем возврат вверх по инерции троса.","Непрерывные циклы, рукоятки не бросать."],["Только руки без шарнира","округление поясницы","вставание на носки с потерей баланса."],"От рукояток вверху до кистей у бёдер при нейтральной спине."],"techEn":[["Stand facing the ski ergometer, handles up in the hands, feet about hip width.","Pull both handles from high to low: hinge at the hips, drive the handles along the body to the hips, then let the cables' momentum bring them back up.","Keep the cycles going. Do not throw the handles."],["Arms only, with no hinge","rounding the lower back","rising onto the toes and losing balance."],"From the handles overhead to the hands at the hips, with a neutral back."],"techLv":[["Stāvies ar seju pret slēpošanas ergometru, rokturi augšā rokās, pēdas aptuveni gurnu platumā.","Velc abus rokturus no augšas uz leju: noliecies gurnos, dzen rokturus gar ķermeni līdz gurniem, tad ļauj tiem atgriezties augšup ar trošu inerci.","Turpini ciklus. Nemet rokturus."],["Tikai rokas, bez noliekšanās","jostasvietas apaļošana","pacelšanās uz pirkstgaliem un līdzsvara zaudēšana."],"No rokturiem virs galvas līdz plaukstām pie gurniem, ar neitrālu muguru."]},{"id":"pistol-squat","name":"Присед на одной ноге","group":"Ноги","meta":"gdb|k","nameEn":"Single-leg squat","nameLv":"Pietupiens uz vienas kājas","lib":["Квадрицепс опорной ноги; ягодичные.","Приводящие; задняя поверхность; икры; кор. Свободная нога — сгибатели бедра, чтобы удержать её впереди.","Присед на одной ноге. Для продвинутых."],"libEn":["Quadriceps of the standing leg; glutes.","Adductors; hamstrings; calves; core. The free leg uses the hip flexors to keep it out in front.","Squats on one leg while the other stays off the floor."],"libLv":["Atbalsta kājas četrgalvainais; sēžas muskuļi.","Pievilcēji; augšstilba aizmugure; ikri; korpuss. Brīvā kāja izmanto gūžas saliecējus, lai noturētu to priekšā.","Pietupjas uz vienas kājas, kamēr otra paliek nost no grīdas."],"tech":[["Стоя на одной ноге, свободная нога вытянута вперёд, руки перед собой для баланса.","Медленный присед на опорной ноге: таз назад-вниз, колено по носку, пятка на полу. Свободная нога не касается пола.","Внизу опорное бедро примерно параллельно полу или ниже, если позволяет контроль. Выход в стойку без отталкивания свободной ногой.","Вариант: Регрессия: держаться за опору или садиться на ящик."],["Завал колена внутрь","отрыв пятки","падение на свободную ногу","округление поясницы внизу через боль."],"До той глубины, где пятка на полу и спина контролируема, обычно около параллели или ниже."],"techEn":[["Stand on one leg, the free leg extended forward, arms in front of you for balance.","Squat slowly on the standing leg: hips back and down, knee tracking the toes, heel on the floor. The free leg does not touch the floor.","At the bottom the standing thigh is about parallel to the floor, or lower if you can still control it. Stand up without pushing off the free leg.","Variation: An easier version: hold a support, or sit down to a box."],["The knee collapsing inward","the heel lifting","falling onto the free leg","rounding the lower back at the bottom through pain."],"Only as deep as the heel stays down and the back stays under control, usually around parallel or below."],"techLv":[["Stāvies uz vienas kājas, brīvā kāja izstiepta uz priekšu, rokas priekšā līdzsvaram.","Pietupies lēni uz atbalsta kājas: gūžas atpakaļ un lejup, celis virzienā uz pirkstiem, papēdis uz grīdas. Brīvā kāja nepieskaras grīdai.","Apakšā atbalsta augšstilbs ir aptuveni paralēli grīdai vai zemāk, ja to vēl vari kontrolēt. Pieceļies, neatspiežoties ar brīvo kāju.","Variants: Vieglāks variants: turi atbalstu vai sēdies uz boksa."],["Ceļa iekrīšana uz iekšu","papēža atraušanās","krišana uz brīvās kājas","jostasvietas apaļošana apakšā caur sāpēm."],"Tikai tik dziļi, cik papēdis paliek uz grīdas un mugura paliek kontrolē, parasti ap paralēli vai zemāk."]},{"id":"cru-machine","name":"Скручивания в тренажёре","group":"Пресс","meta":"g|","nameEn":"Machine crunches","nameLv":"Vēdera preses saliekšana trenažierī","lib":["Прямая мышца живота.","Косые.","Скручивание в тренажёре с небольшой амплитудой."],"libEn":["Rectus abdominis.","Obliques.","Curls the trunk a short way against a pad."],"libLv":["Taisnais vēdera muskulis.","Slīpie.","Saliec korpusu īsu ceļu pret polsteri."],"tech":[["Сидя в тренажёре для скручиваний, подушка на верхней груди или плечах, стопы на подставках.","Сгибание корпуса в грудном отделе против сопротивления, без рывка руками.","Короткая пауза, контролируемый возврат."],["Тяга руками","инерция","сильный отрыв поясницы, если конструкция это допускает."],"Небольшая амплитуда сгибания корпуса, бережно к пояснице."],"techEn":[["Sit in the crunch machine, the pad on the upper chest or the shoulders, feet on the footrests.","Flex the trunk through the thoracic spine against the resistance, without yanking with the arms.","A short pause, then a controlled return."],["Pulling with the arms","using momentum","lifting the lower back hard, if the machine allows it."],"A small range of trunk flexion, gentle on the lower back."],"techLv":[["Sēdi vēdera preses trenažierī, polsteris uz krūšu augšdaļas vai pleciem, pēdas uz pēdu balstiem.","Saliec korpusu caur krūšu mugurkaulu pret pretestību, neraujot ar rokām.","Īsa pauze, tad kontrolēta atgriešanās."],["Vilkšana ar rokām","inerces izmantošana","jostasvietas stipra atraušana, ja trenažieris to pieļauj."],"Neliela korpusa saliekšanas amplitūda, saudzīga pret jostasvietu."]}];
const NO_ANIM = new Set(NEW_CARDS.map(c=>c.id));
const LIB_ONLY = new Set(["box-jump","jump-squat","broad-jump","kettlebell-swing","med-ball-slam","push-press","turkish-getup","kb-windmill","pistol-squat","standing-ab-wheel","copenhagen-plank","ankle-knee-to-wall","open-book","worlds-greatest-stretch","inchworm","deep-squat-hold","lateral-lunge-bw","wrist-mobility","stretch-hip-flexor","stretch-chest-doorway","stretch-hamstring","stretch-glute-figure4","stretch-calf","cable-external-rotation","cable-internal-rotation","cable-external-rotation-90","cuban-press","wall-slide","neck-retraction","neck-flexion-extension","tibialis-raise","plate-pinch","dead-hang"]);
