const EX_MIN = {"tbar-row":1,"reverse-lunge":1,"single-leg-press":1,"standing-db-press":1,"smith-close-grip":1,"smith-rdl":1,"smith-row":1,"reverse-hyper":1,"decline-db-press":1,"hanging-knee-raise":1,"sl-rdl":1,"pendlay-row":2,"plank-advanced":1,"smith-upright-row":1,"smith-bss":1,"single-arm-cable-lateral":1,"incline-db-curl":1,"pallof-press":1,"farmers-walk":1,"suitcase-carry":1,"woodchop":1,"landmine-press":1,"jump-rope":1,"air-bike":1,"ski-erg":1,"sled-push":1,"wrist-curl":1,"reverse-wrist-curl":1,"meadows-row":2};
