const EXTRA_CARDIO = ['jump-rope','air-bike','ski-erg'];
const LVRANK = {nov:0,mid:1,adv:2};
function autoOk(id,a){if(LIB_ONLY.has(id)||FINISHER.has(id))return false;const g=GEAR[id];if(g&&!((a&&a.gear)||[]).includes(g))return false;const need=EX_MIN[id]||0;const lv=LVRANK[(a&&a.level)||'mid'];if(lv==null||lv<need)return false;return true}
function finisherFor(a,used,off){if(!a||a.level==='nov'||a.place==='b')return null;const ids=['wrist-curl','reverse-wrist-curl'];let i=Math.abs(off||0)%2;if(used.has(ids[i]))i=1-i;return used.has(ids[i])?null:ids[i]}
NEW_CARDS.forEach(c=>{EX.push({id:c.id,name:c.name,group:c.group});META[c.id]=c.meta;LIB[c.id]=c.lib;TECH[c.id]=c.tech;LIB_EN[c.id]=c.libEn;LIB_LV[c.id]=c.libLv;TECH_EN[c.id]=c.techEn;TECH_LV[c.id]=c.techLv;DICT.push([c.name,c.nameEn,c.nameLv])});
const SLOT_ADD = {"HPUSH":["smith-bench","decline-db-press","band-chest-press"],"IPUSH":["mch-incline","smith-incline-bench"],"CHEST2":["pec-deck","incline-db-fly"],"VPUSH":["smith-seated-press","standing-db-press","landmine-press"],"SIDE":["single-arm-cable-lateral","smith-upright-row"],"REAR":["reverse-pec-deck"],"HPULL":["chest-supported-2db","chest-supported-1db","tbar-row","smith-row","pendlay-row","meadows-row","smith-shrug"],"VPULL":["close-pulldown","straight-arm-pulldown","assisted-pullup","negative-pullup"],"SQ":["hack-squat","smith-squat"],"HINGE":["smith-rdl","sl-rdl","reverse-hyper","farmers-walk","sled-push"],"LUNGE":["reverse-lunge-supported","reverse-lunge","smith-split-squat","smith-bss","single-leg-press"],"LEGISO":["lc-seated","standing-single-leg-curl","hip-abduction","hip-adduction","smith-hip-thrust"],"CALF":["seated-calf","smith-calf"],"BI":["concentration-curl","incline-db-curl"],"TRI":["tpd-rope","cable-overhead-extension","smith-close-grip"],"CORE":["cru-machine","cable-crunch","plank-advanced","pallof-press","hanging-knee-raise","suitcase-carry","woodchop"]};
const SLOT_HEAD = {"HPUSH":"smith-bench","IPUSH":"mch-incline","CHEST2":"pec-deck","VPUSH":"smith-seated-press","SIDE":"single-arm-cable-lateral","REAR":"reverse-pec-deck","HPULL":"chest-supported-2db","VPULL":"close-pulldown","SQ":"hack-squat","HINGE":"smith-rdl","LUNGE":"reverse-lunge-supported","LEGISO":"lc-seated","CALF":"seated-calf","BI":"concentration-curl","TRI":"tpd-rope","CORE":"cru-machine"};
Object.keys(SLOT_ADD).forEach(slot=>{const ids=SLOT_ADD[slot], head=SLOT_HEAD[slot], arr=SLOT[slot][0];const rest=ids.filter(id=>id!==head);if(head&&!arr.includes(head))arr.splice(Math.min(1,arr.length),0,head);rest.forEach(id=>{if(!arr.includes(id))arr.push(id)})});
const SAFE_ADD = {"HPUSH":["smith-bench","band-chest-press"],"IPUSH":["mch-incline"],"SQ":["hack-squat","smith-squat"],"VPULL":["assisted-pullup","close-pulldown"],"HPULL":["chest-supported-2db","chest-supported-1db"],"CALF":["seated-calf","smith-calf"],"CORE":["cru-machine","cable-crunch"],"TRI":["tpd-rope"],"LUNGE":["reverse-lunge-supported"]};
Object.keys(SAFE_ADD).forEach(slot=>{const arr=SLOT[slot][1];SAFE_ADD[slot].forEach(id=>{if(!arr.includes(id))arr.push(id)})});
